	["강호 곳곳에 흩어진 비급 조각 다섯을 모두 모은 자만이 익힌다"] = "Only those who collect all five scattered manual fragments can learn it",
	["끝도 시작도 없는 권. 모든 권법이 하나로 돌아가는 자리. 손이 닿기도 전에 상대의 균형이 무너진다."] = "A fist with no end and no beginning, where all styles return to one. Your foe's balance breaks before your hand lands.",
	["무극: 모든 타격이 상대 균형을 두 배로 깎고, 흘리기 판정이 넓다"] = "Limitless: every hit wears balance twice as fast, and the deflect window is wide",
	["허공수"] = "Void Hand",
	["역류수"] = "Reverse Current Hand",
	["환원장"] = "Return Palm",
	["귀일장"] = "Unity Palm",
	["무극장"] = "Limitless Palm",
	["음양탄"] = "Yin-Yang Orbs",
	["두 손을 맞댔다가 밀어낸다. 검은 구슬과 흰 구슬이 서로 감아 돌며 앞으로 날아가 길의 적을 치고, 끝에서 부딪쳐 둘레의 적을 빨아들이며 터진다"] = "Press your palms together and push. A black orb and a white orb spiral forward, hit enemies on the way, then collide at the end, pulling in nearby enemies as they burst",
	["태극선회"] = "Taiji Whirl",
	["제자리에서 원을 그린다. 검은 구슬과 흰 구슬이 나를 축으로 소용돌이치며 16칸까지 퍼졌다가 되돌아오고, 돌아올 때 둘레의 적을 내 앞으로 끌어 모아 한 번 더 친다"] = "Draw a circle in place. Black and white orbs swirl around you out to 16 studs and back, dragging nearby enemies in front of you for one more hit",
	["태극인"] = "Taiji Seal",
	["세상의 빛깔이 빠지고 발밑에 30칸 넓이의 태극이 그려진다. 그 위의 적은 모두 멈춘다. 태극이 돌며 하늘로 떠올라 뒤집힌 뒤 도장처럼 내리찍고, 흑과 백의 물결이 한 번 더 지나간다"] = "The world loses its color and a 30-stud Taiji forms underfoot. Enemies on it freeze. It spins, rises, flips and stamps down like a seal, then a wave of black and white passes once more",
	["혈마신수"] = "Blood Demon Hand",
	["절세"] = "Peerless",
	["혈교의 주인 혈마를 쓰러뜨린 자에게 그 손이 넘어간다"] = "Defeat the Blood Demon, master of the Blood Cult, and his hand is yours",
	["혈교의 주인이 쓰던 마공. 손톱 끝에 피의 기운이 맺힌다. 베어 낸 만큼 내 몸이 살아난다."] = "The demonic art of the Blood Cult's master. Blood ki gathers at your nails. What you cut heals you.",
	["흡혈: 준 피해의 2%만큼 체력을 되찾는다 (한 번에 최대 체력의 1.5%, 1초에 4%까지)"] = "Lifesteal: heal 2% of damage dealt (max 1.5% of max HP per hit; per 1s up to 4%)",
	["혈조"] = "Blood Claw",
	["역조"] = "Reverse Claw",
	["혈영수"] = "Blood Shadow Hand",
	["혈마조"] = "Blood Demon Claw",
	["혈수천강"] = "Blood Hand Descends",
	["혈영보"] = "Blood Shadow Step",
	["피의 그림자가 되어 적을 꿰뚫고 지나간다 (무적)"] = "Become a blood shadow and pass through enemies (invincible)",
	["혈해"] = "Sea of Blood",
	["발밑에 피의 바다를 4초 펼친다. 안의 적을 계속 베고, 벨 때마다 내 체력이 돌아온다"] = "Spread a sea of blood underfoot for 4s. It keeps cutting enemies inside, and each cut heals you",
	["혈마강림"] = "Blood Demon Descends",
	["등 뒤로 거대한 혈마의 허상이 솟아 손톱으로 적들을 네 번 찢고 포효한다. 그 뒤 8초 광란 (동작 ×1.2, 흡혈 1.5배)"] = "A giant Blood Demon rises behind you, tears enemies four times with its claws and roars. Then 8s of frenzy (speed x1.2, lifesteal x1.5)",
	["천제신권"] = "Heavenly Emperor Fist",
	["생사경에 오른 자만이 이름 없는 노인을 만난다. 강호의 끝, 아무도 가지 않는 구석에서"] = "Only those at Life & Death meet the nameless old man, in a corner at the end of the world nobody visits",
	["하늘의 임금이 땅에 남긴 주먹. 손이 닿는 곳마다 하늘의 검이 따라 내린다. 이 권을 쓰는 자의 머리 위로는 늘 하늘의 문이 열려 있다."] = "The fist the Emperor of Heaven left on earth. Wherever it lands, heavenly swords follow. Above its wielder, the gate of heaven is always open.",
	["천위: 다섯 번 맞힐 때마다 하늘에서 빛의 검이 떨어져 둘레를 친다. 흘리기 판정이 넓고 균형을 1.5배로 깎는다"] = "Heavenly Might: every five hits a sword of light falls and strikes the area. Wide deflect window, balance damage x1.5",
	["천제권"] = "Emperor Fist",
	["역천권"] = "Defy Heaven Fist",
	["천월각"] = "Heaven Moon Kick",
	["천광장"] = "Heaven Light Palm",
	["천검일섬"] = "Heaven Sword Flash",
	["천검강림"] = "Heaven Sword Descends",
	["둘레의 적 셋 위로 하늘에서 빛의 검을 꽂는다"] = "Drive swords of light down onto three nearby enemies",
	["천제의 창"] = "Emperor's Spear",
	["등 뒤에 하늘의 문이 열리고, 빛의 창이 앞으로 한 줄 쏟아져 꿰뚫는다"] = "The gate of heaven opens behind you and a spear of light pours forward in a line",
	["만검천벌"] = "Ten Thousand Swords Judgment",
	["하늘이 열려 천 자루의 빛의 검이 내려다본다. 적마다 검이 꽂히고, 마지막에 거대한 하늘의 검이 내리꽂혀 터진다"] = "The sky opens and a thousand swords of light look down. A sword pierces each enemy, then a giant heavenly sword slams down and explodes",
	["파천신권"] = "Sky-Breaking Divine Fist",
	["강호의 마지막 적, 천마를 쓰러뜨려야 그 마공을 거꾸로 익힐 수 있다"] = "Defeat the Heavenly Demon, the last foe of the martial world, to learn his art in reverse",
	["천마의 마공을 꺾어 거꾸로 익힌 주먹. 주먹이 닿는 곳의 무게가 열 배가 되고, 마지막에는 하늘에 검은 해를 띄워 모든 것을 끌어당겨 으스러뜨린다."] = "A fist that turned the Heavenly Demon's art against itself. Where it lands, weight becomes tenfold, and at the end a black sun rises to crush everything it pulls in.",
	["중압: 여섯 번 맞힐 때마다 상대 자리에 중력 우물이 열려 둘레의 적을 끌어당겨 바닥에 짓누른다. 맞힌 적은 잠깐 느려진다"] = "Pressure: every six hits a gravity well opens at the target, pulling nearby enemies in and pinning them down. Enemies hit are briefly slowed",
	["중력 우물"] = "Gravity Well",
	["중력권"] = "Gravity Fist",
	["역중권"] = "Reverse Gravity Fist",
	["천근각"] = "Thousand-Pound Kick",
	["추성장"] = "Falling Star Palm",
	["흑성추"] = "Black Star Hammer",
	["인력장"] = "Pull Palm",
	["앞에 중력 우물을 연다. 1.2초 동안 둘레의 적을 한가운데로 빨아들이며 짓누른다"] = "Open a gravity well ahead. For 1.2s it sucks nearby enemies to the center and crushes them",
	["천근추"] = "Thousand-Pound Drop",
	["가장 가까운 적 위로 몸이 천 근 무게가 되어 떨어진다. 떨어진 자리가 움푹 꺼진다"] = "Become a thousand-pound weight and drop onto the nearest enemy. The ground caves in where you land",
	["흑일강림"] = "Black Sun Descends",
	["주먹으로 하늘을 찢어 검은 해를 띄운다. 검은 해가 둘레의 모든 적을 하늘로 끌어올려 짓이기고, 마지막에 안으로 무너지며 터진다"] = "Tear the sky with your fist and raise a black sun. It lifts every nearby enemy into the sky, grinds them, then collapses inward and explodes",
	["태초신권"] = "Genesis Divine Fist",
	["태초"] = "Genesis",
	["무극의 경지에 오른 자만이 하늘 끝 봉우리, 천외봉의 시원자를 만난다"] = "Only those at Limitless meet the Origin Sage of the Beyond Peak, at the edge of the sky",
	["하늘과 땅이 갈라지기 전, 세상이 처음 열리던 그 한순간을 담은 주먹. 이 권을 쓰는 자는 땅을 딛지 않고 떠 있으며, 마지막 한 주먹에 세상이 유리처럼 깨졌다가 다시 맞춰진다."] = "A fist that holds the single moment the world first opened, before heaven and earth parted. Its wielder floats above the ground, and the final blow shatters the world like glass before it reassembles.",
	["창세: 네 번 맞힐 때마다 상대 자리에 빛의 결정이 피어나 터진다. 모든 기술 대기 20% 짧음, 몸이 땅에서 떠 있다"] = "Creation: every four hits a crystal of light blooms and bursts at the target. All skill cooldowns 20% shorter, and you float above the ground",
	["창세 결정"] = "Creation Crystal",
	["일원장"] = "One Origin Palm",
	["양의장"] = "Two Forms Palm",
	["사상권"] = "Four Images Fist",
	["개천일권"] = "Sky-Opening Strike",
	["성운보"] = "Nebula Step",
	["빛이 되어 둘레의 적 사이를 다섯 번 건너뛰며 친다 (그동안 무적)"] = "Become light and leap between nearby enemies five times, striking each (invincible meanwhile)",
	["창세주"] = "Creation Pillar",
	["둘레의 적 다섯 아래에서 빛의 결정 기둥이 솟아 하늘로 띄운다"] = "Crystal pillars of light rise under five nearby enemies and launch them skyward",
	["천지개벽"] = "Heaven and Earth Split",
	["세상이 멈추고 하늘과 땅이 별바다로 바뀐다. 주먹을 쥐면 세상에 금이 가고, 내지르면 세상이 유리처럼 깨지며 모든 적이 함께 부서진다"] = "The world stops and sky and earth turn into a sea of stars. Clench your fist and the world cracks; strike and it shatters like glass, breaking every enemy with it",
	["일월신권"] = "Sun-Moon Divine Fist",
	["지존"] = "Supreme",
	["태초신권을 익힌 무극의 고수만이 세상 동남쪽 끝 일월대에서 권존을 만난다"] = "Only a Limitless master who knows the Genesis Fist meets the Fist Sovereign on the Sun-Moon Altar at the far southeast",
	["권법의 정점. 오른손에 해를, 왼손에 달을 쥐었다. 낮에는 해처럼 태우고 밤에는 달처럼 베며, 마지막 한 수에 해와 달을 하나로 겹쳐 하늘을 일식으로 덮는다."] = "The summit of all styles. The sun in the right hand, the moon in the left. Burns like the sun by day, cuts like the moon by night, and in the final move the two overlap into an eclipse.",
	["일월: 세 번 맞힐 때마다 해와 달이 번갈아 떨어진다 (해는 터지고, 달은 벤다). 낮에는 주는 피해 +15%, 밤에는 받는 피해 -15%. 모든 기술 대기 25% 짧음"] = "Sun-Moon: every three hits the sun and moon fall in turn (the sun explodes, the moon cuts). By day damage dealt +15%, by night damage taken -15%. All skill cooldowns 25% shorter",
	["일월"] = "Sun-Moon",
	["일출장"] = "Sunrise Palm",
	["월하장"] = "Moonlight Palm",
	["일륜각"] = "Sun Wheel Kick",
	["월인권"] = "Moon Seal Fist",
	["일월합벽"] = "Sun-Moon Union",
	["만월참"] = "Full Moon Cut",
	["보름달만 한 빛의 초승달을 던진다. 앞의 모든 적을 꿰뚫고 벤다"] = "Throw a crescent of light as big as a full moon. It pierces and cuts every enemy ahead",
	["대일강림"] = "Great Sun Descends",
	["둘레의 적 여섯 머리 위로 작은 해가 떨어져 불기둥이 되어 터진다"] = "Small suns fall on six nearby enemies and burst into pillars of fire",
	["일월동천"] = "Sun and Moon Together",
	["하늘이 밤이 되고 해와 달이 함께 떠오른다. 달빛이 둘레를 베고, 해와 달이 겹쳐 일식이 되면 검은 해의 빛살이 모든 적을 꿰뚫은 뒤, 새벽처럼 터진다"] = "The sky turns to night and the sun and moon rise together. Moonlight cuts the area, the two overlap into an eclipse, rays of the black sun pierce every enemy, then it bursts like dawn",
	["창해신권"] = "Azure Sea Divine Fist",
	["끝없는 바다를 두 손에 담은 권법. 태허유수권이 받아 흘리는 물이라면, 창해신권은 밀려와 모든 것을 삼키는 파도다. 한 번 밀리기 시작하면 끝까지 쓸려 간다."] = "A style that holds the endless sea in two hands. If Flowing Water receives and redirects, Azure Sea is the wave that rolls in and swallows everything. Once pushed, you're swept to the end.",
	["파도: 네 번 맞힐 때마다 상대 자리에서 물기둥이 솟아 둘레를 쓸어 낸다. 모든 공격의 밀어냄 1.3배"] = "Waves: every four hits a water pillar rises at the target and sweeps the area. All knockback x1.3",
	["파도"] = "Waves",
	["파랑장"] = "Billow Palm",
	["역랑장"] = "Backwash Palm",
	["소용돌이각"] = "Whirlpool Kick",
	["해일권"] = "Tsunami Fist",
	["노도격"] = "Raging Wave Strike",
	["파도타기"] = "Wave Ride",
	["파도를 타고 앞으로 미끄러지며 꿰뚫는다 (무적). 지나간 길에 물보라가 솟아 터진다"] = "Slide forward on a wave, piercing through (invincible). Spray bursts along your path",
	["해일벽"] = "Tsunami Wall",
	["앞으로 물의 벽이 차례로 솟아 한 줄을 휩쓸고, 맞은 적을 멀리 밀어낸다"] = "Walls of water rise ahead one after another, sweeping a line and pushing enemies far away",
	["창해일소"] = "Azure Sea Sweep",
	["등 뒤의 바다가 일어선다. 하늘을 가리는 해일이 앞으로 밀려가며 모든 적을 휩쓸어 끌고 가고, 마지막에 부서지며 거대한 소용돌이가 된다"] = "The sea behind you stands up. A sky-high tsunami rolls forward dragging every enemy, then breaks into a giant whirlpool",
	["영겁신권"] = "Eternity Divine Fist",
	["태초신권을 익힌 무극의 고수만이 북서쪽 끝 천 개의 계단 위, 떠 있는 문 앞에서 영겁노인을 만난다"] = "Only a Limitless master who knows the Genesis Fist meets the Eternal Elder before the floating gate atop the thousand stairs in the far northwest",
	["시간을 쥔 주먹. 맞은 자의 시간이 멎고, 지나간 주먹이 메아리처럼 되돌아와 다시 친다. 마지막 한 수에 하늘에 거대한 해시계가 열리고 열두 번의 종이 울린다."] = "A fist that holds time. Time stops for those it hits, and past blows echo back to strike again. The final move opens a giant sundial in the sky and a bell tolls twelve times.",
	["정지: 다섯 번 맞힐 때마다 상대 둘레의 시간이 1.4초 멎고 메아리가 친다. 모든 기술 대기 30% 짧음, 동작 +10%"] = "Stop: every five hits time stops around the target for 1.4s and an echo strikes. All skill cooldowns 30% shorter, action speed +10%",
	["시간 정지"] = "Time Stop",
	["찰나장"] = "Instant Palm",
	["순간장"] = "Moment Palm",
	["회귀각"] = "Rewind Kick",
	["정시권"] = "Still Time Fist",
	["영겁일격"] = "Eternal Strike",
	["역행보"] = "Reverse Step",
	["앞으로 꿰뚫고 지나간 뒤 (무적), 0.6초 뒤 시간이 거꾸로 돌아 제자리로 되돌아오며 지나온 길의 적을 다시 벤다"] = "Pierce forward (invincible), then 0.6s later time rewinds and you return to your spot, cutting enemies on the path again",
	["정지된 시간"] = "Frozen Time",
	["앞에 시간이 멎은 구역을 2초 연다. 안의 적은 꼼짝 못 하고 째깍일 때마다 베인다"] = "Open a zone of stopped time ahead for 2s. Enemies inside can't move and are cut with every tick",
	["만겁귀환"] = "Return of Ages",
	["하늘에 거대한 해시계가 열리고 시곗바늘이 거꾸로 돈다. 둘레의 모든 적의 시간이 멎고, 열두 번의 종이 울릴 때마다 베이며, 자정에 시간이 깨진다"] = "A giant sundial opens in the sky and its hand turns backward. Time stops for every nearby enemy, they're cut each time the bell tolls twelve, and at midnight time shatters",
	["열화신권"] = "Blazing Fire Divine Fist",
	["타오르는 불꽃을 주먹에 담았다. 맞은 자는 불이 붙어 계속 타고, 불붙은 적에게 꽂는 강타는 터진다."] = "A fist that holds a burning flame. Those it hits keep burning, and a heavy strike on a burning enemy explodes.",
	["연소: 맞힌 적이 3초 동안 불탄다 (0.5초마다 피해). 불타는 적에게 강타(Z)를 꽂으면 폭발해 둘레까지 태운다"] = "Burn: enemies hit burn for 3s (damage every 0.5s). A heavy strike (Z) on a burning enemy explodes and burns the area",
	["화염장"] = "Flame Palm",
	["염조권"] = "Flame Claw Fist",
	["화륜각"] = "Fire Wheel Kick",
	["열화권"] = "Blazing Fist",
	["폭염추"] = "Blast Hammer",
	["화룡보"] = "Fire Dragon Step",
	["불길이 되어 앞으로 꿰뚫고 지나간다 (무적). 지나간 길에 불기둥이 솟는다"] = "Become flame and pierce forward (invincible). Fire pillars rise along your path",
	["염화폭풍"] = "Flame Storm",
	["앞쪽 부채꼴로 불길을 1.2초 동안 내뿜는다 (맞은 적은 불탄다)"] = "Breathe fire in a cone ahead for 1.2s (enemies hit burn)",
	["열화천멸"] = "Blazing Annihilation",
	["땅이 갈라져 용암이 둘레의 모든 적 발밑으로 흐르고, 적마다 불기둥이 솟는다. 마지막에 내 자리에서 화산이 터진다"] = "The ground splits and lava flows under every nearby enemy, raising a fire pillar on each. At the end a volcano erupts where you stand",
	["무쌍신권"] = "Peerless Divine Fist",
	["신화"] = "Mythic",
	["배틀그라운드에서 백 명을 쓰러뜨린 자만이 강호 제일의 비무 권법을 얻는다"] = "Only those who defeat one hundred players in the Battleground gain the martial world's finest dueling style",
	["배틀그라운드에서 백 명을 쓰러뜨린 자의 주먹. 화려함 없이 오직 상대를 꺾는 데만 다듬어졌다. 적을 쓰러뜨릴 때마다 숨이 돌아온다."] = "The fist of one who has defeated a hundred in the Battleground. No flourish, honed only to beat opponents. Each takedown restores your breath.",
	["무쌍: 사람을 상대로 주는 피해 +20%. 적을 쓰러뜨릴 때마다 체력 10%와 내공 20을 되찾는다. 흘리기 판정이 넓다"] = "Peerless: +20% damage against players. Each takedown restores 10% HP and 20 Ki. Wide deflect window",
	["선수"] = "First Hand",
	["결수"] = "Finishing Hand",
	["회선퇴"] = "Spinning Kick",
	["단수"] = "Cutting Hand",
	["필살권"] = "Killing Fist",
	["일기당천"] = "One Against a Thousand",
	["번개처럼 파고들며 앞의 적을 모두 베고 지나간다 (무적)"] = "Dart in like lightning and cut through every enemy ahead (invincible)",
	["무쌍난무"] = "Peerless Flurry",
	["제자리에서 사방으로 주먹과 발을 퍼붓는다 (1.2초)"] = "Unleash fists and kicks in every direction (1.2s)",
	["천하무쌍"] = "Unrivaled Under Heaven",
	["빛의 울타리가 둘레를 가두고 모든 적을 한가운데로 끌어당긴다. 여덟 번 몰아친 뒤 마지막 한 주먹으로 하늘 높이 쳐올린다"] = "A fence of light traps the area and pulls every enemy to the center. Eight blows, then a final fist launches them high into the sky",
	["아공신권"] = "Subspace Divine Fist",
	["천상계 어딘가, 허공에 금이 간 작은 섬. 보이지 않는 다리를 건넌 반선의 고수만이 아공선인을 만난다"] = "Somewhere in the Heavenly Realm lies a small island where the air is cracked. Only a Half-Immortal master who crosses the invisible bridge meets the Subspace Sage",
	["공간의 틈에 사는 노인의 주먹. 주먹이 닿는 곳마다 공간이 접히고, 오의를 펼치면 그 자리에 바깥과 끊긴 공간이 열린다."] = "The fist of an old man who lives in the cracks of space. Space folds wherever it lands, and its secret art opens a space cut off from the outside.",
	["틈새: 뒤에서 치면 1.4배. 기술 대기 15% 짧고, 회피를 두 번 이어 쓴다"] = "Rift: 1.4x from behind. Skill cooldowns 15% shorter, and you can dodge twice in a row",
	["접은 손"] = "Folded Hand",
	["틈새 손"] = "Rift Hand",
	["공간 돌려차기"] = "Space Roundhouse",
	["허공 원장"] = "Void Round Palm",
	["공간 밀치기"] = "Space Shove",
	["공간 접기"] = "Space Fold",
	["공간을 접어 가장 가까운 적의 등 뒤로 나타나 친다 (치명타)"] = "Fold space and appear behind the nearest enemy to strike (critical)",
	["공간 균열"] = "Space Rift",
	["앞의 공간을 찢어 1.5초 동안 둘레의 적을 빨아들이며 벤다"] = "Tear the space ahead, pulling in and cutting nearby enemies for 1.5s",
	["아공간"] = "Subspace",
	["그 자리에 바깥과 끊긴 공간을 연다. 10초 동안 안의 적은 빠져나가지 못하고, 사방에서 공간이 베어 든다. 마지막에 공간이 닫히며 터진다"] = "Open a space cut off from the outside. For 10s enemies inside can't escape and are cut from all sides. At the end the space closes and explodes",
	["운류장"] = "Drifting Cloud Palm",
	["상급"] = "Advanced",
	["구름이 흐르듯 손바닥을 밀어 적을 흩어 놓는다. 세지는 않지만 몸이 가볍고 빠져나가기 좋다."] = "Push palms like flowing clouds to scatter enemies. Not strong, but light on your feet and good for escaping.",
	["구름 걸음: 회피를 두 번 이어 쓰고, 흘리기 판정이 넓다. 손바닥은 적을 멀리 밀어낸다"] = "Cloud Step: dodge twice in a row, wide deflect window. Palms push enemies far away",
	["운수장"] = "Cloud Water Palm",
	["류수장"] = "Flowing Stream Palm",
	["회운장"] = "Circling Cloud Palm",
	["추운장"] = "Chasing Cloud Palm",
	["쌍운장"] = "Twin Cloud Palm",
	["운보"] = "Cloud Step",
	["구름을 밟듯 앞으로 미끄러지며 지나가는 적을 친다 (무적)"] = "Glide forward as if on clouds, hitting enemies you pass (invincible)",
	["운해장"] = "Sea of Clouds Palm",
	["앞에 구름 소용돌이를 펼쳐 1초 동안 둘레의 적을 친다"] = "Spread a cloud vortex ahead, hitting nearby enemies for 1s",
	["만리운해"] = "Endless Sea of Clouds",
	["발밑에서 구름 바다가 넓게 퍼져 2초 동안 둘레의 모든 적을 친다"] = "A sea of clouds spreads wide underfoot, hitting every nearby enemy for 2s",
	["성하신권"] = "Starry River Divine Fist",
	["천상계 성운원의 가장 깊은 곳, 성군의 등 뒤에서 별을 헤아리는 노인. 등선에 오른 자에게만 별의 길을 보여 준다"] = "In the deepest part of the Nebula Garden, behind the Star Lord, an old man counts the stars. He shows the path of stars only to those at Ascension",
	["별의 강을 주먹에 담았다. 주먹이 닿는 곳마다 별빛이 흩어지고, 오의를 펼치면 머리 위에 은하가 열려 별이 쏟아진다."] = "A fist that holds the river of stars. Starlight scatters wherever it lands, and its secret art opens a galaxy overhead that rains stars.",
	["성하: 균형을 1.5배로 깎고, 기술 대기 20% 짧다"] = "Starry River: balance damage x1.5, skill cooldowns 20% shorter",
	["성권"] = "Star Fist",
	["월권"] = "Moon Fist",
	["은하장"] = "Galaxy Palm",
	["천성각"] = "Heavenly Star Kick",
	["유성추"] = "Meteor Hammer",
	["유성 돌진"] = "Meteor Charge",
	["유성처럼 꼬리를 끌며 돌진해 앞의 적을 꿰뚫는다 (무적)"] = "Charge like a meteor trailing its tail, piercing enemies ahead (invincible)",
	["은하 소용돌이"] = "Galaxy Vortex",
	["둘레에 별의 소용돌이를 일으켜 1.4초 동안 적을 빨아들이며 친다"] = "Raise a vortex of stars around you, pulling in and hitting enemies for 1.4s",
	["성하강림"] = "Starry River Descends",
	["머리 위에 은하가 열리고, 별이 나선을 그리며 스물네 번 쏟아진 뒤 한가운데에서 별이 터진다"] = "A galaxy opens overhead and stars spiral down twenty-four times, then a star bursts at the center",
	["풍신각"] = "Wind God Kick",
	["최상급"] = "Superior",
	["바람을 차는 다리. 잡을 수도 막을 수도 없는 바람처럼 들어갔다 빠진다. 발끝이 지나간 자리에 바람의 칼이 남는다."] = "Legs that kick the wind. In and out like wind that can't be caught or blocked. Blades of wind linger where your feet pass.",
	["질풍: 대시 대기가 짧고(0.6초), 발차기가 바람을 일으켜 더 멀리 날린다 (밀어냄 1.3배)"] = "Gale: short dash cooldown (0.6s), and kicks raise wind that launches enemies farther (knockback x1.3)",
	["질풍각"] = "Gale Kick",
	["선풍후각"] = "Whirlwind Back Kick",
	["쌍비각"] = "Twin Flying Kick",
	["회선풍"] = "Spinning Gale",
	["풍인각"] = "Wind Blade Kick",
	["질풍보"] = "Gale Step",
	["바람처럼 꿰뚫고 지나간다 (무적). 지나간 길에 바람의 칼이 남았다 베어 낸다"] = "Pierce through like the wind (invincible). Wind blades left on your path cut again",
	["회오리"] = "Tornado",
	["앞에 회오리를 2.5초 세운다. 둘레의 적을 빨아들이며 계속 벤다"] = "Raise a tornado ahead for 2.5s. It pulls in and keeps cutting nearby enemies",
	["풍신강림"] = "Wind God Descends",
	["거대한 회오리가 일어 앞으로 나아가며 모든 적을 빨아올리고, 끝에서 사방으로 내던진다"] = "A huge tornado rises and moves forward, sucking up every enemy, then hurls them in all directions at the end",
	["진 혈마신수"] = "True Blood Demon Hand",
	["혈마신수를 완전 각성하고 두 번 깨달은 뒤, 각성 시련에서 피에 물든 자기 그림자를 넘어라"] = "Fully awaken the Blood Demon Hand and gain two insights, then beat your blood-soaked shadow in the Awakening Trial",
	["혈마의 손이 주인을 알아보고 깨어났다. 손톱 끝의 피가 금빛으로 끓는다. 혈마신수의 모든 기술이 그대로, 그러나 한층 더 깊고 붉다."] = "The Blood Demon's hand has recognized its master and awakened. The blood at your nails boils gold. Every skill of the Blood Demon Hand, only deeper and redder.",
	["진 흡혈: 준 피해의 3%를 되찾는다 (광란 중엔 1.5배, 1초에 최대 체력의 5%까지). 모든 기술 1.5배. 진 혈마강림: 더 큰 혈마가 여섯 번 찢고, 광란 10초"] = "True Lifesteal: heal 3% of damage dealt (1.5x during frenzy, per 1s up to 5% of max HP). All skills x1.5. True Blood Demon Descends: a bigger Blood Demon tears six times, frenzy 10s",
	["등 뒤로 하늘을 가릴 만큼 거대한 혈마가 솟아 손톱으로 적들을 여섯 번 찢고 포효한다. 그 뒤 10초 광란 (동작 ×1.2, 흡혈 1.5배)"] = "A sky-blotting Blood Demon rises behind you, tears enemies six times with its claws and roars. Then 10s of frenzy (speed x1.2, lifesteal x1.5)",
	["진 천룡파천장"] = "True Heavenly Dragon Sky-Breaker Palm",
	["천룡파천장을 완전 각성하고 두 번 깨달은 뒤, 각성 시련에서 금빛 용을 두른 자기 그림자를 넘어라"] = "Fully awaken the Heavenly Dragon Palm and gain two insights, then beat your gold-dragon-clad shadow in the Awakening Trial",
	["푸른 용이 허물을 벗고 금빛 진룡이 되었다. 장풍은 더 빨리 모이고, 땅을 뚫고 나오는 용은 하늘을 다 덮는다."] = "The blue dragon shed its skin and became a golden true dragon. Blasts charge faster, and the dragon from the ground covers the whole sky.",
	["진 용기: 1초면 장풍이 가득 모인다. 모든 기술 1.5배. 진 진룡강림: 거대한 금룡이 다섯 번 내리꽂히고 더 큰 숨을 뿜는다"] = "True Dragon Charge: a full blast in 1s. All skills x1.5. True Dragon Descends: a giant gold dragon slams five times and breathes bigger",
	["땅을 뚫고 거대한 금룡이 솟아 적에게 다섯 번 내리꽂히고, 마지막에 앞으로 하늘을 가르는 용의 숨을 뿜는다"] = "A giant gold dragon bursts from the ground, slams the enemy five times, then breathes a sky-splitting blast forward",
	["진 벽력신권"] = "True Thunderclap Divine Fist",
	["벽력신권을 완전 각성하고 두 번 깨달은 뒤, 각성 시련에서 보랏빛 벼락이 된 자기 그림자를 넘어라"] = "Fully awaken the Thunderclap Fist and gain two insights, then beat your shadow of purple lightning in the Awakening Trial",
	["노란 벼락이 보랏빛 천뢰가 되었다. 주먹이 닿기 전에 소리가 먼저 터지고, 연쇄 번개가 더 멀리 더 세게 튄다."] = "Yellow lightning has become purple heavenly thunder. The sound bursts before the fist lands, and chain lightning jumps farther and harder.",
	["진 전하: 네 번 맞히면 연쇄 천뢰 (더 넓고 더 세다). 모든 기술 1.5배. 진 뇌신화: 열한 번 튀고 하늘이 크게 갈라진다"] = "True Charge: four hits for chain heavenly thunder (wider and stronger). All skills x1.5. True Thunder God Form: eleven jumps and the sky splits wide",
	["몸이 보랏빛 천뢰가 되어 적에서 적으로 열한 번 튄다. 닿을 때마다 벼락이 떨어지고, 마지막에 하늘이 크게 갈라진다"] = "Your body becomes purple heavenly thunder and jumps between enemies eleven times. Lightning falls at each touch, and at the end the sky splits wide",
	["진 금강불괴신공"] = "True Indestructible Diamond Art",
	["불괴금강신권을 완전 각성하고 두 번 깨달은 뒤, 한 번 환생한 몸으로 각성 시련에서 금빛 불상이 된 자기 그림자를 넘어라"] = "Fully awaken the Diamond Fist and gain two insights, then, after one rebirth, beat your golden-Buddha shadow in the Awakening Trial",
	["다시 태어난 몸에서 금강이 깨어났다. 이제 주먹이 아니라 몸 자체가 무기다. 맞을수록 단단해지고, 쌓인 충격은 땅을 울리는 진동이 되어 되돌아간다."] = "Diamond has awakened in your reborn body. Your body itself is now the weapon. The more you're hit, the harder you get, and stored impact returns as ground-shaking tremors.",
	["불괴: 받는 피해 30% 감소. 여덟 번 맞을 때마다 (막아도 센다) 몸에서 금강 진동이 저절로 터져 둘레를 날린다. 오의 만불조종: 하늘에서 거대한 금빛 손바닥이 내려와 땅을 누른다"] = "Indestructible: 30% less damage taken. Every eight hits taken (blocks count) a diamond tremor bursts from you and throws the area. Secret Art Ten Thousand Buddhas: a giant golden palm descends from the sky and presses the ground",
	["불괴진동"] = "Indestructible Tremor",
	["항마장"] = "Demon-Subduing Palm",
	["금강주"] = "Diamond Pillar",
	["불괴추"] = "Indestructible Hammer",
	["금강파산권"] = "Mountain-Breaking Diamond Fist",
	["금강반탄"] = "Diamond Rebound",
	["1.2초 동안 금빛 종이 몸을 덮는다. 그동안 받는 모든 공격을 튕겨 되돌리고, 끝에 종이 울려 둘레를 친다"] = "A golden bell covers you for 1.2s, reflecting every attack, then rings to strike the area",
	["항마금강저"] = "Demon-Subduing Vajra",
	["땅을 내리찍으면 앞으로 금강저 일곱 개가 차례로 솟아 길을 가르고 적을 띄운다"] = "Slam the ground and seven vajras rise ahead one by one, splitting the path and launching enemies",
	["만불조종"] = "Ten Thousand Buddhas",
	["하늘이 갈라지며 산만 한 금빛 손바닥이 내려와 둘레의 땅을 누른다. 눌린 적은 오래 묶이고, 땅이 세 번 울린다"] = "The sky splits and a mountain-sized golden palm presses down on the area. Pinned enemies are held long while the ground shakes three times",
	["진 무영귀각"] = "True Shadowless Ghost Kick",
	["무영귀각을 완전 각성하고 두 번 깨달은 뒤, 한 번 환생한 몸으로 각성 시련에서 그림자뿐인 자기 그림자를 넘어라"] = "Fully awaken the Ghost Kick and gain two insights, then, after one rebirth, beat your shadow-only shadow in the Awakening Trial",
	["다시 태어난 몸에서 그림자가 따로 걷기 시작했다. 내 발이 닿은 곳에 한 박자 늦게 그림자의 발이 또 닿는다. 상대는 두 번 맞고도 한 번 본다."] = "In your reborn body, your shadow walks on its own. A beat after your foot lands, the shadow's foot lands there too. Foes get hit twice but see it once.",
	["영각: 연타·강타가 맞을 때마다 그림자가 한 박자 뒤 같은 자리를 한 번 더 찬다 (45%). 대시 세 번, 등 뒤를 차면 1.7배. 오의 백귀야행: 그림자 여덟이 둘레를 가로지르며 짓밟는다"] = "Shadow Kick: when a light or heavy hit lands, your shadow kicks the same spot again a beat later (45%). Three dashes, 1.7x from behind. Secret Art Night Parade: eight shadows cross the area and trample",
	["영각"] = "Shadow Kick",
	["쌍영각"] = "Twin Shadow Kick",
	["귀선퇴"] = "Ghost Spin Kick",
	["낙귀각"] = "Falling Ghost Kick",
	["귀영섬각"] = "Ghost Flash Kick",
	["영보삼연"] = "Shadow Triple Step",
	["그림자를 밟고 가장 가까운 적 셋의 등 뒤로 차례로 건너뛰며 찬다 (무적, 모두 등 뒤 치명)"] = "Step on shadows and leap behind the three nearest enemies in turn, kicking each (invincible, all critical from behind)",
	["그림자 감옥"] = "Shadow Prison",
	["발밑의 그림자가 둘레로 번져 적들의 발을 붙든다. 1.2초 뒤 그림자가 솟아 한꺼번에 걷어찬다"] = "Your shadow spreads to grab enemies' feet. 1.2s later the shadows rise and kick them all at once",
	["백귀야행"] = "Night Parade of a Hundred Ghosts",
	["세상이 어두워지고 그림자 여덟이 둘레의 땅에서 솟는다. 그림자들이 적들 사이를 엇갈려 가로지르며 열두 번 짓밟고, 마지막에 모두 한가운데로 모여 하늘로 걷어찬다 (그동안 무적)"] = "The world darkens and eight shadows rise from the ground. They crisscross between enemies trampling twelve times, then gather at the center and kick everyone into the sky (invincible meanwhile)",
	["진 태허유수장"] = "True Great Void Flowing Palm",
	["태허유수장을 완전 각성하고 두 번 깨달은 뒤, 한 번 환생한 몸으로 각성 시련에서 물이 된 자기 그림자를 넘어라"] = "Fully awaken the Flowing Palm and gain two insights, then, after one rebirth, beat your water shadow in the Awakening Trial",
	["다시 태어난 몸이 물이 되었다. 흘려 낸 힘은 사라지지 않고 물결이 되어 둘레를 덮친다. 물은 다투지 않는다. 다만 모든 것을 덮을 뿐."] = "Your reborn body has become water. Deflected force doesn't vanish; it turns into waves that sweep the area. Water doesn't fight. It just covers everything.",
	["역류: 흘리기 틈이 넓고 (0.3초), 흘려 낼 때마다 물결이 둘레로 터져 적을 밀어낸다. 오의 천하수류: 물의 용 셋이 나를 감아 돌며 둘레를 휩쓸고, 마지막에 한데 모여 앞으로 덮친다"] = "Backflow: wide deflect window (0.3s), and each deflect bursts a wave that pushes enemies away. Secret Art Flowing Under Heaven: three water dragons coil around you sweeping the area, then merge and crash forward",
	["역수장"] = "Reverse Water Palm",
	["회류"] = "Return Flow",
	["해일장"] = "Tidal Palm",
	["만류반탄장"] = "Ten Thousand Streams Rebound",
	["수벽파"] = "Water Wall Wave",
	["두 손으로 물의 벽을 밀어낸다. 1초 동안 앞쪽 부채꼴로 물결이 계속 밀려가 적을 밀어내고 균형을 깎는다"] = "Push a wall of water with both hands. For 1s waves keep rolling in a cone ahead, pushing enemies and wearing their balance",
	["용오름"] = "Waterspout",
	["발밑에서 물기둥이 솟아 둘레의 적을 하늘로 띄운다. 떠오른 적에게 물줄기가 내리꽂힌다"] = "A water pillar rises underfoot, launching nearby enemies; jets of water slam down on them",
	["천하수류"] = "Flowing Under Heaven",
	["물의 용 셋이 몸을 감고 솟아올라 2.6초 동안 둘레를 휘감아 돌며 휩쓴다. 마지막에 셋이 하나로 엉겨 앞으로 거대한 물결이 되어 덮친다"] = "Three water dragons coil around you and rise, sweeping the area for 2.6s. At the end they merge into one giant wave and crash forward",
	["진 열화신권"] = "True Blazing Fire Divine Fist",
	["열화신권을 완전 각성하고 두 번 깨달은 뒤, 한 번 환생한 몸으로 각성 사부를 찾아가 불이 된 자기 그림자를 넘어라"] = "Fully awaken the Blazing Fire Fist and gain two insights, then, after one rebirth, find the Awakening Master and beat your fire shadow",
	["다시 태어난 몸에서 꺼지지 않는 업화가 깨어났다. 불은 맞은 자를 태우는 것으로 끝나지 않는다. 쓰러지는 순간 터져 곁의 모두를 삼킨다."] = "An undying karmic fire has awakened in your reborn body. The fire doesn't stop at burning its target. When they fall, it bursts and engulfs everyone nearby.",
	["업화: 맞힌 적이 4초 동안 더 세게 불탄다. 불타는 적이 쓰러지면 그 자리에서 터져 둘레를 태운다. 오의 화룡천멸: 하늘을 돈 불의 용이 적들에게 내리꽂히고, 떨어진 자리가 용암이 되어 터진다"] = "Karmic Fire: enemies hit burn harder for 4s. When a burning enemy falls, it explodes and burns the area. Secret Art Fire Dragon Annihilation: a fire dragon circles the sky and slams into enemies; where it lands turns to lava and bursts",
	["업화장"] = "Karmic Fire Palm",
	["화염쌍조"] = "Twin Flame Claws",
	["염륜선풍"] = "Flame Wheel Whirlwind",
	["멸화권"] = "Extinguishing Fist",
	["업화폭추"] = "Karmic Blast Hammer",
	["염룡질주"] = "Flame Dragon Rush",
	["불길이 되어 앞으로 꿰뚫고 지나간다 (무적). 지나간 길이 한 박자 뒤 불기둥으로 터진다"] = "Become flame and pierce forward (invincible). Your path bursts into fire pillars a beat later",
	["화산주"] = "Volcano Pillar",
	["땅을 내리쳐 앞으로 불기둥 여덟을 차례로 세운다"] = "Strike the ground to raise eight fire pillars ahead one by one",
	["화룡천멸"] = "Fire Dragon Annihilation",
	["몸에서 불의 용이 솟아 하늘을 한 바퀴 돌고, 적들에게 네 번 내리꽂힌다. 마지막에 떨어진 자리가 용암이 되어 세 번 터진다"] = "A fire dragon rises from you, circles the sky and slams into enemies four times. At the end the impact points turn to lava and burst three times",
	["진 창해신권"] = "True Azure Sea Divine Fist",
	["창해신권을 완전 각성하고 두 번 깨달은 뒤, 한 번 환생한 몸으로 각성 사부를 찾아가 바다가 된 자기 그림자를 넘어라"] = "Fully awaken the Azure Sea Fist and gain two insights, then, after one rebirth, find the Awakening Master and beat your sea shadow",
	["다시 태어난 몸에서 깊은 바다가 깨어났다. 파도는 더 자주, 더 깊이 밀려온다. 바다의 바닥은 아무도 본 적이 없다."] = "The deep sea has awakened in your reborn body. Waves come more often and deeper. No one has ever seen the bottom of the sea.",
	["심해: 세 번 맞힐 때마다 상대 자리에서 큰 물기둥이 솟는다 (더 넓고 세다). 밀어냄 1.4배. 오의 심해강림: 땅이 깊은 바다가 되어 적이 가라앉고, 거대한 물기둥이 하늘로 쳐올린다"] = "Deep Sea: every three hits a big water pillar rises at the target (wider and stronger). Knockback x1.4. Secret Art Deep Sea Descends: the ground becomes deep sea, enemies sink, and a giant water pillar launches them skyward",
	["심해 파도"] = "Deep Sea Wave",
	["심해장"] = "Deep Sea Palm",
	["역류장"] = "Counter Current Palm",
	["와류각"] = "Eddy Kick",
	["대해권"] = "Ocean Fist",
	["해룡노도"] = "Sea Dragon Surge",
	["해류보"] = "Current Step",
	["물살을 타고 미끄러져 꿰뚫는다 (무적). 지나간 길에 물기둥이 솟는다"] = "Slide on the current and pierce through (invincible). Water pillars rise along your path",
	["해일용권"] = "Tidal Dragon Fist",
	["발밑에서 물기둥이 솟아 둘레의 적을 하늘로 띄우고, 물줄기가 내리꽂힌다"] = "A water pillar rises underfoot, launching nearby enemies; jets of water slam down",
	["심해강림"] = "Deep Sea Descends",
	["앞의 땅이 깊은 바다가 된다. 1.8초 동안 적이 가라앉아 움직이지 못하고, 마지막에 한가운데서 거대한 물기둥이 솟아 모두 하늘로 쳐올린다"] = "The ground ahead becomes deep sea. Enemies sink and can't move for 1.8s, then a giant water pillar rises at the center and launches them all",
	["진 풍신각"] = "True Wind God Kick",
	["풍신각을 완전 각성하고 두 번 깨달은 뒤, 한 번 환생한 몸으로 각성 사부를 찾아가 바람이 된 자기 그림자를 넘어라"] = "Fully awaken the Wind God Kick and gain two insights, then, after one rebirth, find the Awakening Master and beat your wind shadow",
	["다시 태어난 몸에서 바람의 칼이 깨어났다. 발끝이 지나간 자리마다 칼날이 남고, 그 칼날이 모여 하늘까지 닿는 회오리가 된다."] = "Blades of wind have awakened in your reborn body. A blade lingers wherever your feet pass, and the blades gather into a tornado that reaches the sky.",
	["칼바람: 대시 두 번, 대시 대기 0.4초, 밀어냄 1.5배, 더 빠르다. 오의 천풍만검: 바람의 칼날 열둘이 몸을 돌다가 사방으로 쏘아지고, 거대한 회오리가 모두 들어 올린다"] = "Blade Wind: two dashes, dash cooldown 0.4s, knockback x1.5, faster. Secret Art Heavenly Wind Myriad Blades: twelve wind blades circle you, shoot out in all directions, then a giant tornado lifts everything",
	["회선풍각"] = "Spinning Gale Kick",
	["쌍풍비각"] = "Twin Gale Flying Kick",
	["대선풍"] = "Great Whirlwind",
	["천풍인"] = "Heavenly Wind Seal",
	["질풍만보"] = "Gale Ten Thousand Steps",
	["바람처럼 꿰뚫고 지나간다 (무적). 지나간 길의 바람 칼날이 한 박자 뒤 베어 낸다"] = "Pierce through like the wind (invincible). Wind blades on your path cut a beat later",
	["칼바람 회오리"] = "Blade Wind Tornado",
	["앞에 칼바람 회오리를 2.5초 세운다. 둘레의 적을 빨아들이며 계속 벤다"] = "Raise a blade-wind tornado ahead for 2.5s. It pulls in and keeps cutting nearby enemies",
	["천풍만검"] = "Heavenly Wind Myriad Blades",
	["바람의 칼날 열둘이 몸을 감아 돌며 둘레를 베고, 사방으로 쏘아진다. 마지막에 앞에서 하늘까지 닿는 회오리가 모두 들어 올려 내던진다"] = "Twelve wind blades coil around you cutting the area, then shoot out in all directions. At the end a sky-high tornado ahead lifts and hurls everyone",
	["진 무극신권"] = "True Limitless Divine Fist",
	["무극신권을 완전 각성하고 두 번 깨달은 뒤, 한 번 환생한 몸으로 각성 사부를 찾아가 먹으로 그린 자기 그림자를 넘어라"] = "Fully awaken the Limitless Fist and gain two insights, then, after one rebirth, find the Awakening Master and beat your ink-painted shadow",
	["다시 태어난 몸에서 무극이 붓을 들었다. 흑과 백을 넘어, 먹 한 방울에서 모든 것이 그려지고 지워진다. 손끝이 지나간 자리에 먹이 번지고, 먹은 금빛으로 타오른다."] = "In your reborn body, the Limitless has taken up the brush. Beyond black and white, everything is drawn and erased from a single drop of ink. Ink spreads where your fingers pass and burns gold.",
	["먹 번짐: 네 번 맞힐 때마다 상대 발밑에 먹이 번졌다가 금빛으로 터진다. 모든 타격이 균형을 두 배로 깎는다. 오의 무극필: 하늘의 큰 붓이 땅에 먹의 꽃을 그리고, 그림이 금빛으로 타오르며 터진다"] = "Ink Bleed: every four hits ink spreads under the target and bursts gold. Every hit wears balance twice as fast. Secret Art Limitless Brush: a great brush in the sky paints an ink flower on the ground, and the painting burns gold and explodes",
	["먹 번짐"] = "Ink Bleed",
	["묵장"] = "Ink Palm",
	["획장"] = "Stroke Palm",
	["점각"] = "Dot Kick",
	["일필권"] = "Single Stroke Fist",
	["낙관"] = "Seal Stamp",
	["일획"] = "One Stroke",
	["팔을 크게 휘둘러 허공에 먹으로 한 획을 긋는다. 앞의 26칸을 가르는 굵은 먹 획이 지나간 적을 베고, 0.5초 뒤 획이 금빛으로 타오르며 한 번 더 터진다"] = "Swing your arm wide and draw one ink stroke in the air. A thick stroke cuts 26 studs ahead, slicing enemies, and 0.5s later it burns gold and bursts again",
	["원상"] = "Ink Circle",
	["붓 끝으로 발밑에 커다란 먹 원을 한 번에 그린다. 원 안의 적은 먹에 붙잡혀 1초 동안 움직이지 못하고, 원이 다 그려지면 먹 벽이 솟았다가 금빛으로 무너진다"] = "Draw a big ink circle underfoot in one go. Enemies inside are stuck in ink for 1s, and when the circle closes an ink wall rises and collapses in gold",
	["무극필"] = "Limitless Brush",
	["하늘에 커다란 붓이 나타나 둘레의 땅에 먹의 꽃을 그린다. 소용돌이치는 획 여덟이 차례로 내리그어질 때마다 그 아래의 적을 베고, 마지막에 둘레에 원을 둘러 그림 전체가 금빛으로 타오르며 터진다"] = "A great brush appears in the sky and paints an ink flower around you. Eight swirling strokes come down one by one, cutting enemies beneath, then a circle closes around it all and the painting burns gold and explodes",
	["진 매화난무권"] = "True Plum Blossom Storm Fist",
	["매화난무권을 완전 각성하고 두 번 깨달은 뒤, 한 번 환생한 몸으로 각성 사부를 찾아가 눈 속에 핀 자기 그림자를 넘어라"] = "Fully awaken the Plum Blossom Fist and gain two insights, then, after one rebirth, find the Awakening Master and beat your snow-bloom shadow",
	["다시 태어난 몸에서 한겨울의 매화가 피었다. 눈이 쌓일수록 붉게 피는 설중매처럼, 손끝이 지나간 자리마다 매화 가지가 뻗고 눈 속에서 꽃이 터진다."] = "Midwinter plum has bloomed in your reborn body. Like plum that blooms redder as snow piles up, branches stretch wherever your fingers pass and flowers burst in the snow.",
	["설중매: 다섯 번 맞힐 때마다 상대 발밑에 매화 가지가 뻗어 꽃이 피고 터진다 (눈에 덮여 잠깐 굼뜨다). 꽃잎이 차면 강타가 만개. 오의 설중매화: 둘레에 눈이 내리며 붉은 꽃잎이 휘몰아치고, 하늘에 거대한 매화가 피어 꽃잎이 쏟아진다"] = "Snow Plum: every five hits a plum branch grows under the target, blooms and bursts (snow slows them briefly). Full petals make your heavy strike bloom. Secret Art Plum in Snow: snow falls as red petals swirl around you, then a giant plum blooms in the sky and petals pour down",
	["설중매"] = "Snow Plum",
	["앞으로 손을 뻗으면 땅을 따라 매화 가지가 24칸 뻗는다. 마디마다 차례로 꽃이 피며 베고, 잠시 뒤 가지 전체의 꽃이 한꺼번에 터진다"] = "Reach out and a plum branch grows 24 studs along the ground. Flowers bloom at each joint, cutting, then all of them burst at once",
	["한매오판"] = "Five Winter Plums",
	["둘레 다섯 곳에 커다란 매화가 핀다. 꽃이 둘레의 적을 꽃술로 끌어당긴 뒤 눈보라와 함께 터진다 (맞은 적은 1초 굼뜨다)"] = "Five big plum flowers bloom around you. They pull nearby enemies into their stamens, then burst with a blizzard (enemies hit are slowed for 1s)",
	["설중매화"] = "Plum Blossoms in Snow",
	["둘레에 2초 동안 함박눈이 내리며 붉은 꽃잎이 휘몰아쳐 계속 벤다. 마지막에 하늘에 거대한 매화가 피어 꽃잎이 비처럼 쏟아진다"] = "Heavy snow falls around you for 2s while red petals swirl and keep cutting. At the end a giant plum blooms in the sky and petals pour like rain",
	["진 취팔선권"] = "True Drunken Eight Immortals Fist",
	["취팔선권을 완전 각성하고 두 번 깨달은 뒤, 한 번 환생한 몸으로 각성 사부를 찾아가 술에 취한 자기 그림자를 넘어라"] = "Fully awaken the Drunken Fist and gain two insights, then, after one rebirth, find the Awakening Master and beat your drunken shadow",
	["다시 태어난 몸에 여덟 신선이 함께 취했다. 호리병의 술이 강이 되어 흐르고, 비틀거리는 걸음 하나하나가 신선의 걸음이 된다."] = "The eight immortals are drunk with you in your reborn body. Wine from the gourd flows like a river, and every stagger becomes an immortal's step.",
	["취선: 30% 확률로 공격을 저절로 피한다. 네 번 맞힐 때마다 상대 자리에서 술이 튀어 어지럽힌다. 오의 팔선강림: 여덟 신선의 그림자가 둘레에 나타나 차례로 덮치고, 하늘에서 거대한 호리병이 내리꽂힌다"] = "Drunken Immortal: 30% chance to dodge attacks automatically. Every four hits wine splashes at the target and dizzies them. Secret Art Eight Immortals Descend: shadows of the eight immortals appear and pounce one by one, then a giant gourd slams down from the sky",
	["술 튐"] = "Wine Splash",
	["취월삼보"] = "Drunken Moon Three Steps",
	["비틀비틀 세 걸음, 좌우로 크게 휘청이며 9칸씩 뛰어든다 (무적). 내려설 때마다 둘레를 걷어찬다"] = "Three wobbly steps, lurching left and right as you lunge 9 studs each (invincible). Kick the area each time you land",
	["주천강"] = "Wine River",
	["호리병을 기울여 앞으로 술의 강을 쏟는다. 2초 동안 강 위의 적은 굼뜨고 젖어 들며, 마지막에 강에 불이 붙어 한꺼번에 타오른다"] = "Tip the gourd and pour a river of wine ahead. For 2s enemies on it are slowed and soaked, then the river catches fire and burns all at once",
	["팔선강림"] = "Eight Immortals Descend",
	["여덟 신선의 그림자가 둘레에 나타나 차례로 가까운 적에게 덮쳐 든다. 마지막에 하늘에서 거대한 호리병이 내리꽂혀 술 물결이 사방으로 터진다"] = "Shadows of the eight immortals appear and pounce on nearby enemies one by one. At the end a giant gourd slams down from the sky and wine bursts in all directions",
	["혈해만마"] = "Ten Thousand Demons in a Sea of Blood",
	["발밑이 피의 바다가 된다. 피에서 마수의 손톱이 열두 번 솟아 적들을 찢고 (찢을 때마다 체력이 돌아온다), 마지막에 바다가 핏빛 소용돌이 기둥으로 솟아 터진다. 그 뒤 10초 광란"] = "The ground becomes a sea of blood. Demon claws rise from it twelve times to tear enemies (healing you each time), then the sea erupts into a blood-red whirlpool pillar. Then 10s of frenzy",
	["구룡승천"] = "Nine Dragons Ascend",
	["땅을 뚫고 금룡 아홉이 둘레에서 솟아 하늘로 감아 오른다. 하늘을 돈 용들이 적들에게 하나씩 내리꽂히고, 마지막에 한가운데로 모여 터진다"] = "Nine gold dragons burst from the ground and coil into the sky. They circle and slam into enemies one by one, then gather at the center and explode",
	["뇌정천망"] = "Thunder Heaven Net",
	["둘레의 적 열을 보랏빛 번개 그물로 모두 잇는다. 그물이 다섯 번 고동치며 묶인 적을 지지고, 마지막에 적마다 천뢰가 떨어진다"] = "Link ten nearby enemies with a net of purple lightning. The net pulses five times frying them, then heavenly thunder falls on each",
	["천수여래"] = "Thousand-Armed Tathagata",
	["등 뒤로 팔이 여럿 달린 거대한 금빛 여래가 솟아 적들을 차례로 여덟 번 내리친다. 마지막에 하늘이 갈라지며 산만 한 손바닥이 땅을 누른다"] = "A giant many-armed golden Tathagata rises behind you and strikes enemies eight times in turn. At the end the sky splits and a mountain-sized palm presses the ground",
	["무영천살"] = "Shadowless Heaven Kill",
	["세상이 어두워지고 몸이 사라진다. 적들의 몸에 붉은 표식이 하나씩 새겨지고, 빛이 돌아오는 순간 모두 한꺼번에 터진다. 마지막에 하늘에서 그림자의 발이 짓밟는다 (그동안 무적)"] = "The world darkens and you vanish. A red mark is carved on each enemy, and the moment light returns they all burst at once. Finally a shadow foot stomps from the sky (invincible meanwhile)",
	["창해만류"] = "Azure Sea Ten Thousand Currents",
	["발밑에 거대한 소용돌이가 일어 적들을 가운데로 빨아들인다. 둘레에 물의 벽이 높이 솟았다가, 마지막에 안쪽으로 한꺼번에 무너져 내린다"] = "A giant whirlpool rises underfoot and sucks enemies to the center. Walls of water rise high around it, then collapse inward all at once",
	["진 혈마강림: .*$"] = "True Blood Demon Descends: .*$",
	["진 오의 혈해만마: 피의 바다에서 마수의 손톱이 열두 번 솟는다"] = "True Secret Art Ten Thousand Demons: demon claws rise twelve times from the sea of blood",
	["진 진룡강림: .*$"] = "True Dragon Descends: .*$",
	["진 오의 구룡승천: 금룡 아홉이 솟아 하늘을 돌고 내리꽂힌다"] = "True Secret Art Nine Dragons: nine gold dragons rise, circle the sky and slam down",
	["진 뇌신화: .*$"] = "True Thunder God Form: .*$",
	["진 오의 뇌정천망: 번개 그물이 적들을 모두 잇는다"] = "True Secret Art Thunder Net: a lightning net links every enemy",
	["오의 만불조종: .*$"] = "Secret Art Ten Thousand Buddhas: .*$",
	["오의 천수여래: 팔이 여럿 달린 금빛 여래가 내리치고 하늘의 손바닥이 누른다"] = "Secret Art Thousand-Armed Tathagata: a many-armed golden Tathagata strikes and a heavenly palm presses down",
	["오의 백귀야행: .*$"] = "Secret Art Night Parade: .*$",
	["오의 무영천살: 어둠 속에서 적마다 표식이 새겨지고 한꺼번에 터진다"] = "Secret Art Shadowless Heaven Kill: marks carved on each enemy in the dark burst at once",
	["오의 천하수류: .*$"] = "Secret Art Flowing Under Heaven: .*$",
	["오의 창해만류: 소용돌이가 빨아들이고 물의 벽이 무너진다"] = "Secret Art Ten Thousand Currents: a whirlpool pulls in and walls of water collapse",
	["혈침"] = "Blood Needles",
	["손톱 끝의 피를 바늘로 날려 둘레의 적 넷에게 꽂는다. 1초 뒤 바늘이 몸속에서 터지고, 터진 만큼 체력을 빨아온다"] = "Fire the blood at your nails as needles into four nearby enemies. 1s later they burst inside, draining HP equal to the burst",
	["혈마수인"] = "Blood Demon Hand Seal",
	["앞의 땅에서 거대한 피의 손이 솟아 둘레의 적을 움켜쥔다. 세 번 쥐어짜고, 마지막에 땅에 내리꽂는다"] = "A giant hand of blood rises ahead and grabs nearby enemies. It squeezes three times, then slams them into the ground",
	["용음"] = "Dragon's Cry",
	["금룡의 울음을 앞으로 토해낸다. 부채꼴 안의 적이 멀리 날아가고 1초 동안 몸이 굳는다 (막을 수 없다)"] = "Unleash a gold dragon's roar ahead. Enemies in the cone fly far and freeze for 1s (unblockable)",
	["금룡의 머리 모양 장력이 앞으로 길게 뻗어 나가며 닿는 적을 모두 꿰뚫고, 끝에서 터진다"] = "A palm force shaped like a gold dragon's head stretches far ahead, piercing every enemy it touches, and bursts at the end",
	["뇌인진"] = "Thunder Seal Formation",
	["땅을 내리쳐 둘레 네 곳에 보랏빛 뇌인을 새긴다. 2.6초 동안 적이 밟으면 벼락이 떨어지고 (뇌인마다 두 번), 끝에 모두 터진다"] = "Strike the ground to carve purple thunder seals in four spots. For 2.6s, enemies stepping on them are struck by lightning (twice per seal), then they all burst",
	["섬뢰포"] = "Flash Thunder Cannon",
	["주먹에 뇌전을 모았다가 앞으로 곧게 쏜다. 한 줄의 적을 모두 꿰뚫고, 지나간 줄이 1.2초 동안 지지직 지진다"] = "Gather lightning in your fist and fire it straight ahead. Pierces every enemy in the line, and the line crackles for 1.2s",
	["금강종"] = "Diamond Bell",
	["하늘에서 금빛 큰 종이 떨어져 몸을 덮는다 (1.4초 무적). 종이 세 번 울릴 때마다 둘레를 밀어내고, 마지막 울림이 가장 크다"] = "A big golden bell falls from the sky and covers you (1.4s invincible). Each of its three rings pushes the area away; the last is the biggest",
	["항마저"] = "Demon-Subduing Pestle",
	["금강저를 던진다. 앞으로 날아갔다가 손으로 되돌아오며, 가는 길과 오는 길에 한 번씩 친다"] = "Throw a vajra. It flies out and returns to your hand, hitting once going and once coming back",
	["분영"] = "Split Shadow",
	["양옆에 그림자 분신 둘이 떨어져 나와, 저마다 가까운 적에게 세 번 덮쳐 찬다"] = "Two shadow clones split off to your sides, each pouncing on a nearby enemy and kicking three times",
	["그림자 밟기"] = "Shadow Tread",
	["내 그림자만 앞으로 미끄러져 나가며 밟은 적의 그림자를 땅에 꿰맨다 (1.6초 묶임). 그림자 끝으로 몸이 옮겨 가 되돌아 걷어찬다"] = "Only your shadow slides forward, pinning the shadows of enemies it steps on (bound 1.6s). You move to the shadow's end and kick back",
	["회류환"] = "Circling Drops",
	["물방울 셋이 3초 동안 몸을 감아 돌며 닿는 적을 친다. 끝에 물결로 퍼진다"] = "Three water drops orbit you for 3s, hitting enemies they touch, then spread as a wave",
	["간헐천"] = "Geyser",
	["가까운 적 여섯의 발밑에서 차례로 뜨거운 물기둥이 솟아 하늘로 쳐올린다"] = "Scalding water pillars rise under six nearby enemies one by one, launching them skyward",
	["화륜"] = "Fire Wheel",
	["불의 바퀴를 앞으로 굴린다. 닿는 적을 치고, 바퀴가 지나간 길이 2초 동안 불탄다"] = "Roll a wheel of fire forward. It hits enemies it touches, and its path burns for 2s",
	["폭염륜"] = "Blazing Ring",
	["솟구쳤다가 내려앉으며 둘레로 불의 고리를 퍼뜨린다. 고리가 지나가는 순간 맞는다"] = "Leap up and land, spreading a ring of fire. Enemies are hit as the ring passes",
	["화산천붕"] = "Volcano Collapse",
	["앞의 땅이 부풀어 오른다. 적의 발밑마다 용암이 뿜어지고, 한가운데에서 화산이 터져 불덩이 열 개가 쏟아진다"] = "The ground ahead swells. Lava spurts under each enemy, then a volcano erupts at the center and rains ten fireballs",
	["수포옥"] = "Bubble Prison",
	["가까운 적 셋을 물방울 감옥에 가둬 띄운다. 1.6초 동안 지지고, 끝에 펑 터진다"] = "Trap three nearby enemies in water bubbles and float them. They're fried for 1.6s, then pop",
	["해룡창"] = "Sea Dragon Spear",
	["하늘에서 물의 창 일곱이 적들에게 차례로 내리꽂힌다 (적이 없으면 앞으로 한 줄)"] = "Seven water spears fall from the sky onto enemies in turn (in a line ahead if there are none)",
	["고래강림"] = "Whale Descends",
	["발밑에서 거대한 물의 고래가 솟구쳐 앞으로 크게 뛰어오른다. 고래가 땅을 덮치며 떨어지는 자리의 적은 모두 짓눌린다"] = "A giant water whale bursts from underfoot and leaps far forward. Every enemy where it crashes down is crushed",
	["회풍"] = "Whirling Wind",
	["작은 회오리를 풀어 놓는다. 3초 동안 가까운 적을 쫓아다니며 들어 올리고, 끝에 흩어지며 친다"] = "Release a small whirlwind. For 3s it chases nearby enemies lifting them up, then scatters and strikes",
	["풍압"] = "Wind Pressure",
	["솟구친 뒤 하늘의 바람을 끌어내린다. 둘레의 적을 가운데로 빨아들여 땅에 짓누른다 (1.2초 기절)"] = "Leap up and pull down the sky's wind. Nearby enemies are sucked to the center and pinned to the ground (1.2s stun)",
	["오의 화룡천멸: .*$"] = "Secret Art Fire Dragon Annihilation: .*$",
	["오의 화산천붕: 적의 발밑마다 용암이 뿜어지고, 화산이 터져 불덩이가 쏟아진다"] = "Secret Art Volcano Collapse: lava spurts under each enemy and a volcano rains fireballs",
	["오의 심해강림: .*$"] = "Secret Art Deep Sea Descends: .*$",
	["오의 고래강림: 거대한 물의 고래가 솟구쳤다가 땅을 덮친다"] = "Secret Art Whale Descends: a giant water whale bursts up and crashes down",
	[". 마지막에 충격파가 둘레를 친다"] = ". At the end a shockwave hits the area",
	["윤회"] = "Rebirth",
	["초월"] = "Transcendent",
	["극"] = "Apex",
	["신"] = "Divine",
	["초"] = "Ultimate",
	["중급"] = "Intermediate",
	["1차 깨달음"] = "1st Insight",
	["2차 깨달음"] = "2nd Insight",
	["초·매화난무권"] = "Ultimate Plum Blossom Storm Fist",
	["매화난무권을 익히고 천외천에 오른 자만이, 매화원 가장 깊은 벚꽃 언덕의 천앵선을 만난다"] = "Only those who know the Plum Blossom Fist and reach Beyond Heaven meet the Cherry Fan Immortal on the cherry hill deep in the Plum Garden",
	["매화난무권을 넘어선 권법. 두 손의 벚꽃 부채가 펼쳐질 때마다 꽃잎이 칼날이 되어 흩날린다. 꽃은 지는 순간이 가장 아름답다."] = "A style beyond Plum Blossom Storm. Each time the cherry fans in both hands open, petals scatter as blades. Flowers are most beautiful the moment they fall.",
	["벚꽃: 1.2초 안에 계속 맞히면 꽃잎이 쌓인다 (최대 30). 다 차면 Z가 천앵만개로 크게 터진다. 오의 위에 초 오의(X)가 있다"] = "Cherry Blossom: keep hitting within 1.2s to stack petals (max 30). At full, Z bursts into a huge Thousand Cherry Bloom. An Ultimate Art (X) above the Secret Art",
	["앵선일섬"] = "Cherry Fan Flash I",
	["앵선이섬"] = "Cherry Fan Flash II",
	["화선회"] = "Flower Fan Whirl",
	["낙앵선퇴"] = "Falling Cherry Fan Kick",
	["천앵일섬"] = "Heaven Cherry Flash",
	["선풍낙화"] = "Whirlwind Falling Blossoms",
	["두 부채를 펼쳐 양옆으로 던진다. 부채는 꽃잎을 흘리며 둥글게 앞으로 날아갔다 되돌아오고, 지나는 길의 적을 오갈 때 한 번씩 벤다"] = "Open both fans and throw them to the sides. They arc forward shedding petals and return, cutting enemies on the way out and back",
	["화영보"] = "Flower Shadow Step",
	["꽃잎이 되어 앞으로 미끄러진다 (무적). 지나간 길에 꽃 그림자 셋이 남아 차례로 부채를 휘두르고, 마지막에 모두 꽃잎으로 터진다"] = "Become petals and glide forward (invincible). Three flower shadows stay on your path, swing their fans in turn, then burst into petals",
	["만화천선"] = "Ten Thousand Flower Fan",
	["하늘에 커다란 벚꽃 부채가 펼쳐진다. 부채가 앞의 땅을 칼날처럼 두 번 쓸고 지나가고, 마지막에 접히며 탁 소리와 함께 꽃잎 폭풍이 둘레를 휘감는다"] = "A giant cherry fan opens in the sky. It sweeps the ground ahead twice like a blade, then snaps shut and a petal storm wraps the area",
	["만앵참월"] = "Ten Thousand Cherries Cut the Moon",
	["초 오의. 보이지 않게 둘레의 적 열을 베고 지나가며 하늘에 칼자국을 남긴다. 세상이 잿빛으로 멈춘 한 박자 뒤, 칼바람이 일어 적들을 휘감고, 마지막에 터지며 화면까지 한칼에 두 동강 낸다 (그동안 무적)"] = "Ultimate Art. Cut through ten nearby enemies unseen, leaving sword marks in the sky. The world freezes gray for a beat, then a blade wind wraps the enemies and bursts, splitting even the screen in two (invincible meanwhile)",
	["초·취팔선권"] = "Ultimate Drunken Eight Immortals Fist",
	["취팔선권을 익히고 천외천에 오른 자만이, 취선 주막 남쪽 술독 마루의 만취선을 만난다"] = "Only those who know the Drunken Fist and reach Beyond Heaven meet the Dead-Drunk Immortal on the wine-jar porch south of the Drunken Inn",
	["취팔선권을 넘어선 권법. 술병 하나와 넥타이 하나로 천하를 비틀거린다. 넘어지는 것처럼 보이는 모든 몸짓이 공격이고, 쓰러지는 순간이 가장 빠르다."] = "A style beyond the Drunken Fist. Staggering across the world with one bottle and one necktie. Every move that looks like a fall is an attack, and the moment you collapse is your fastest.",
	["만취: 막기가 되지 않는다 (막아도 그대로 맞는다). 대신 흘리기 틈이 넓고, 움직이거나 기술을 쓰는 동안 30% 확률로 저절로 피한다. 오의 위에 초 오의(X)가 있다"] = "Dead Drunk: you can't block (blocked hits still land). Instead the deflect window is wide, and you have a 30% chance to dodge while moving or using skills. An Ultimate Art (X) above the Secret Art",
	["병나발 휘두르기"] = "Bottle Swing",
	["비틀 팔꿈치"] = "Wobbly Elbow",
	["자빠지며 걷어차기"] = "Falling Kick",
	["술병 내려찍기"] = "Bottle Smash",
	["취선 몸통박치기"] = "Drunken Body Slam",
	["취화방사"] = "Drunken Fire Spray",
	["술병을 흔들어 입구에 불똥을 튀긴다. 1.6초 동안 앞으로 초록 불길이 뿜어져 나가 부채꼴을 계속 태운다"] = "Shake the bottle and spark its mouth. Green flames spray ahead for 1.6s, burning a cone",
	["팔선취보"] = "Eight Immortals Drunken Steps",
	["쓰러질 듯 여덟 걸음을 갈지자로 내딛는다. 걸음마다 둘레를 후려치고, 그동안 무엇도 맞히지 못한다"] = "Take eight zigzag steps as if about to fall. Each step sweeps the area, and nothing can hit you meanwhile",
	["취몽팔선진"] = "Drunken Dream Formation",
	["술병을 하늘 높이 던진다. 병이 깨지며 둘레에 술비가 쏟아져 적을 적시고, 불똥 하나에 온 땅이 초록 불길로 타오르며 여덟 취선의 그림자가 한꺼번에 덮친다"] = "Throw the bottle high. It shatters and wine rains down soaking enemies, one spark sets the ground ablaze in green fire, and the shadows of eight drunken immortals pounce at once",
	["취선만권"] = "Drunken Immortal Ten Thousand Fists",
	["초 오의. 세상이 멈춘 듯한 한순간, 점점 빨라지는 앞구르기로 굴러 들어가 (그동안 무적) 적들에게 와다다다 수백 주먹을 퍼붓고, 마지막에 술병을 깨뜨리며 터뜨린다"] = "Ultimate Art. In a moment where the world seems to stop, roll in with ever-faster forward rolls (invincible meanwhile), rain hundreds of punches on enemies, then smash the bottle to finish",
	["초·혈마신수"] = "Ultimate Blood Demon Hand",
	["혈마신수를 익히고 천외천에 오른 자만이, 혈교 본산 성벽 너머 혈월 제단의 혈월선을 만난다"] = "Only those who know the Blood Demon Hand and reach Beyond Heaven meet the Blood Moon Immortal at the blood-moon altar beyond the Blood Cult's walls",
	["혈마신수를 넘어선 권법. 손톱이 자라 낫이 되었다. 피처럼 붉은 큰 낫을 휘두를 때마다 핏빛 초승달이 하늘에 걸린다. 피를 흘릴수록 더 깊이 벤다."] = "A style beyond the Blood Demon Hand. The nails have grown into a scythe. Each swing of the great blood-red scythe hangs a crimson crescent in the sky. The more you bleed, the deeper you cut.",
	["피의 계약: 체력이 깎일수록 주는 피해가 오른다 (체력이 바닥이면 최대 1.6배). 벤 피해의 3%를 되찾는다. 오의 위에 초 오의(X)가 있다"] = "Blood Pact: the lower your HP, the more damage you deal (up to 1.6x near zero). Heal 3% of damage dealt. An Ultimate Art (X) above the Secret Art",
	["혈겸 내려베기"] = "Blood Scythe Down Cut",
	["역겸 올려베기"] = "Reverse Scythe Up Cut",
	["혈륜참"] = "Blood Wheel Cut",
	["참수"] = "Beheading",
	["혈월 회선참"] = "Blood Moon Spin Cut",
	["혈사슬"] = "Blood Chain",
	["낫을 사슬에 매달아 던진다. 둘레의 적 셋을 낫 끝으로 낚아 내 앞으로 끌어온 뒤, 한 바퀴 돌며 벤다"] = "Throw the scythe on a chain. Hook three nearby enemies with the tip, drag them in front of you, then cut in a full circle",
	["혈월낙참"] = "Blood Moon Falling Cut",
	["하늘로 솟아 낫을 거꾸로 쥐고 내리꽂는다. 앞의 땅에 핏빛 초승달 자국이 새겨지고, 한 박자 뒤 자국이 터진다"] = "Leap into the sky and drive the scythe down upside-down. A crimson crescent is carved into the ground ahead and bursts a beat later",
	["혈마수확"] = "Blood Demon Harvest",
	["등 뒤로 하늘만 한 피의 낫이 솟아 둘레를 두 바퀴 휩쓴다. 베인 적마다 핏빛 낙인이 찍히고, 낫이 땅에 꽂히는 순간 낙인이 한꺼번에 터진다. 벤 만큼 체력이 돌아온다"] = "A sky-sized blood scythe rises behind you and sweeps the area twice. Each enemy cut is branded crimson, and the brands burst at once when the scythe hits the ground. Heals you for what you cut",
	["혈월만겸"] = "Blood Moon Ten Thousand Scythes",
	["초 오의. 하늘이 핏빛으로 물들고 거대한 붉은 달이 뜬다 (그동안 무적). 달빛을 받은 낫이 수백 개의 핏빛 초승달이 되어 둘레에 쏟아지고, 마지막에 달까지 닿는 한 줄기 낫질이 하늘과 땅을, 화면까지 가른다"] = "Ultimate Art. The sky turns crimson and a giant red moon rises (invincible meanwhile). The moonlit scythe becomes hundreds of crimson crescents raining on the area, and a final stroke reaching the moon splits sky, earth and the screen",
	["초·벽력신권"] = "Ultimate Thunderclap Divine Fist",
	["벽력신권을 익히고 천외천에 오른 자만이, 뇌운 고원 동쪽 벼랑 끝 쇠기둥 봉우리의 뇌천선을 만난다"] = "Only those who know the Thunderclap Fist and reach Beyond Heaven meet the Thunder Heaven Immortal on the iron-pillar peak at the east cliff of the Storm Plateau",
	["벽력신권을 넘어선 권법. 두 팔에 두른 토시에 하늘의 번개가 깃들었다. 주먹은 소리보다 빠르고, 세 번째 주먹마다 하늘이 대답한다."] = "A style beyond the Thunderclap Fist. Heaven's lightning dwells in the bracers on both arms. Fists faster than sound, and every third punch the sky answers.",
	["천뢰: 세 번 맞힐 때마다 둘레로 연쇄 천뢰가 튄다 (더 넓고 세다). 몸이 가볍다 (동작 ×1.25). 오의 위에 초 오의(X)가 있다"] = "Heavenly Thunder: every three hits chain heavenly thunder jumps around (wider and stronger). Light body (speed x1.25). An Ultimate Art (X) above the Secret Art",
	["뇌섬"] = "Thunder Flash",
	["쌍뢰"] = "Twin Thunder",
	["뇌명선풍"] = "Thunder Roar Whirlwind",
	["벽력천추"] = "Thunderclap Heaven Hammer",
	["뇌광일섬"] = "Thunderlight Flash",
	["뇌전쇄"] = "Lightning Chain",
	["손을 뻗어 둘레의 적 여섯에게 차례로 벼락을 꽂는다 (마비)"] = "Reach out and drive lightning into six nearby enemies in turn (paralyze)",
	["뇌운"] = "Thunder Cloud",
	["머리 위로 먹구름을 부른다. 2.4초 동안 둘레의 적에게 번개가 떨어지고, 마지막에 큰 벼락이 내리친다"] = "Summon a dark cloud overhead. For 2.4s lightning strikes nearby enemies, ending with a great bolt",
	["뇌룡승천"] = "Thunder Dragon Ascends",
	["몸에서 번개의 용이 솟아 하늘을 감아 돌고, 적들에게 여섯 번 내리꽂힌다. 마지막에 용이 내 자리로 떨어지며 천둥이 터진다"] = "A lightning dragon rises from you, circles the sky and slams into enemies six times. At the end it falls on your spot and thunder bursts",
	["구천뇌정"] = "Nine Heavens Thunder",
	["초 오의. 하늘이 갈라지고 구름 사이로 거대한 천둥의 눈이 뜬다 (그동안 무적). 둘레에 벼락이 쏟아지고, 마지막에 하늘에서 땅까지 닿는 벼락 기둥이 내리꽂힌다"] = "Ultimate Art. The sky splits and a giant eye of thunder opens between the clouds (invincible meanwhile). Lightning pours on the area, ending with a pillar of lightning from sky to ground",
	["초·창해신권"] = "Ultimate Azure Sea Divine Fist",
	["창해신권을 익히고 천외천에 오른 자만이, 서해 바닷가 고래 뼈 바위에 앉은 고경선을 만난다"] = "Only those who know the Azure Sea Fist and reach Beyond Heaven meet the Ancient Whale Immortal on the whale-bone rock on the west sea shore",
	["창해신권을 넘어선 권법. 손목의 진주가 바다의 숨결을 머금었다. 밀물처럼 다가와 썰물처럼 끌고 간다. 바다 가장 깊은 곳에는 아직 고래가 산다."] = "A style beyond the Azure Sea Fist. The pearls at the wrists hold the sea's breath. It comes like the flood tide and drags away like the ebb. Whales still live in the deepest sea.",
	["조수: 세 번 맞힐 때마다 상대 자리에 소용돌이가 생겨 둘레를 끌어들였다가 물기둥으로 터진다. 밀어냄 1.4배, 물살을 타 빠르다 (동작 ×1.15). 오의 위에 초 오의(X)가 있다"] = "Tide: every three hits a whirlpool forms at the target, pulling in the area before bursting into a water pillar. Knockback x1.4, faster on the current (speed x1.15). An Ultimate Art (X) above the Secret Art",
	["조수"] = "Tide",
	["창랑장"] = "Azure Wave Palm",
	["회류장"] = "Return Current Palm",
	["대와각"] = "Great Whirl Kick",
	["경파권"] = "Whale Wave Fist",
	["거경격"] = "Giant Whale Strike",
	["조류창"] = "Tidal Spear",
	["손끝에 바다를 모아 소용돌이치는 물의 창을 던진다. 창은 앞의 적을 모두 꿰뚫고, 끝에서 1.2초 동안 소용돌이가 되어 둘레를 끌어당기다 물기둥으로 터진다"] = "Gather the sea at your fingertips and throw a swirling spear of water. It pierces every enemy ahead, then becomes a whirlpool for 1.2s pulling in the area before bursting into a water pillar",
	["경음"] = "Whale Song",
	["두 손을 모아 깊은 바다의 노래를 부른다. 고래의 울음이 물의 고리 셋이 되어 차례로 퍼지고, 맞은 적을 밀어내며 굼뜨게 만든다. 마지막 고리가 가장 넓다"] = "Cup your hands and sing the song of the deep sea. The whale's cry spreads as three rings of water one after another, pushing enemies away and slowing them. The last ring is the widest",
	["만경창파"] = "Ten Thousand Billows",
	["둘레 26칸의 땅이 바다가 된다. 사방에서 큰 파도 넷이 차례로 가운데로 밀려와 적을 쓸어 모으고, 마지막에 한가운데서 거대한 소용돌이가 솟아 모두 삼킨다"] = "The ground in a 26-stud radius becomes sea. Four great waves roll to the center from all sides sweeping enemies together, then a giant whirlpool rises at the center and swallows them all",
	["고경승천"] = "Ancient Whale Ascends",
	["초 오의. 하늘이 어두워지고 땅이 깊은 바다가 된다 (그동안 무적). 바다 밑에서 고대의 고래가 솟구쳐 머리 위를 지나 하늘 높이 뛰어오른다. 고래가 지나가는 그림자 아래의 적은 물살에 휩쓸려 떠오르고, 고래가 앞의 바다로 떨어지며 거대한 해일이 둘레를 덮친다"] = "Ultimate Art. The sky darkens and the ground becomes deep sea (invincible meanwhile). An ancient whale bursts from below, passes overhead and leaps high. Enemies under its shadow are swept up by the current, and as it falls into the sea ahead a giant tsunami covers the area",
	["초·성하신권"] = "Ultimate Starry River Divine Fist",
	["성하신권을 익히고 천외천에 오른 자만이, 천상계 성운원 남쪽 끝 관성대에서 별을 헤아리는 천성선을 만난다"] = "Only those who know the Starry River Fist and reach Beyond Heaven meet the Star Counting Immortal at the observatory on the south end of the Nebula Garden",
	["성하신권을 넘어선 권법. 주먹에 담던 별을 이제 지팡이 끝에 매달았다. 휘두를 때마다 마법진이 열리고, 별이 쏟아지고, 하늘에 별자리가 그려진다."] = "A style beyond the Starry River Fist. The stars once held in the fist now hang from the staff tip. Every swing opens a magic circle, rains stars and draws constellations in the sky.",
	["별진: 맞힐 때마다 25% (네 번째는 반드시) 상대 둘레에 마법진이 열리고 별이 튀어나와 찌른다. 균형을 1.3배로 깎고, 기술 대기 15% 짧다. 오의 위에 초 오의(X)가 있다"] = "Star Circle: each hit has a 25% chance (guaranteed on the fourth) to open a magic circle around the target that shoots stars. Balance damage x1.3, skill cooldowns 15% shorter. An Ultimate Art (X) above the Secret Art",
	["별진"] = "Star Circle",
	["성장 휘두르기"] = "Star Staff Swing",
	["역성장"] = "Reverse Star Staff",
	["성환"] = "Star Ring",
	["낙성추"] = "Falling Star Hammer",
	["유성장"] = "Meteor Staff",
	["별똥 화살"] = "Shooting Star Arrows",
	["지팡이 끝에 마법진을 펼쳐 별 다섯을 쏜다. 별은 둘레의 적을 쫓아가 꽂히고, 꽂힌 자리에서 작게 터진다"] = "Open a magic circle at the staff tip and fire five stars. They home in on nearby enemies and burst small where they hit",
	["성좌진"] = "Constellation Circle",
	["앞의 땅에 큰 마법진을 그린다. 둘레에 별 일곱이 떠올라 하나씩 선으로 이어져 별자리가 되는 동안 적을 끌어모으고, 별자리가 완성되면 별빛 기둥이 솟는다"] = "Draw a big magic circle on the ground ahead. Seven stars rise around it and link one by one into a constellation, pulling enemies in; when complete, a pillar of starlight rises",
	["은하수"] = "Milky Way",
	["지팡이가 커다랗게 자라 땅에 꽂힌다. 둘레 24칸에 보라·남색·노란 안개가 피어오르고, 그 안에서 별들이 소용돌이치며 은하수가 된다. 소용돌이는 적을 끌어들이며 계속 치고, 마지막에 은하가 한가운데로 모여 터진다"] = "The staff grows huge and plants itself in the ground. Purple, indigo and yellow mist rises in a 24-stud radius, and stars swirl inside into a galaxy. The swirl keeps pulling in and hitting enemies, then the galaxy collapses to the center and bursts",
	["성천궁"] = "Star Heaven Dome",
	["초 오의. 하늘이 밤이 되고 (그동안 무적) 둘레 34칸을 덮는 커다란 남색 돔이 내려앉는다. 돔 안 곳곳에 마법진이 열려 별이 쏟아지고 메테오가 떨어진다. 마지막에 돔 표면에 별자리들이 빛으로 그려지고, 모두 한꺼번에 터진다"] = "Ultimate Art. The sky turns to night (invincible meanwhile) and a big indigo dome covering 34 studs settles down. Magic circles open all over inside, raining stars and meteors. At the end constellations light up on the dome's surface and everything bursts at once",
	["만목신권"] = "Myriad Trees Divine Fist",
	["반선의 경지에 오른 자만이, 남서쪽 들판 깊은 숲 만목원의 이끼 좌대에 앉은 목선을 만난다"] = "Only those at Half-Immortal meet the Tree Sage seated on the mossy dais of the Myriad Tree Grove deep in the southwest woods",
	["나무는 서두르지 않는다. 그러나 멈추지도 않는다. 대숲의 바람처럼 부드럽게 흘러, 천 년 은행나무처럼 무겁게 내려앉는 권. 끝에는 숲 전체가 일어선다."] = "A tree doesn't hurry. But it doesn't stop either. A fist that flows softly like wind in bamboo and lands heavy like a thousand-year ginkgo. At the end the whole forest stands up.",
	["죽순: 네 번 맞힐 때마다 상대 발밑에서 죽순이 창처럼 솟아 띄운다. 몸이 단단하다 (균형 1.4배). 오의 신목강림: 천 년 은행나무가 솟아 금빛 잎을 쏟는다"] = "Bamboo Shoots: every four hits bamboo shoots spear up under the target and launch them. Sturdy body (balance x1.4). Secret Art Sacred Tree Descends: a thousand-year ginkgo rises and rains golden leaves",
	["죽순"] = "Bamboo Shoots",
	["청엽장"] = "Green Leaf Palm",
	["죽절장"] = "Bamboo Joint Palm",
	["송풍퇴"] = "Pine Wind Kick",
	["고목권"] = "Old Tree Fist",
	["천년송"] = "Thousand-Year Pine",
	["죽림창"] = "Bamboo Spears",
	["손바닥으로 땅을 누른다. 앞으로 곧게 대나무 일곱 그루가 차례로 창처럼 솟구쳐 위의 적을 띄우고, 잠시 대숲으로 서 있다가 잎을 날리며 가라앉는다"] = "Press the ground with your palm. Seven bamboo stalks spear up in a straight line ahead, launching enemies above; they stand as a grove for a moment, then sink scattering leaves",
	["천엽비수"] = "Thousand Leaf Daggers",
	["두 손을 돌리면 둘레에 푸른 잎 수십 장이 소용돌이친다. 잎은 가까운 적 여덟을 골라 세 줄기로 날아가 베고, 나는 체력 6%를 되찾는다"] = "Turn your hands and dozens of green leaves swirl around you. They pick eight nearby enemies and fly in three streams to cut them, and you recover 6% HP",
	["신목강림"] = "Sacred Tree Descends",
	["무릎을 꿇고 땅에 손을 대면 등 뒤에서 천 년 은행나무가 하늘 높이 솟는다. 2.4초 동안 금빛 잎이 둘레 24칸에 쏟아져 적을 베고, 나는 그 숲의 기운으로 체력 12%를 되찾는다. 끝에 나무가 빛나며 금빛 잎이 사방으로 휘몰아친다"] = "Kneel and touch the ground, and a thousand-year ginkgo rises high behind you. For 2.4s golden leaves pour over a 24-stud radius cutting enemies, and the forest's energy restores 12% of your HP. At the end the tree glows and golden leaves storm in all directions",
	["뇌신낙"] = "Thunder God's Fall",
	["하늘로 솟았다가 벼락이 되어 가까운 적에게 내리꽂힌다. 떨어진 자리에서 네 갈래로 땅이 갈라지며 번개가 달린다"] = "Leap into the sky and strike the nearest enemy as lightning. The ground splits four ways where you land as lightning runs along it",
	["뇌성강림"] = "Thunder Star Descends",
	["두 팔을 들어 머리 위에 고리 둘이 도는 천둥별을 띄운다. 별에서 작은 별 여섯이 떨어져 나와 둘레를 돌며 2.4초 동안 저마다 가까운 적에게 번개 줄기를 쏜다. 끝에 여섯이 다시 하나로 모여 천둥별이 땅에 떨어진다"] = "Raise both arms to summon a thunder star with two spinning rings overhead. Six small stars break off and orbit, each firing lightning at a nearby enemy for 2.4s. At the end they merge again and the thunder star falls to the ground",
	["초 오의. 하늘이 핏빛으로 물들고 거대한 붉은 달이 뜬다 (그동안 무적). 등 뒤에서 날개 달린 우두머리 악마가 솟아 큰 낫을 휘두르고, 핏빛 초승달이 2.4초 동안 쏟아진다. 마지막에 악마의 낫이 하늘과 땅을, 화면까지 가른다"] = "Ultimate Art. The sky turns crimson and a giant red moon rises (invincible meanwhile). A winged demon lord rises behind you swinging a great scythe while crimson crescents pour for 2.4s. At the end the demon's scythe splits sky, earth and the screen",
	["뇌고천무"] = "Thunder Drum Heaven Dance",
	["초 오의. 등 뒤 하늘에 뇌고(천둥 북) 여덟이 둥글게 뜬다 (그동안 무적). 북을 열여섯 번 두드릴 때마다 그 북에서 적에게 벼락이 꽂히고, 박자는 점점 빨라진다. 네 번째마다 둘레로 천둥이 울린다. 마지막에 북이 모두 모여 하나의 뇌구가 되어 땅에 내리꽂힌다"] = "Ultimate Art. Eight thunder drums appear in a ring in the sky behind you (invincible meanwhile). Each of sixteen beats drives lightning from a drum into an enemy, faster and faster, with thunder rolling around every fourth beat. At the end the drums merge into one thunder orb that slams down",
	["윤회권"] = "Rebirth Fist",
	["한 번 환생한 몸으로 첫 번째 윤회의 시련을 넘으면, 전생의 그림자가 이 권을 남기고 간다"] = "After one rebirth, pass the first Rebirth Trial and the shadow of your past life leaves this fist behind",
	["돌고 도는 삶의 바퀴를 등에 진 권. 주먹이 닿을 때마다 지난 삶의 내가 한 박자 늦게 같은 자리를 다시 친다. 바퀴가 구를 때 여섯 갈래 세상이 함께 돈다."] = "A fist that carries the wheel of rebirth on its back. Each time it lands, your past self strikes the same spot a beat later. As the wheel turns, the six realms turn with it.",
	["전생의 메아리: 네 번 맞힐 때마다 지난 삶의 그림자가 나타나 같은 자리를 다시 친다. 등 뒤의 윤회륜을 던지고, 부르고, 하늘에 띄운다"] = "Past-Life Echo: every four hits the shadow of your past life appears and strikes the same spot again. Throw, recall and raise the rebirth wheel on your back",
	["전생의 메아리"] = "Past-Life Echo",
	["윤장"] = "Wheel Palm",
	["회장"] = "Turning Palm",
	["법륜각"] = "Dharma Wheel Kick",
	["전생일격"] = "Past-Life Strike",
	["윤회일장"] = "Rebirth Palm",
	["윤회삼륜"] = "Three Wheels of Rebirth",
	["등 뒤의 윤회륜을 던진다. 금빛 바퀴가 세워진 채 구르며 26칸을 나아가고, 지난 삶의 쪽빛 바퀴 둘이 양옆으로 부채꼴을 그리며 뒤따른다. 셋 모두 땅에 금빛 바퀴 자국을 새기며 갈고, 되돌아와 등에 붙는다"] = "Throw the rebirth wheel on your back. The golden wheel rolls upright 26 studs ahead, while two indigo wheels from past lives fan out to the sides behind it. All three carve golden tracks in the ground, then return to your back",
	["삼생보"] = "Three Lives Step",
	["앞으로 18칸 미끄러지며 벤다 (무적). 떠난 자리에 지난 세 삶의 그림자가 멈춰 서 있다가 차례로 같은 길을 다시 내달려 베고, 끝에서 나에게 하나로 모여드는 순간 바퀴 무늬로 터진다"] = "Slide 18 studs forward cutting (invincible). Shadows of your three past lives stay behind, then charge the same path one by one, cutting, and burst in a wheel pattern as they merge into you",
	["육도윤회"] = "Six Paths of Rebirth",
	["윤회륜이 하늘로 올라 집채만큼 커진다. 여섯 구슬 (여섯 갈래 세상) 이 차례로 떨어져 적 둘레의 여섯 자리에 빛기둥으로 꽂히고, 기둥끼리 이어져 땅에 육각별이 그려진다. 거대한 바퀴가 누워 내려와 별 위를 갈며 돌다가 내리박혀 터진다"] = "The rebirth wheel rises into the sky and grows house-sized. Six orbs (the six realms) fall one by one as pillars of light at six spots around the enemy, the pillars link into a hexagram on the ground, and the giant wheel lies down, grinds over the star and slams in",
	["윤회전생"] = "Rebirth Reincarnation",
	["초 오의. 컷씬: 하늘이 쪽빛으로 저물고 등 뒤 하늘에 거대한 윤회륜이 걸리며, 둘레의 땅에서 지난 네 삶의 내가 일어선다 (그동안 무적). 전생의 군세가 적에게 번갈아 덮쳐 친다. 바퀴가 땅에 누워 둘레를 가두고 돌며 끌어당기고, 모두가 나에게 모여드는 순간 다시 태어나며 금빛으로 터진다"] = "Ultimate Art. Cutscene: the sky fades to indigo, a giant rebirth wheel hangs behind you, and your four past selves rise from the ground (invincible meanwhile). The army of past lives takes turns striking enemies. The wheel lies on the ground trapping the area and pulls them in, and when everyone gathers to you, you are reborn in a golden burst",
	["업화권"] = "Karmic Fire Fist",
	["두 번 환생한 몸으로 두 번째 윤회의 시련을 넘으면, 업을 진 그림자가 이 권을 남기고 간다"] = "After two rebirths, pass the second Rebirth Trial and a karma-laden shadow leaves this fist behind",
	["두 삶 동안 쌓인 업이 검은 불꽃이 되었다. 달군 사슬을 팔에 감고 치는 주먹마다 업이 상대에게 옮겨 붙고, 업이 차면 발밑에서 지옥불이 솟는다."] = "Karma piled up over two lives has turned into black flame. With heated chains wrapped around your arms, each punch passes karma to the foe, and when it's full hellfire rises underfoot.",
	["업보: 다섯 번 맞힐 때마다 상대에게 업의 낙인이 찍히고, 반 박자 뒤 발밑에서 검은 지옥불 기둥이 솟아 띄운다. 맞을수록 불은 더 무겁다 (균형 1.25배)"] = "Retribution: every five hits brands the target with karma, and half a beat later a black hellfire pillar rises underfoot and launches them. The more you're hit, the heavier the fire (balance x1.25)",
	["업보"] = "Retribution",
	["업화탄권"] = "Karmic Fire Bullet Fist",
	["흑염권"] = "Black Flame Fist",
	["사슬회권"] = "Chain Spin Fist",
	["겁화추"] = "Calamity Fire Hammer",
	["업화일권"] = "Karmic Fire Strike",
	["업화쇄"] = "Karmic Fire Chains",
	["두 팔의 달군 사슬을 내던진다. 사슬은 가까운 적 셋에게 날아가 걸리고, 검은 불이 사슬을 타고 번지며 적을 끌어온 뒤 발밑에서 지옥불로 터진다"] = "Hurl the heated chains on both arms. They catch three nearby enemies, black fire spreads along the chains, drags them in, then bursts as hellfire underfoot",
	["겁화질주"] = "Calamity Fire Rush",
	["검은 불꽃이 되어 앞으로 22칸 내달린다 (무적). 지나간 땅이 용암 틈으로 갈라져 타고, 양옆으로 사슬이 휘몰아친다. 잠시 뒤 도화선처럼 불기둥 여덟이 차례로 치솟고, 끝에서 크게 터진다"] = "Become black flame and rush 22 studs ahead (invincible). The ground you pass splits into burning lava cracks while chains lash both sides. Soon eight fire pillars erupt in sequence like a fuse, ending in a big blast",
	["업화지옥문"] = "Karmic Hell Gate",
	["주먹으로 땅을 치면 앞의 땅이 갈라지며 붉은 글이 새겨진 거대한 지옥문이 솟는다. 문이 열리며 붉은 빛과 검은 불이 쏟아지고, 문 안에서 뻗은 사슬이 둘레의 적을 문 앞으로 끌고 간다. 문이 쾅 닫히고, 땅속으로 가라앉으며 지옥불 고리로 터진다"] = "Punch the ground and it splits as a giant hell gate carved with red script rises. It opens pouring red light and black fire, and chains from inside drag nearby enemies to the gate. The gate slams shut, sinks into the ground and bursts in a ring of hellfire",
	["팔열지옥"] = "Eight Burning Hells",
	["초 오의. 컷씬: 하늘이 핏빛이 되고 땅이 갈라지며 둘레에 검은 불기둥 여덟이 솟는다 (그동안 무적). 기둥이 하나씩 적에게 지옥불을 내리꽂고, 땅에서 솟은 거대한 불의 두 손이 가운데를 맞잡아 짓누른다. 여덟 기둥이 머리 위로 모여 검은 해가 되고, 땅을 내리치면 검은 해가 떨어져 둘레가 지옥불의 돔으로 터진다"] = "Ultimate Art. Cutscene: the sky turns crimson, the ground splits and eight black fire pillars rise around you (invincible meanwhile). Each pillar drives hellfire into an enemy, and two giant hands of fire rise from the ground to clasp and crush the center. The eight pillars gather overhead into a black sun, and when you strike the ground it falls and bursts into a dome of hellfire",
	["무상권"] = "Impermanence Fist",
	["세 번 환생한 몸으로 세 번째 윤회의 시련을 넘으면, 재가 된 그림자가 이 권을 남기고 간다"] = "After three rebirths, pass the third Rebirth Trial and a shadow turned to ash leaves this fist behind",
	["세 번을 살고 나니 모든 것이 지나간다는 것을 알았다. 닿는 것마다 금이 가고, 금 간 것은 재가 되어 흩어진다. 꽃은 지고, 모래는 다 흐르고, 촛불은 꺼진다."] = "After three lives, you learned that everything passes. Everything you touch cracks, and what cracks scatters as ash. Flowers fall, sand runs out, candles go out.",
	["무상: 25% 확률로 공격이 몸을 비켜 간다. 네 번 맞힐 때마다 상대에게 사기 같은 금이 가고, 잠시 뒤 산산이 깨져 재로 흩어진다. 빠르다 (동작 ×1.3)"] = "Impermanence: 25% chance for attacks to slip past you. Every four hits porcelain-like cracks spread on the target, and soon they shatter into ash. Fast (speed x1.3)",
	["무상인"] = "Impermanence Seal",
	["허장"] = "Empty Palm",
	["실장"] = "Solid Palm",
	["연무퇴"] = "Mist Dance Kick",
	["멸영장"] = "Vanishing Shadow Palm",
	["일장무상"] = "One Palm Impermanence",
	["잔영멸"] = "Fading Afterimages",
	["재가 되어 앞으로 20칸을 스친다 (무적). 지나간 자리에 재로 빚은 내 모습 다섯이 남아 있다가, 차례로 금이 가고 무너지며 둘레를 친다"] = "Turn to ash and graze 20 studs ahead (invincible). Five ash figures of you remain on the path, then crack and crumble in turn, striking the area",
	["화무십일"] = "No Flower Lasts Ten Days",
	["앞의 땅에 커다란 잿빛 꽃이 피어난다. 꽃잎 여덟이 적을 감싸 안으로 끌어들이다가, 꽃이 시들어 재로 무너지며 터진다"] = "A big ash-gray flower blooms on the ground ahead. Its eight petals wrap enemies and pull them in, then the flower withers into ash and bursts",
	["제행무상"] = "All Things Pass",
	["둘레 26칸 위로 커다란 모래시계가 내려선다. 모래가 흐르는 동안 그 안의 적은 굼뜨고 재의 비를 맞는다. 모래가 다 흐르면 모래시계에 금이 가고, 산산이 깨지며 모든 것이 모래 폭풍으로 흩어진다"] = "A big hourglass descends over a 26-stud radius. While the sand runs, enemies inside are slowed under a rain of ash. When the sand runs out, the hourglass cracks and shatters, scattering everything in a sandstorm",
	["경화수월"] = "Flowers in a Mirror, Moon in Water",
	["초 오의. 세상의 빛깔이 빠진다 (그동안 무적). 둘레 36칸에 사람 키 세 배의 거울 열둘이 솟아 원을 이룬다. 거울 속에서 유리로 된 나의 그림자가 튀어나와 적을 치고 다른 거울로 돌아가기를 거듭한다. 거울마다 금이 번지고, 모든 거울이 한가운데로 산산이 깨져 쏟아지며 모든 것이 재가 된다"] = "Ultimate Art. The world loses its color (invincible meanwhile). Twelve mirrors three times a person's height rise in a 36-stud circle. Glass shadows of you leap from the mirrors to strike enemies and return to other mirrors again and again. Cracks spread across every mirror, they all shatter toward the center, and everything turns to ash",
	["권왕신권"] = "Fist King Divine Fist",
	["네 번 환생한 몸으로 마지막 윤회의 시련을 넘으면, 네 삶의 그림자가 하나가 되어 이 권을 남기고 간다"] = "After four rebirths, pass the final Rebirth Trial and the shadows of four lives merge to leave this fist behind",
	["네 번의 삶을 모두 넘은 자의 권. 맨손의 강호에 왕은 하나다. 주먹을 들면 하늘에서 금빛 주먹이 함께 내려오고, 마지막에는 금빛 왕이 일어선다."] = "The fist of one who has passed all four lives. In the bare-handed martial world there is only one king. Raise your fist and a golden fist descends from the sky with it; at the end, a golden king rises.",
	["왕의 주먹: 네 번 맞힐 때마다 하늘에서 거대한 금빛 주먹이 상대를 내리찍는다. 앞의 세 권을 품었다: 공격의 10%를 비켜 가고, 준 피해의 1.5%를 되찾는다"] = "King's Fist: every four hits a giant golden fist from the sky slams the target. It holds the three fists before it: 10% of attacks miss you, and you heal 1.5% of damage dealt",
	["왕의 주먹"] = "King's Fist",
	["왕권직타"] = "King's Straight",
	["왕권횡타"] = "King's Hook",
	["승천권"] = "Ascending Fist",
	["천하일권"] = "First Fist Under Heaven",
	["왕권일격"] = "King's Strike",
	["왕권천타"] = "King's Heaven Barrage",
	["등 뒤에 금빛 주먹 여섯이 부채꼴로 나타나 차례로 28칸을 내지른다. 마지막에 커다란 왕의 주먹이 가운데를 꿰뚫고 금빛 충격파가 줄지어 터진다"] = "Six golden fists appear behind you in a fan and thrust 28 studs one by one. Finally a big king's fist pierces the center and golden shockwaves burst in a line",
	["왕도강림"] = "King's Road Descends",
	["발밑에서 앞으로 붉은 길이 깔리고, 그 위로 크게 뛰어올라 24칸 앞에 내려앉는다 (무적). 내려앉은 자리 둘레에서 왕관의 금빛 가시 여덟이 솟고, 가시가 안으로 무너지며 터진다"] = "A red road unrolls ahead from your feet; leap high along it and land 24 studs ahead (invincible). Eight golden crown spikes rise around where you land, then collapse inward and burst",
	["패왕난무"] = "Overlord Flurry",
	["둘레에 금빛 기둥 여덟이 솟아 왕의 투기장이 되고 적을 안으로 끌어들인다. 기둥마다 붉은 소매의 거대한 금빛 주먹이 나타나 차례로 한가운데를 내지르고, 마지막에 땅속에서 솟은 주먹이 모두를 하늘로 올려친다"] = "Eight golden pillars rise around you forming a king's arena and pull enemies in. A giant red-sleeved golden fist appears at each pillar and punches the center in turn, and finally a fist from the ground launches everyone skyward",
	["천하제일권"] = "First Fist Under Heaven",
	["초 오의. 컷씬: 하늘이 금빛으로 갈라진다 (그동안 무적). 몸에서 금빛이 솟아 등 뒤에 관과 망토를 두른 하늘만 한 금빛 왕 (나의 모습)이 일어선다. 왕이 주먹을 당겨 하늘의 금빛을 모으고 가장 강한 적에게 내리꽂는다. 땅이 꺼지며 충격파 세 겹, 금빛 빛기둥 넷이 십자로 내달린 뒤, 하늘에서 빛의 왕관이 내려와 터진다"] = "Ultimate Art. Cutscene: the sky splits gold (invincible meanwhile). Gold rises from your body and a sky-sized golden king (your form) wearing a crown and cape stands behind you. The king draws back its fist, gathers the sky's gold and drives it into the strongest enemy. The ground caves in with three shockwaves, four golden pillars race out in a cross, and a crown of light descends from the sky and bursts",
	["몽유권"] = "Dreamwalk Fist",
	["두 번 환생한 몸으로, 연화정에서 꾸벅꾸벅 조는 몽선의 꿈 이야기를 들어주어라"] = "After two rebirths, listen to the dream stories of the Dream Sage dozing at the Lotus Pavilion",
	["두 번째 삶의 꿈속을 걷는 권. 반쯤 잠든 채 싸운다. 꿈에서는 문이 허공에 열리고, 땅과 하늘이 뒤집히고, 달이 손에 닿는다."] = "A fist that walks through the dream of a second life. You fight half asleep. In dreams, doors open in midair, earth and sky flip, and the moon is within reach.",
	["꿈길: 네 번 맞힐 때마다 상대 등 뒤 허공에 꿈의 문이 열려 상대를 빨아들였다가 뱉어 낸다. 잠결처럼 가볍다: 공격의 15%가 비켜 가고, 동작 ×1.2"] = "Dream Path: every four hits a dream door opens in the air behind the target, swallowing them and spitting them out. Light as sleep: 15% of attacks slip past you, speed x1.2",
	["꿈의 문"] = "Dream Door",
	["잠결 손"] = "Sleepy Hand",
	["꿈결 손"] = "Dreamy Hand",
	["뒤척임"] = "Toss and Turn",
	["깨는 손"] = "Waking Hand",
	["몽중일장"] = "Palm in a Dream",
	["꿈길 걸음"] = "Dream Path Walk",
	["눈을 감은 채 앞으로 18칸을 걷는다 (그동안 무적). 발 앞 허공에 달빛 디딤돌이 하나씩 놓여 밤하늘 길이 되고, 길 위의 적은 꾸벅 잠이 든다 (0.8초 기절). 길 끝에 닿으면 디딤돌이 차례로 별가루가 되어 솟구치며 잠든 적을 한 번 더 친다"] = "Walk 18 studs ahead with your eyes closed (invincible meanwhile). Moonlit stepping stones appear one by one in the air, forming a night-sky path, and enemies on it nod off (0.8s stun). At the end the stones rise as stardust in turn and strike the sleeping enemies again",
	["거꾸로 꿈"] = "Upside-Down Dream",
	["앞의 땅이 밤하늘이 되고 중력이 뒤집힌다. 그 안의 적은 하늘로 떨어지듯 거꾸로 떠오르다가, 꿈이 바로 서는 순간 땅에 내리꽂힌다"] = "The ground ahead becomes a night sky and gravity flips. Enemies inside float upward as if falling into the sky, then slam into the ground when the dream rights itself",
	["몽중몽"] = "Dream Within a Dream",
	["둘레 26칸이 꿈속이 된다. 밤하늘에 커다란 달이 뜨고, 풀이 덮인 작은 섬과 끝이 없는 계단과 문들이 둥실 떠다닌다. 문이 적 곁에서 열렸다 닫힐 때마다 꿈에 베이고, 마지막에 모든 것이 아래로 떨어지며 꿈에서 깬다"] = "A 26-stud radius becomes a dream. A big moon rises in the night sky, and small grassy islands, endless stairs and doors drift about. Each time a door opens and shuts beside an enemy, the dream cuts them; at the end everything falls away and you wake",
	["월하몽"] = "Moonlit Dream",
	["초 오의. 컷씬: 밤이 내리고 하늘을 가득 채우는 보름달이 떠오른다 (그동안 무적). 둘레 40칸의 땅이 달을 비추는 고요한 밤 호수가 되고, 등불과 문이 떠오른다. 적은 잠든 듯 둥실 떠올라 별의 소용돌이에 감기고, 마지막에 달이 천천히 내려와 호수에 닿는 순간 하얀 빛이 소리 없이 번지며 모두 떨어진다"] = "Ultimate Art. Cutscene: night falls and a full moon fills the sky (invincible meanwhile). The ground in a 40-stud radius becomes a still night lake reflecting the moon, with lanterns and doors floating up. Enemies drift up as if asleep and are wrapped in a whirl of stars; finally the moon slowly descends, and the moment it touches the lake a white light silently spreads and they all fall",
	["공백권"] = "Null Fist",
	["null. 이 권법의 설명은 지워졌다. 주먹이 닿은 자리는 비어 버리고, 비어 버린 자리는 다시 채워지지 않는다."] = "null. This style's description has been erased. Where the fist lands becomes empty, and what becomes empty is never filled again.",
	["빈칸: 네 번 맞힐 때마다 상대가 검은 네모 칸에 지워졌다가 깨진 화면처럼 돌아온다. 끊김: 공격의 12%가 몸을 비켜 간다 (지직). 동작 ×1.25"] = "Blank: every four hits the target is erased into a black square, then returns like a broken screen. Glitch: 12% of attacks slip past you (bzzt). Speed x1.25",
	["빈칸"] = "Blank",
	["지직"] = "Bzzt",
	["끊김"] = "Glitch",
	["되감기"] = "Rewind",
	["덮어쓰기"] = "Overwrite",
	["빈 주먹"] = "Empty Fist",
	["소거"] = "Erase",
	["앞에 흰 선택 상자가 그어지고 깜박인다. 상자 안의 모든 것이 검게 지워졌다가, 상자가 화소 조각으로 부서진다"] = "A white selection box is drawn ahead and blinks. Everything in it is blacked out, then the box breaks into pixel shards",
	["화면이 끊기듯 둘레의 적 넷 사이를 순간이동하며 친다 (그동안 무적). 지나간 자리마다 어긋난 잔상이 남고, 마지막 적의 등 뒤에 나타난다"] = "Teleport between four nearby enemies like a stuttering screen, striking each (invincible meanwhile). Misaligned afterimages remain, and you appear behind the last enemy",
	["허공 격자"] = "Void Grid",
	["둘레 26칸의 빛깔이 빠지고 땅이 흰 격자의 검은 허공이 된다. 허공 위로 붉은 null 글자가 떠다니며 적을 가운데로 끌어 지우다가, 허공이 한 점으로 오그라든 뒤 흰 잡음으로 터진다"] = "A 26-stud radius loses its color and the ground becomes a black void with a white grid. Red null text drifts over it, pulling enemies to the center to erase them, then the void shrinks to a point and bursts into white noise",
	["존재소거"] = "Existence Erasure",
	["초 오의. 화면이 깨진다 (그동안 무적). 둘레 40칸에 검은 화면 균열이 미끄러지고, 하늘에서 빈칸 상자들이 적에게 떨어진다. 모든 것이 멈추고 빛깔이 뒤집힌 뒤, 삑 소리 한 번에 둘레가 화소 조각으로 무너진다"] = "Ultimate Art. The screen breaks (invincible meanwhile). Black screen cracks slide across a 40-stud radius and blank boxes fall on enemies from the sky. Everything stops, colors invert, and with one beep the area collapses into pixel shards",
	["극 일월신권"] = "Apex Sun-Moon Divine Fist",
	["일월신권을 숙련 20까지 쌓고 세 번 환생한 자만이, 천상 윤회대의 황혼권존을 만난다"] = "Only those who build Sun-Moon Fist mastery to 20 and are reborn three times meet the Twilight Fist Sovereign on the Heavenly Rebirth Terrace",
	["일월신권의 끝. 해와 달을 쥐는 것을 넘어, 해와 달을 부린다. 싸움이 무르익으면 해와 달이 미친 듯이 번갈아 뜨다가 세상이 황혼에 멈추고, 그 황혼 속에서 모든 수가 다른 것이 된다."] = "The end of the Sun-Moon Fist. Beyond holding the sun and moon, you command them. As the fight ripens they rise in turn ever faster until the world halts at twilight, and in that twilight every move becomes something else.",
	["극 패시브 · 일월극변: 맞히고 맞으며 극(100)을 채우면 서버 전체에 컷씬이 흐르고 40초 동안 세상이 황혼이 된다. 그동안 모든 기술이 황혼의 기술로 바뀌고 (더 세다), 연타·강타 피해 1.3배. 낮에는 주는 피해 +20%, 밤에는 받는 피해 -20%. 모든 기술 대기 30% 짧음. 초 오의(X)가 있다"] = "Apex Passive · Sun-Moon Apex Shift: fill Apex (100) by landing and taking hits and a cutscene plays server-wide as the world turns to twilight for 40s. Meanwhile all skills become twilight skills (stronger), light and heavy damage x1.3. By day damage dealt +20%, by night damage taken -20%. All skill cooldowns 30% shorter. Has an Ultimate Art (X)",
	["극 일출장"] = "Apex Sunrise Palm",
	["극 월하장"] = "Apex Moonlight Palm",
	["극 일륜각"] = "Apex Sun Wheel Kick",
	["극 월인권"] = "Apex Moon Seal Fist",
	["일월극벽"] = "Sun-Moon Apex Wall",
	["일월쌍륜"] = "Sun-Moon Twin Discs",
	["해의 원반과 달의 원반을 양옆으로 던진다. 두 원반은 서로 엇갈리는 활을 그리며 앞으로 날아가 지나는 적을 태우고 베다가, 30칸 앞에서 만나 일식처럼 터진다"] = "Throw a sun disc and a moon disc to the sides. They fly forward in crossing arcs, burning and cutting enemies on the way, and meet 30 studs ahead in an eclipse burst",
	["일월환보"] = "Sun-Moon Blink",
	["제자리에 해를 터뜨리며 앞으로 22칸 사라졌다 나타난다 (무적). 지나간 길을 달빛이 베고, 내려선 자리에서 초승달이 둥글게 터진다"] = "Burst a sun in place and vanish, reappearing 22 studs ahead (invincible). Moonlight cuts your path, and a crescent bursts in a circle where you land",
	["대일월천"] = "Great Sun-Moon Heaven",
	["등 뒤에 해와 달이 떠오른다. 해는 불의 빛줄기로 앞의 땅을 앞뒤로 쓸어 태우고, 달은 거대한 초승달 셋을 차례로 내리꽂는다. 둘이 적 위에서 부딪쳐 일식이 되고 땅이 갈라지며, 일식이 땅에 박혀 빛의 돔으로 터진다"] = "The sun and moon rise behind you. The sun sweeps the ground ahead back and forth with a beam of fire while the moon drives down three giant crescents. They collide over enemies into an eclipse, the ground splits, and the eclipse sinks in and bursts into a dome of light",
	["일월개벽"] = "Sun-Moon Genesis",
	["초 오의. 컷씬: 세상이 어두워지고 등 뒤 지평선 양쪽에서 거대한 해와 달이 솟는다 (그동안 무적). 해와 달이 나를 두고 점점 빨리 돌며 번갈아 적을 친다 (해는 불기둥, 달은 초승달). 둘이 머리 위에서 부딪쳐 하늘에 거대한 일식이 걸리면 세상의 빛깔이 빠지고, 일식의 빛살이 쏟아진다. 하늘로 주먹을 내지르면 일식이 금 가고 깨지며 새벽빛으로 터진다"] = "Ultimate Art. Cutscene: the world darkens and a giant sun and moon rise from both horizons behind you (invincible meanwhile). They orbit you faster and faster, striking enemies in turn (fire pillars from the sun, crescents from the moon). They collide overhead and a giant eclipse hangs in the sky, the world loses its color, and eclipse rays pour down. Punch the sky and the eclipse cracks and shatters into dawn light",
	["황혼"] = "Twilight",
	["황혼일권"] = "Twilight Strike",
	["황혼참"] = "Twilight Cut",
	["노을빛 초승달 다섯을 부채꼴로 던진다. 초승달은 28칸 날아갔다가 되돌아오며 오갈 때 한 번씩 벤다"] = "Throw five sunset crescents in a fan. They fly 28 studs and return, cutting once each way",
	["석양보"] = "Sunset Step",
	["노을이 되어 가까운 적 다섯의 등 뒤로 차례로 나타나며 벤다 (무적). 지나간 노을빛 줄이 모두 한꺼번에 터진다"] = "Become sunset and appear behind five nearby enemies in turn, cutting each (invincible). The sunset trails you left all burst at once",
	["황혼낙일"] = "Twilight Sunset",
	["하늘 저편에서 거대한 석양이 내려와 앞의 땅에 닿고, 땅이 노을빛 바다가 된다. 석양이 가라앉는 동안 바다 위의 적은 타며 굼뜨고, 노을빛 물결 넷이 퍼지고, 달빛 기둥이 솟는다. 다 잠기면 바다가 잠깐 식어 고요해졌다가 노을 불꽃의 왕관으로 솟구친다"] = "A giant setting sun descends from afar onto the ground ahead and the ground becomes a sunset sea. As the sun sinks, enemies on the sea burn and slow, four sunset waves spread and moonlight pillars rise. Once it's fully submerged the sea briefly cools and goes still, then erupts into a crown of sunset flame",
	["일월동귀"] = "Sun and Moon Return Together",
	["황혼의 초 오의. 컷씬: 하늘이 노을로 물들고 양쪽에서 거대한 석양과 달이 내려온다 (그동안 무적). 둘은 빨려 들며 작아져 두 손에 맺히고, 손을 떠나 발밑 진의 테두리를 서로 반대로 내달려 불의 원을 그린다. 앞에서 만난 둘은 황혼의 구슬이 되어 머리 위로 떠올라 둘레를 빨아들이다가 한 점으로 줄어들고, 세상이 노을빛으로 하얗게 터진다"] = "Twilight Ultimate Art. Cutscene: the sky turns to sunset and a giant setting sun and moon descend from both sides (invincible meanwhile). They shrink as they're drawn into your hands, then leave them and race around the edge of the circle underfoot in opposite directions, drawing a ring of fire. Meeting ahead, they become an orb of twilight that rises overhead, pulls in the area, shrinks to a point, and the world bursts white in sunset light",
	["극 공백권"] = "Apex Null Fist",
	["공백권을 숙련 20까지 쌓고 세 번 환생한 자만이, 세상 끝 너머 망각의 정원에서 격자지기를 만난다"] = "Only those who build Null Fist mastery to 20 and are reborn three times meet the Grid Keeper in the Garden of Oblivion beyond the end of the world",
	["공백권의 끝. 지우는 것을 넘어, 비어 있는 곳에 좌표를 긋는다. 싸움이 무르익으면 그가 선 자리에서 흰 격자가 한 점에서부터 천천히 펼쳐져 공간이 되고, 그 격자 안은 모두 그의 것이 된다."] = "The end of the Null Fist. Beyond erasing, you draw coordinates in emptiness. As the fight ripens, a white grid slowly unfolds from a single point where he stands, becoming a space, and everything inside that grid is his.",
	["극 패시브 · 격자 전개: 맞히고 맞으며 극(100)을 채우면 서버 전체에 알림이 뜨고, 선 자리에서 흰 3차원 격자 공간이 한 점에서부터 천천히 펼쳐져 (4.5초) 30초 동안 머문다 (반지름 100칸, 높이 84칸. 둘레는 허공에서 끊긴다). 격자 안의 적은 굼뜨고 1초마다 격자에 베이며, 그동안 모든 기술이 격자의 기술로 바뀌고 연타·강타 피해 1.3배. 빈칸: 세 번 맞힐 때마다 빈칸이 터진다. 끊김: 공격의 15%가 몸을 비켜 간다. 동작 ×1.3"] = "Apex Passive · Grid Deployment: fill Apex (100) by landing and taking hits and a server-wide alert appears as a white 3D grid space slowly unfolds from a point where you stand (4.5s) and stays for 30s (radius 100 studs, height 84 studs; the edges cut off into the void). Enemies inside are slowed and cut by the grid every 1s, all skills become grid skills, and light and heavy damage x1.3. Blank: a blank bursts every three hits. Glitch: 15% of attacks slip past you. Speed x1.3",
	["극 빈칸"] = "Apex Blank",
	["극 지직"] = "Apex Bzzt",
	["극 끊김"] = "Apex Glitch",
	["극 되감기"] = "Apex Rewind",
	["극 덮어쓰기"] = "Apex Overwrite",
	["극 빈 주먹"] = "Apex Empty Fist",
	["좌표선"] = "Coordinate Lines",
	["앞의 허공에 흰 좌표축 세 줄이 별 모양으로 그어진다. 줄을 따라 공간이 위아래로 어긋나며 베고, 다시 붙으며 한 번 더 벤다"] = "Three white coordinate axes are drawn in a star shape in the air ahead. Space shifts up and down along the lines cutting, then snaps back and cuts again",
	["좌표 교환"] = "Coordinate Swap",
	["가장 가까운 적과 나를 흰 격자 상자에 가두고 좌표를 맞바꾼다 (그동안 무적). 적이 서 있던 자리에 내가, 내가 서 있던 자리에 적이 놓이고, 그 상자가 오그라들며 터진다"] = "Trap yourself and the nearest enemy in white grid boxes and swap coordinates (invincible meanwhile). You end up where the enemy stood and vice versa, then the box shrinks and bursts",
	["천공 격자"] = "Sky Grid",
	["가까운 적의 하늘에 거대한 흰 격자 정육면체가 짜여 내려꽂힌다. 땅에 격자가 새겨지고 칸마다 붉게 세 번 터지다가, 정육면체가 산산이 흩어진다"] = "A giant white grid cube forms in the sky above a nearby enemy and slams down. A grid is carved into the ground, each cell bursts red three times, then the cube scatters",
	["차원 절단"] = "Dimension Cut",
	["초 오의. 컷씬 (그동안 무적): 손끝에서 흰 격자가 하늘로 뻗는다. 둘레 52칸에 흰 격자 하늘이 둥글게 짜이고, 거대한 빛의 칼날 판이 공간을 여섯 번 가른다 (가를 때마다 공간이 어긋난다). 멈추고 빛깔이 뒤집힌 뒤, 모든 격자가 한 점으로 빨려 들어 하얗게 터진다"] = "Ultimate Art. Cutscene (invincible meanwhile): a white grid stretches from your fingertips into the sky. A dome of white grid sky forms over a 52-stud radius, and a giant blade of light slices space six times (space shifts with each cut). Everything stops, colors invert, then every grid line is sucked into one point and bursts white",
	["격자 공간"] = "Grid Space",
	["격자"] = "Grid",
	["좌표 고정"] = "Coordinate Lock",
	["격자선 베기"] = "Grid Line Cut",
	["펼친 격자 공간 안의 적 여섯 (어디 있든)이 선 자리를 지나는 격자선 셋 (가로·세로·높이)이 공간 끝에서 끝까지 붉게 켜졌다가, 선째 벤다. 그 둘레의 격자도 함께 붉게 지직인다"] = "For six enemies inside your grid space (wherever they are), the three grid lines through each (width, depth, height) light up red from end to end, then cut along the lines. The grid around them crackles red too",
	["격자 질주"] = "Grid Rush",
	["격자선을 따라 직각으로 꺾어 달리며 공간 안의 적 다섯을 차례로 친다 (무적). 지나간 격자선이 하얗게 타오른다"] = "Run along grid lines turning at right angles, hitting five enemies in the space in turn (invincible). The grid lines you pass burn white",
	["격자 수축"] = "Grid Collapse",
	["펼친 격자 공간 전체가 적이 가장 많은 곳으로 오그라들며 (선이 붉어진다) 공간 안의 적을 모두 끌어모은다. 잠깐 버티다가 다시 튕겨 펼쳐지며 그 자리가 하얗게 터진다"] = "The whole grid space shrinks toward the densest group of enemies (lines turn red), pulling every enemy inside together. It holds briefly, then springs back open and that spot bursts white",
	["격자의 초 오의 (그동안 무적). 펼친 공간의 네 벽이 네 번에 걸쳐 안으로 접혀 들며 공간 안의 적을 짓누르고, 위아래로 눌려 한 점이 된 뒤, 공간째 지워진다. 격자 공간은 여기서 끝난다"] = "Grid Ultimate Art (invincible meanwhile). The four walls of the space fold inward in four steps crushing enemies inside, press down from above and below into a single point, and the space is erased with them. The grid space ends here",
	["극 광속권"] = "Apex Lightspeed Fist",
	["진 풍신각을 숙련 20까지 쌓고 세 번 환생한 자만이, 지옥 황천 나루에서 질주귀를 만난다"] = "Only those who build True Wind God Kick mastery to 20 and are reborn three times meet the Racing Ghost at the Hwangcheon Ferry in the Underworld",
	["진 풍신각의 끝. 바람을 앞지르는 것을 넘어, 소리를 앞지르고, 마침내 빛을 앞지른다. 그의 주먹은 맞고 나서야 보이고, 그가 지나간 자리엔 잔상만 남는다. 싸움이 무르익으면 세상이 느려 보일 만큼 빨라지고, 그 속에서 그만 홀로 번개처럼 달린다."] = "The end of the True Wind God Kick. Beyond outrunning the wind, you outrun sound and finally light. His fist is seen only after it lands, and only afterimages remain where he passed. As the fight ripens he becomes so fast the world seems slow, and he alone runs through it like lightning.",
	["극 패시브 · 초가속: 맞히고 맞으며 극(100)을 채우면 서버 전체에 컷씬이 흐르고 30초 동안 초가속에 든다. 둘레 90칸의 적은 굼뜨고 (이동 ×0.35), 내 걸음은 ×1.6, 모든 타격이 0.2초 뒤 잔상으로 절반만큼 한 번 더 친다. 그동안 기술이 모두 초가속의 기술로 바뀌고 (더 세다), 연타·강타 피해 1.3배. 가속: 맞힐 때마다 걸음이 5%씩 빨라진다 (최대 5단계, 3초 안 맞히면 풀리고, 맞으면 반으로). 네 번 맞힐 때마다 음속 충격. 모든 기술 대기 28% 짧음. 초 오의(X)가 있다"] = "Apex Passive · Hyper Speed: fill Apex (100) by landing and taking hits and a cutscene plays server-wide as you enter hyper speed for 30s. Enemies within 90 studs are slowed (move x0.35), your stride x1.6, and every hit strikes again 0.2s later as an afterimage for half damage. All skills become hyper-speed skills (stronger), light and heavy damage x1.3. Acceleration: each hit speeds you up 5% (up to 5 stacks; resets if you don't hit for 3s, halves when you're hit). A sonic shock every four hits. All skill cooldowns 28% shorter. Has an Ultimate Art (X)",
	["음속 충격"] = "Sonic Shock",
	["극 광권"] = "Apex Light Fist",
	["극 섬권"] = "Apex Flash Fist",
	["극 쾌타"] = "Apex Quick Strike",
	["극 음속각"] = "Apex Sonic Kick",
	["극 관통"] = "Apex Pierce",
	["광속 관통"] = "Lightspeed Pierce",
	["몸을 빛으로 쏘아 앞의 적들을 34칸 꿰뚫고 나타난다 (무적). 지나간 자리에 빛의 줄이 남고, 잠시 뒤 줄 전체가 한꺼번에 터지며 한 번 더 벤다"] = "Fire your body as light, piercing enemies 34 studs ahead (invincible). A line of light remains, then the whole line bursts at once for another cut",
	["음속 돌파"] = "Sonic Breakthrough",
	["소리의 벽을 뚫고 26칸을 달린다 (무적). 벽이 깨지는 순간 몸 뒤로 하얀 증기 원뿔이 터지며, 닿은 적이 크게 튕겨 나간다"] = "Break the sound barrier and run 26 studs (invincible). The moment it breaks, a white vapor cone bursts behind you and enemies it touches are flung away",
	["유성 질주"] = "Meteor Run",
	["순식간에 사라져 둘레를 별 모양으로 열 번 가로지른다 (무적). 달린 길마다 빛의 선이 남아 지나는 적을 베고, 마지막에 모든 선이 한꺼번에 번쩍이며 터진다"] = "Vanish and cross the area ten times in a star pattern (invincible). Each path leaves a line of light that cuts enemies passing through, and at the end all lines flash and burst at once",
	["광속 일섬"] = "Lightspeed Flash",
	["초 오의. 짧은 컷씬 (그동안 무적): 출발선에서 몸을 낮춘다. 음속, 광속, 초광속, 세 걸음으로 점점 더 길게 내달린다. 첫 걸음은 소리를 넘고, 둘째는 빛이 되고, 셋째는 지나간 자리마저 남기지 않는다. 달린 길 위의 모든 적을 베고, 끝에서 소리가 한꺼번에 따라붙어 충격파로 터진다"] = "Ultimate Art. Short cutscene (invincible meanwhile): crouch at the starting line. Three ever-longer dashes: sonic, light speed, beyond light. The first breaks sound, the second becomes light, the third leaves not even a trace. Every enemy on the path is cut, and at the end the sound catches up all at once in a shockwave",
	["초가속"] = "Hyper Speed",
	["초 관통"] = "Hyper Pierce",
	["광침"] = "Light Needles",
	["손목을 튕겨 빛의 바늘 아홉을 부채꼴로 쏜다. 바늘은 34칸을 순식간에 꿰뚫고 사라지며, 지나간 줄이 번쩍인다"] = "Flick your wrist to fire nine needles of light in a fan. They pierce 34 studs in an instant and vanish, leaving flashing lines",
	["지그재그 질주"] = "Zigzag Run",
	["직각으로 꺾으며 앞으로 다섯 번 번개처럼 도약한다 (무적). 내려서는 자리마다 사방이 터지고, 지나간 길이 번개 줄로 남는다"] = "Leap forward five times like lightning, turning at right angles (invincible). Each landing bursts in all directions, and your path remains as a lightning trail",
	["마하 폭풍"] = "Mach Storm",
	["앞으로 뻗은 한 줄기 길을 64칸씩 네 번 왕복한다 (무적). 지날 때마다 소리의 벽이 깨지며 길 양옆의 적을 한가운데로 쓸어 모으고, 마지막에 길 한복판에서 충격파가 터진다"] = "Run back and forth four times along a 64-stud road ahead (invincible). Each pass breaks the sound barrier, sweeping enemies on both sides to the middle, and finally a shockwave bursts at the center",
	["유성 연쇄"] = "Meteor Chain",
	["초가속의 초 오의 (그동안 무적). 몸이 빛의 구슬이 되어 눈에 보이지 않는 속도로 적들 사이를 열 번 튕겨 다닌다. 지나간 자리마다 빛의 줄이 거미줄처럼 남고, 마지막에 하늘로 솟았다가 혜성처럼 한가운데로 내리꽂힌다. 거미줄이 한꺼번에 번쩍인다"] = "Hyper Speed Ultimate Art (invincible meanwhile). Your body becomes an orb of light and bounces between enemies ten times at invisible speed. Lines of light remain like a web, and at the end you shoot into the sky and crash into the center like a comet as the whole web flashes",
	["신 삼재권"] = "Divine Three Powers Fist",
	["환생 5번 + 극 권법 셋 (극 일월 · 극 공백 · 극 광속)을 얻고, 세상 북서쪽 끝의 사람 모양 돌에게 은자 9,990,000을 바쳐 땅 밑 동굴의 제단에서 얻는다"] = "After 5 rebirths and all three Apex styles (Apex Sun-Moon, Apex Null, Apex Lightspeed), offer 9,990,000 silver to the man-shaped stone at the far northwest, then claim it at the altar in the cave below",
	["극을 넘어선 궁극의 권법. 새로운 것이 아니라, 처음의 주먹으로 돌아온 것이다. 하늘을 받치고, 땅을 딛고, 사람이 휘두른다. 팔이 몸 둘레를 돌 때마다 하늘과 땅과 사람이 하나로 모이고, 땅을 한 번 찍으면 천지가 갈라진다."] = "The ultimate style beyond Apex. Not something new, but a return to the first fist. Heaven supports, earth grounds, man swings. Each time the arms circle the body, heaven, earth and man become one; one stomp and heaven and earth split.",
	["신 채우기: 싸우며 신(100)을 채우면 신의 모습으로 바뀐다 (쓰러질 때까지). 몸이 떠올라 날아다니고 금빛 갑옷과 거대한 신의 잔상이 따르며 기술이 모두 바뀐다 (더 세다, 영역은 없다). 체술: 팔꿈치 · 쓸어차기 · 무릎 · 진각 · 메치기로 싸우는 몸의 권법. 붙잡아 휘돌리고 내리꽂는다. 삼재 진동: 연타·강타를 세 번 맞힐 때마다 발밑에서 땅이 울려 둘레를 흔든다. 막기와 흘리기가 가장 단단하고 (균형 ×1.5), 모든 기술 대기 25% 짧음. 초 오의(X)가 있다"] = "Divine Gauge: fill Divine (100) while fighting to take Divine Form (until you fall). You float and fly, golden armor and a giant divine afterimage follow you, and all skills change (stronger, no domain). Body Arts: a style that fights with elbows, sweeps, knees, stomps and throws. Grab, spin and slam. Three Powers Tremor: every three light or heavy hits the ground shakes underfoot. The sturdiest blocks and deflects (balance x1.5), all skill cooldowns 25% shorter. Has an Ultimate Art (X)",
	["삼재 진동"] = "Three Powers Tremor",
	["승천 팔꿈치"] = "Rising Elbow",
	["쓸어차기"] = "Sweep Kick",
	["목 잡고 무릎"] = "Neck Grab Knee",
	["삼재 진각"] = "Three Powers Stomp",
	["철산고"] = "Iron Mountain Lean",
	["삼재 메치기"] = "Three Powers Throw",
	["앞의 적 셋을 한꺼번에 붙잡아 끌어당긴 뒤 땅에 내리꽂는다. 내리꽂힌 자리마다 땅이 터지며 둘레의 적도 크게 다친다 (보스는 붙잡지 못하고 그 자리에서 맞는다)"] = "Grab three enemies ahead at once, pull them in and slam them into the ground. The ground bursts where each lands, badly hurting nearby enemies too (bosses can't be grabbed and take the hit in place)",
	["지축 진각"] = "Earth Axis Stomp",
	["무릎을 높이 들어 땅을 찍는다. 발밑에서 충격이 사방으로 퍼져 둘레의 적이 크게 튕겨 오른다"] = "Raise your knee high and stomp. A shock spreads in all directions from underfoot, launching nearby enemies high",
	["천근 대회전"] = "Thousand-Pound Great Spin",
	["둘레의 적 다섯을 붙잡아 온몸으로 휘돌린다 (그동안 무적). 도는 동안 닿는 적이 모두 맞고, 마지막에 사방으로 내던지면 떨어진 자리마다 땅이 터진다"] = "Grab five nearby enemies and swing them around with your whole body (invincible meanwhile). Every enemy you touch while spinning is hit, and at the end you hurl them all outward; the ground bursts where each lands",
	["초 오의. 얻을 때의 그 동작 그대로 (그동안 무적): 둘레의 적 여섯을 붙잡아 팔을 여섯 번 휘두르며 몸째 휘돌린다. 무릎을 들어 땅을 찍는 순간 모두를 사방으로 내던져 떨어진 자리마다 천지가 갈라진다 (보스는 붙잡지 못하고 그 자리에서 맞는다)"] = "Ultimate Art. The same motion as when you earned it (invincible meanwhile): grab six nearby enemies and swing your arms six times, spinning them with your body. The moment you raise your knee and stomp, you hurl them all outward and heaven and earth split where each lands (bosses can't be grabbed and take the hit in place)",
	["천지인 삼연격"] = "Heaven-Earth-Man Triple Strike",
	["각성. 한 걸음 파고들며 하늘로 올려 치고 (적이 뜬다), 땅으로 내리꽂고, 사람의 정권으로 앞을 꿰뚫는다. 세 번의 타격이 하나로 이어진다 (무적)"] = "Awakened. Step in and uppercut skyward (enemy launches), slam down to earth, and pierce ahead with man's straight punch. Three blows in one flow (invincible)",
	["지축 진동"] = "Earth Axis Tremor",
	["각성. 땅을 찍으면 충격이 안에서 바깥으로 세 겹의 물결이 되어 퍼져 나간다. 마지막에 발밑이 크게 솟는다"] = "Awakened. Stomp and the shock spreads outward in three waves. At the end the ground underfoot heaves up",
	["각성. 하늘·땅·사람의 기를 1초 모았다가 단 한 번 지른다. 주먹이 앞으로 길게 꿰뚫고 (무적), 뒤따르는 충격이 부채꼴로 퍼지고, 먼 땅이 터진다"] = "Awakened. Gather the ki of heaven, earth and man for 1s and strike once. The fist pierces far ahead (invincible), a following shock spreads in a cone, and the distant ground bursts",
	["천지개벽 · 각"] = "Heaven and Earth Split · Awakened",
	["각성 초 오의. 컷씬 동작 그대로 (그동안 무적): 팔을 여섯 번 휘두를 때마다 몸 둘레로 큰 물결이 터져 나간다 (점점 커진다). 무릎을 들어 땅을 찍는 순간 천지가 갈라져 둘레 48칸이 터지고, 바깥 70칸까지 충격이 퍼진다"] = "Awakened Ultimate Art. The cutscene motion itself (invincible meanwhile): each of six arm swings bursts a big wave around you (growing each time). When you raise your knee and stomp, heaven and earth split, blasting a 48-stud radius with shock reaching out to 70 studs",
	["신강림"] = "Divine Descent",
	["신벌"] = "Divine Punishment",
	["천룡각"] = "Heavenly Dragon Kick",
	["회천각"] = "Heaven Spin Kick",
	["낙성슬"] = "Falling Star Knee",
	["신 강하각"] = "Divine Dive Kick",
	["신 천벌권"] = "Divine Judgment Fist",
	["비천 신각"] = "Flying Divine Kick",
	["하늘을 날며 가까운 적 다섯 사이를 번개처럼 오가며 두 번씩 걷어찬다 (무적). 마지막에 내려서며 둘레가 터진다"] = "Fly between five nearby enemies like lightning, kicking each twice (invincible). At the end you land and the area bursts",
	["천강 낙하"] = "Heavenly Plunge",
	["하늘 높이 솟았다가 가장 가까운 적을 향해 벼락처럼 내리꽂힌다 (무적). 떨어진 자리에서 땅이 네 갈래로 갈라지며 금빛 균열이 멀리 달린다"] = "Soar high, then crash down on the nearest enemy like lightning (invincible). The ground splits four ways where you land, golden cracks racing far",
	["신행 십이각"] = "Divine Twelve Kicks",
	["신의 걸음으로 둘레의 적들 사이를 오가며 열 번 걷어차고 (무적), 앞을 부채꼴로 쓸어 찬 뒤, 하늘에서 내리찍는 발꿈치로 둘레 30칸의 땅을 가른다"] = "Move among nearby enemies with divine steps kicking ten times (invincible), sweep a cone ahead, then split the ground in a 30-stud radius with a heel drop from the sky",
	["천지개벽 · 신"] = "Heaven and Earth Split · Divine",
	["신의 초 오의 (그동안 무적). 얻을 때의 그 동작: 팔을 여섯 번 휘두르는 동안 둘레 70칸의 시간이 멈춰 모두 묶이고 세상에 금이 간다. 무릎을 들어 땅을 찍는 순간 하늘과 땅이 갈라지며 모두 부서진다"] = "Divine Ultimate Art (invincible meanwhile). The motion from when you earned it: while you swing your arms six times, time stops in a 70-stud radius binding everyone and the world cracks. When you raise your knee and stomp, heaven and earth split and everything shatters",
	["철쇄금나수"] = "Iron Chain Grappling Hand",
	["쇠사슬처럼 붙잡는 손. 치고 받기보다 붙잡아 메치고 집어 던진다. 던진 적이 다른 적과 부딪혀 함께 쓰러진다."] = "Hands that grab like iron chains. Rather than trading blows, grab, throw and hurl. Thrown enemies crash into others and go down together.",
	["금나: 기술이 적을 붙잡아 메치거나 던진다 (던진 적에 부딪힌 적도 다친다). 모든 타격이 균형을 1.3배 깎는다"] = "Grapple: skills grab enemies to slam or throw them (enemies hit by a thrown enemy are hurt too). Every hit wears balance 1.3x",
	["쇄수"] = "Chain Hand",
	["견비"] = "Shoulder Lock",
	["금나수"] = "Grappling Hand",
	["업어치기"] = "Shoulder Throw",
	["금나 메치기"] = "Grapple Slam",
	["앞의 적을 붙잡아 끌어당긴 뒤 땅에 내리꽂는다. 둘레의 적도 흔들린다"] = "Grab the enemy ahead, pull them in and slam them into the ground. Nearby enemies are shaken too",
	["철쇄 던지기"] = "Iron Chain Throw",
	["적을 붙잡아 앞으로 멀리 집어 던진다. 날아가는 적에 부딪힌 적과 떨어진 자리의 적도 다친다"] = "Grab an enemy and hurl them far ahead. Enemies hit by the flying body and those where it lands are hurt too",
	["둘레의 적 셋을 한꺼번에 붙잡아 크게 휘돌린다. 도는 동안 닿는 적이 모두 맞고, 마지막에 사방으로 내던진다"] = "Grab three nearby enemies at once and swing them in a big circle. Every enemy you touch while spinning is hit, then you hurl them outward",
	["역류반격권"] = "Counter Current Fist",
	["흐름을 거스르는 주먹. 먼저 치지 않는다. 받아칠 자세를 잡고 기다렸다가, 상대가 들어오는 순간 그 힘을 그대로 되돌려 준다."] = "A fist against the current. It never strikes first. It takes a counter stance and waits, and the moment the foe comes in, returns their force as is.",
	["역류: 흘리기 판정이 넓고 (0.34초), 흘리기에 성공하면 저절로 되받아친다. 받아칠 자세 (E·G) 동안 맞으면 피해 없이 되받아친다"] = "Countercurrent: wide deflect window (0.34s), and successful deflects counter automatically. Hits taken during counter stance (E, G) deal no damage and are countered",
	["역수"] = "Reverse Hand",
	["류수"] = "Flow Hand",
	["회선장"] = "Circling Palm",
	["역류세"] = "Countercurrent Stance",
	["0.9초 동안 받아칠 자세. 그 사이 맞으면 피해 없이 상대 앞으로 미끄러져 크게 되받아친다"] = "A 0.9s counter stance. If hit during it, take no damage, slide up to the foe and counter hard",
	["회류파"] = "Return Wave",
	["두 손을 돌려 앞으로 거센 물결을 밀어낸다. 앞의 적을 모두 밀어내며 균형을 크게 깎는다"] = "Turn your hands to push a strong wave ahead. Pushes away every enemy ahead and wears their balance a lot",
	["역천반격"] = "Defy Heaven Counter",
	["1.6초 동안 받아칠 자세 (무적은 아니다). 맞으면 상대 앞으로 미끄러져 세 번 몰아치고 둘레로 역류가 터진다. 아무도 치지 않으면 끝에 역류만 터진다"] = "A 1.6s counter stance (not invincible). If hit, slide up to the foe, strike three times, and a backflow bursts around you. If no one hits you, only the backflow bursts at the end",
	["질풍연권"] = "Gale Combo Fist",
	["거센 바람처럼 이어지는 주먹. 짧게 파고들어 적을 띄우고, 떠오른 적을 공중에서 몇 번이고 이어 친다. 빠르고 가볍다."] = "Punches that flow like a strong wind. Dart in short, launch the enemy, and keep hitting them in midair. Fast and light.",
	["연타: 몸이 빠르고 (1.1배) 대시 대기가 짧다 (0.8초). 기술이 적에게 파고들어 띄우고, 공중에서 이어 친다"] = "Combo: fast body (1.1x) and short dash cooldown (0.8s). Skills dart in to launch enemies and follow up in the air",
	["질권"] = "Quick Fist",
	["풍권"] = "Wind Fist",
	["연환권"] = "Chain Fist",
	["승풍권"] = "Rising Wind Fist",
	["섬전돌"] = "Flash Rush",
	["가장 가까운 적에게 번개처럼 파고들어 두 번 치고 띄운다 (무적)"] = "Dart at the nearest enemy like lightning, hit twice and launch (invincible)",
	["연환비격"] = "Chain Flying Strike",
	["파고들어 띄운 적을 따라 뛰어올라 공중에서 세 번 치고 땅에 내리꽂는다"] = "Follow a launched enemy into the air, hit three times and slam them down",
	["질풍백렬"] = "Gale Hundred Blows",
	["둘레의 적 여섯 사이를 바람처럼 오가며 둘씩 치고 띄운다. 마지막에 한가운데서 바람이 터진다 (무적)"] = "Move between six nearby enemies like wind, hitting and launching them in pairs. At the end wind bursts at the center (invincible)",
	["산악붕권"] = "Mountain Crusher Fist",
	["산을 무너뜨리는 주먹. 느리고 무겁다. Z를 눌러 모았다가 놓으면 땅이 갈라지며 적이 멀리 날아간다. 한 방 한 방이 균형을 크게 깎는다."] = "A fist that topples mountains. Slow and heavy. Hold Z to charge and release to split the ground and send enemies flying. Every blow wears a lot of balance.",
	["붕산: Z를 길게 누르면 (최대 1.6초) 강타가 2.6배까지 세진다. 몸이 느리지만 (0.92배) 모든 타격이 균형을 1.4배, 밀어냄을 1.2배"] = "Crush: hold Z (up to 1.6s) to power heavy strikes up to 2.6x. The body is slow (0.92x), but every hit deals balance x1.4 and knockback x1.2",
	["붕권"] = "Crush Fist",
	["산권"] = "Mountain Fist",
	["추산"] = "Falling Mountain",
	["지진각"] = "Earthquake Kick",
	["붕산일권"] = "Mountain Crusher Strike",
	["지열각"] = "Earth Split Kick",
	["발을 굴러 앞으로 땅을 가른다. 갈라진 금을 따라 바위가 차례로 솟는다"] = "Stamp to split the ground ahead. Rocks rise one after another along the crack",
	["낙석추"] = "Falling Rock Hammer",
	["가장 가까운 적 머리 위에 집채만 한 바위를 떨어뜨린다"] = "Drop a house-sized boulder on the nearest enemy's head",
	["천붕지열"] = "Sky Falls, Earth Splits",
	["1초 동안 힘을 모아 땅을 내리친다. 둘레의 땅이 산처럼 솟았다 무너지며 모두 띄우고, 떨어질 때 한 번 더 친다"] = "Gather strength for 1s and strike the ground. The ground around you rises like a mountain and collapses, launching everyone and hitting again as they fall",
	["빙혼신장"] = "Ice Soul Divine Palm",
	["사경의 경지에 오른 자만이, 북방 설산 얼음 벼랑 아래 얼어붙은 폭포 앞의 빙혼노니를 만난다"] = "Only those at Brink meet the Ice Soul Nun before the frozen waterfall under the ice cliffs of the northern snow mountains",
	["얼음의 넋을 담은 손바닥. 닿는 곳마다 서리가 내리고, 네 번 맞히면 상대가 얼어붙는다. 오의는 둘레를 만년 빙하로 덮는다."] = "A palm that holds the soul of ice. Frost falls wherever it touches, and four hits freeze the foe. Its secret art covers the area in an eternal glacier.",
	["빙결: 네 번 맞힐 때마다 상대 자리에 서리가 터지며 1초 동안 얼어붙는다 (움직이지 못함)"] = "Freeze: every four hits frost bursts at the target, freezing them for 1s (can't move)",
	["빙결"] = "Freeze",
	["빙장"] = "Ice Palm",
	["설장"] = "Snow Palm",
	["한풍장"] = "Cold Wind Palm",
	["빙혼장"] = "Ice Soul Palm",
	["빙벽장"] = "Ice Wall Palm",
	["빙창진"] = "Ice Spear Formation",
	["앞으로 얼음 창이 줄지어 솟는다"] = "Ice spears rise in a row ahead",
	["한빙결"] = "Frozen Seal",
	["둘레를 얼려 적을 1.6초 동안 얼음에 가둔 뒤 얼음째 깨뜨린다"] = "Freeze the area, trapping enemies in ice for 1.6s, then shatter it with them inside",
	["만년빙하"] = "Eternal Glacier",
	["하늘에서 얼음 기둥이 둘레의 적 여덟에게 차례로 내리꽂히고, 마지막에 발밑에서 빙하가 솟는다"] = "Ice pillars fall from the sky onto eight nearby enemies in turn, then a glacier rises underfoot",
	["천옥신권"] = "Heavenly Jade Divine Fist",
	["무극의 경지에 오른 자만이, 서쪽 끝 석림의 옥 기둥 사이에 앉은 옥진인을 만난다"] = "Only those at Limitless meet the Jade Sage seated among the jade pillars of the far-west stone forest",
	["하늘의 옥을 깎아 만든 주먹. 맞을 때마다 옥 결정이 피어나 쌓이고, 오의를 펼치면 둘레가 옥의 숲이 되어 모두 꿰뚫는다."] = "A fist carved from heaven's jade. Jade crystals bloom and stack with each hit, and its secret art turns the area into a jade forest that pierces everything.",
	["옥결: 네 번 맞힐 때마다 상대 자리에 옥 결정이 피어 터진다. 몸이 단단해 받는 피해 10% 덜"] = "Jade Crystal: every four hits a jade crystal blooms and bursts at the target. A sturdy body takes 10% less damage",
	["옥결"] = "Jade Crystal",
	["옥수"] = "Jade Hand",
	["벽옥"] = "Green Jade",
	["옥광장"] = "Jade Light Palm",
	["천옥권"] = "Heavenly Jade Fist",
	["옥쇄일권"] = "Jade Shatter Strike",
	["옥창림"] = "Jade Spear Forest",
	["앞으로 옥 기둥이 줄지어 솟아 꿰뚫는다"] = "Jade pillars rise in a row ahead, piercing",
	["옥우"] = "Jade Rain",
	["둘레의 적 다섯 머리 위로 옥 덩이가 떨어진다"] = "Chunks of jade fall on five nearby enemies",
	["천옥결계"] = "Heavenly Jade Barrier",
	["발밑에서 옥의 숲이 넓게 자라나 2.4초 동안 둘레의 적을 모두 꿰뚫는다"] = "A jade forest grows wide underfoot, piercing every nearby enemy for 2.4s",
	["천종신권"] = "Heavenly Bell Divine Fist",
	["반선의 경지에 오른 자만이, 동북쪽 끝 단풍산 꼭대기의 낡은 종 아래 선 종지기를 만난다"] = "Only those at Half-Immortal meet the Bell Keeper under the old bell atop the maple mountain in the far northeast",
	["하늘의 종을 울리는 주먹. 칠 때마다 울림이 쌓이고, 다섯 번째에 종소리가 둘레로 퍼져 모두 흔든다. 오의는 하늘에 거대한 종을 건다."] = "A fist that rings heaven's bell. Each blow builds resonance, and on the fifth the bell's toll spreads and shakes everyone around. Its secret art hangs a giant bell in the sky.",
	["울림: 다섯 번 맞힐 때마다 종소리 파동이 둘레로 퍼진다 (둘레 모두 맞는다). 막기가 단단하다 (막을 때 받는 피해 절반)"] = "Resonance: every five hits a bell wave spreads around you (everyone nearby is hit). Sturdy guard (half damage when blocking)",
	["종소리"] = "Bell Toll",
	["종타"] = "Bell Strike",
	["명타"] = "Ringing Strike",
	["범종장"] = "Temple Bell Palm",
	["대종권"] = "Great Bell Fist",
	["천종일격"] = "Heavenly Bell Strike",
	["종명파"] = "Bell Ring Wave",
	["앞으로 종소리를 내질러 부채꼴 안의 적을 모두 흔들고 막기를 깨뜨린다"] = "Shout a bell toll ahead, shaking every enemy in the cone and breaking their guard",
	["금종조"] = "Golden Bell Cover",
	["몸을 금빛 종으로 덮고 1.2초 동안 둘레를 울린다. 그동안 오는 공격은 모두 되받아친다"] = "Cover yourself with a golden bell and ring the area for 1.2s. Every incoming attack is countered meanwhile",
	["천종만향"] = "Heavenly Bell Ten Thousand Echoes",
	["하늘에 거대한 종이 걸리고 열 번 울린다. 울릴 때마다 둘레로 파동이 퍼져 모두 친다"] = "A giant bell hangs in the sky and rings ten times. Each ring sends a wave through the area hitting everyone",
	["명경권"] = "Clear Mirror Fist",
	["한 번 환생한 몸으로, 서북쪽 끝 운무 차밭 한가운데 거울 연못 앞의 명경선을 찾아가라"] = "After one rebirth, find the Clear Mirror Immortal by the mirror pond in the middle of the misty tea fields at the far northwest",
	["맑은 거울과 같은 주먹. 거울 속의 내가 함께 싸운다. 네 번 맞히면 거울 분신이 같은 자리를 되받아 치고, 받아칠 자세에서 맞으면 그 힘을 거울처럼 되돌린다."] = "A fist like a clear mirror. Your self in the mirror fights alongside you. Every four hits a mirror clone strikes the same spot, and hits taken in counter stance are returned like a mirror.",
	["거울: 네 번 맞힐 때마다 거울 속 분신이 나타나 같은 자리를 되받아 친다. E는 받아칠 자세 (맞으면 피해 없이 되받아친다)"] = "Mirror: every four hits a mirror clone appears and strikes the same spot. E is a counter stance (if hit, no damage and you counter)",
	["거울 분신"] = "Mirror Clone",
	["경수"] = "Mirror Hand",
	["명수"] = "Bright Hand",
	["쌍경각"] = "Twin Mirror Kick",
	["파경권"] = "Mirror Break Fist",
	["명경일장"] = "Clear Mirror Palm",
	["명경지수"] = "Still Water Mirror",
	["0.8초 동안 거울처럼 고요한 자세. 맞으면 피해 없이 상대 앞에 나타나 그 힘을 되돌려 친다"] = "A 0.8s stance as still as a mirror. If hit, take no damage, appear before the foe and return their force",
	["경중분신"] = "Mirror Clones",
	["둘레의 적 넷 앞에 거울 속의 내가 하나씩 나타나 두 번씩 친다"] = "A mirror self appears before each of four nearby enemies and strikes twice",
	["만경회랑"] = "Hall of Ten Thousand Mirrors",
	["둘레에 거울이 열 장 선다. 거울마다 빛이 튀어 둘레의 적 열에게 차례로 꽂힌다"] = "Ten mirrors stand around you. Light bounces from each into ten nearby enemies in turn",
	["천경파쇄"] = "Heaven Mirror Shatter",
	["초 오의. 하늘과 땅이 거울이 된다. 둘레의 적 여덟 앞에 거울 속의 내가 셋씩 나타나 몰아치고, 마지막에 거울이 모두 깨지며 둘레가 터진다"] = "Ultimate Art. Sky and earth become mirrors. Three mirror selves appear before each of eight nearby enemies and strike, and at the end every mirror shatters and the area bursts",
	["초·천룡파천장"] = "Ultimate Heavenly Dragon Sky-Breaker Palm",
	["천룡파천장을 익히고 천외천에 오른 자만이, 천룡봉 동쪽 구름 위 용의 등뼈 바위에 선 천룡진인을 만난다"] = "Only those who know the Heavenly Dragon Palm and reach Beyond Heaven meet the Heavenly Dragon Sage on the dragon-spine rock above the clouds east of Dragon Peak",
	["천룡파천장의 끝. 장풍 하나하나가 용이 되어 날아가고, 오의를 펼치면 황금 천룡이 하늘을 덮는다. 멀리서도, 가까이서도 무섭다."] = "The end of the Heavenly Dragon Palm. Each blast flies as a dragon, and its secret art covers the sky with a golden dragon. Fearsome at range and up close.",
	["천룡기: Z를 0.8초만 눌러도 장풍이 가득 모인다. 연격 네 번째와 강타가 용의 장풍. 네 번 맞힐 때마다 작은 용이 상대를 물어뜯는다"] = "Dragon Ki: just 0.8s of holding Z fully charges a blast. The fourth combo hit and heavy strikes are dragon blasts. Every four hits a small dragon bites the target",
	["용의 이빨"] = "Dragon Fang",
	["천룡조"] = "Heavenly Dragon Claw",
	["천룡미"] = "Heavenly Dragon Tail",
	["잠룡승천"] = "Hidden Dragon Ascends",
	["현룡파천"] = "Manifest Dragon Breaks Heaven",
	["항룡파천장"] = "Subduing Dragon Sky-Breaker",
	["황룡유회"] = "Golden Dragon's Regret",
	["금빛 용의 기운이 앞의 적을 모두 꿰뚫고 나아간다"] = "Golden dragon energy pierces every enemy ahead",
	["비룡천"] = "Flying Dragon Heaven",
	["용처럼 솟구치며 둘레의 적을 모두 하늘로 올려 친다"] = "Rise like a dragon, launching every nearby enemy skyward",
	["구룡천강"] = "Nine Dragons Descend",
	["땅을 뚫고 금룡 아홉이 둘레에서 솟아 하늘로 감아 오른 뒤, 차례로 적에게 내리꽂히고 한가운데서 터진다"] = "Nine gold dragons burst from the ground and coil into the sky, then slam into enemies one by one and burst at the center",
	["천룡멸세"] = "Heavenly Dragon World Ender",
	["초 오의. 하늘이 갈라지며 산만 한 황금 천룡이 내려온다. 여덟 번 내리꽂히고 마지막에 앞으로 하늘을 태우는 숨을 뿜는다"] = "Ultimate Art. The sky splits and a mountain-sized golden dragon descends. It slams down eight times, then breathes a sky-burning blast forward",
	["천하패권"] = "Overlord's Supremacy",
	["네 번 환생해 권왕신권을 익힌 자만이, 동쪽 끝 황사 협곡의 무너진 왕좌에 앉은 패왕을 만난다"] = "Only those reborn four times who know the Fist King Fist meet the Overlord seated on the fallen throne in the yellow-dust canyon in the far east",
	["권왕을 넘어선 패자의 주먹. 꾸밈이 없다. 파고들고, 붙잡아 내던지고, 단 한 주먹으로 앞을 모두 지운다. 여섯 번 맞히면 패기에 눌려 둘레의 적이 무릎을 꿇는다."] = "An overlord's fist beyond the Fist King. No flourish. Dart in, grab and hurl, erase everything ahead with a single punch. Every six hits, nearby enemies are forced to their knees by sheer presence.",
	["패기: 여섯 번 맞힐 때마다 둘레로 패기가 터져 적이 무릎을 꿇는다 (오래 굳는다). 앞의 권왕신권처럼 공격의 10%를 비켜 간다"] = "Presence: every six hits presence bursts around you and enemies drop to their knees (frozen for long). Like the Fist King Fist, 10% of attacks miss you",
	["패기"] = "Presence",
	["패권"] = "Supremacy Fist",
	["왕권"] = "King Fist",
	["패왕승천"] = "Overlord Ascends",
	["천하일격"] = "Strike Under Heaven",
	["패왕추"] = "Overlord Hammer",
	["패왕돌진"] = "Overlord Rush",
	["가장 가까운 적 셋 사이를 차례로 파고들어 한 주먹씩 꽂는다 (무적)"] = "Dart between the three nearest enemies in turn, landing a punch on each (invincible)",
	["패왕투"] = "Overlord Throw",
	["앞의 적을 붙잡아 머리 위로 들어 앞으로 내던진다. 날아가는 적에 부딪힌 적과 떨어진 자리의 적이 모두 다친다"] = "Grab the enemy ahead, lift them overhead and hurl them forward. Enemies hit by the flying body and where it lands are all hurt",
	["천하무쌍권"] = "Unrivaled Fist",
	["1초 동안 천하의 기를 한 주먹에 모았다가 앞으로 지른다. 앞의 모든 것이 지워진다"] = "Gather the world's ki into one fist for 1s and strike forward. Everything ahead is erased",
	["패천멸지"] = "Overlord Breaks Heaven and Earth",
	["초 오의. 하늘이 패기에 갈라져 2.4초 동안 둘레의 적에게 금빛 벼락이 쉬지 않고 떨어지고, 마지막에 내가 땅을 내리쳐 둘레를 모두 무너뜨린다"] = "Ultimate Art. The sky splits under your presence and golden lightning falls on nearby enemies nonstop for 2.4s, then you strike the ground and level the area",
	["구미호권"] = "Nine-Tailed Fox Fist",
	["💎 상점의 '구미호권' 게임패스로 얻는다. 강화할수록 꼬리가 늘어난다 (+15에 아홉 꼬리)"] = "💎 Get it with the 'Nine-Tailed Fox Fist' game pass in the shop. More tails grow as you enhance it (nine tails at +15)",
	["푸른 여우불을 두른 요호의 권법. 빠르고 가볍게 스치며, 맞힐 때마다 여우불이 쌓인다. 강화할수록 등 뒤의 꼬리가 늘어난다."] = "The style of a fox spirit cloaked in blue foxfire. Fast and light grazing strikes stack foxfire with every hit. More tails grow behind you as you enhance it.",
	["여우불: 다섯 번 맞힐 때마다 상대 자리에서 푸른 여우불이 터진다. 몸이 가벼워 (1.06배) 공격의 8%를 흘려 보낸다"] = "Foxfire: every five hits blue foxfire bursts at the target. A light body (1.06x) lets 8% of attacks slip past",
	["여우불"] = "Foxfire",
	["호미장"] = "Fox Tail Palm",
	["여우발톱"] = "Fox Claw",
	["월하선각"] = "Moonlit Immortal Kick",
	["구미선풍"] = "Nine-Tail Whirlwind",
	["호혼일격"] = "Fox Soul Strike",
	["호화연무"] = "Foxfire Dance",
	["하늘에 여우불 다섯이 피어 소용돌이치며 내려와, 가까운 적 다섯에게 차례로 꽂혀 푸른 불기둥으로 터진다"] = "Five foxfires bloom in the sky and spiral down, striking five nearby enemies in turn and bursting into blue fire pillars",
	["환영분신"] = "Phantom Clones",
	["푸른 여우 혼령 분신을 남기며 둘레의 적 넷 사이를 스쳐 지나가 할퀸다 (무적). 마지막에 내려서며 여우불이 터진다"] = "Leaving blue fox spirit clones behind, graze between four nearby enemies clawing them (invincible). Foxfire bursts as you land",
	["구미천화"] = "Nine-Tail Heaven Fire",
	["땅에서 거대한 꼬리 혼령 아홉이 솟아 일렁이는 동안 여우불 유성이 둘레의 적에게 쏟아지고, 마지막에 아홉 꼬리가 한가운데로 내리치며 푸른 불이 터진다"] = "Nine giant tail spirits rise from the ground and sway while foxfire meteors rain on nearby enemies; at the end the nine tails slam into the center and blue fire bursts",
	["흑염마검장"] = "Black Flame Demon Sword Palm",
	["💎 상점의 '흑염마검장' 게임패스로 얻는다. 강화할수록 검은 불꽃 검이 둘로 늘고 화려해진다"] = "💎 Get it with the 'Black Flame Demon Sword Palm' game pass in the shop. As you enhance it, the black flame swords grow to two and blaze brighter",
	["검은 불꽃으로 손에 검을 빚어 베는 마검의 권법. 처음엔 한 손, +5부터 두 손에 검이 선다. 강화할수록 불꽃이 짙어지고 보랏빛 · 핏빛으로 타오른다."] = "A demon-sword style that forges swords from black flame in your hands. One hand at first, swords in both hands from +5. As you enhance it, the flames thicken and burn purple and blood red.",
	["흑염 각인: 여섯 번 맞힐 때마다 상대 자리에서 검은 불꽃이 터진다. 마지막 오의 흑염멸천은 하늘에서 불꽃 검이 쏟아진다"] = "Black Flame Brand: every six hits black flame bursts at the target. The final secret art, Black Flame Heaven Ender, rains flaming swords from the sky",
	["흑염 폭발"] = "Black Flame Burst",
	["흑염참"] = "Black Flame Cut",
	["역염참"] = "Reverse Flame Cut",
	["염륜"] = "Flame Ring",
	["마검낙"] = "Demon Sword Drop",
	["흑염일섬"] = "Black Flame Flash",
	["흑염월참"] = "Black Flame Moon Cut",
	["검을 크게 휘둘러 앞으로 검은 초승달 검기를 날린다"] = "Swing the sword wide and launch a black crescent of sword energy ahead",
	["마염천주"] = "Demon Flame Pillars",
	["뛰어올라 검을 땅에 꽂는다. 앞으로 검은 마검이 칼끝부터 땅을 뚫고 줄지어 솟는다"] = "Leap and plant your sword in the ground. Black demon swords burst up tip-first in a line ahead",
	["쌍염십자참"] = "Twin Flame Cross Cut",
	["1초 동안 두 검에 불꽃을 모았다가 교차해 거대한 X자 검기를 앞으로 날린다"] = "Gather flame on both swords for 1s, then cross them to launch a giant X of sword energy ahead",
	["흑염멸천"] = "Black Flame Heaven Ender",
	["초 오의. 하늘에 검은 불의 소용돌이가 열려 2.4초 동안 둘레의 적에게 불꽃 검이 쏟아지고, 마지막에 거대한 마검이 한가운데로 내리꽂히며 둘레에 마검이 솟는다"] = "Ultimate Art. A vortex of black fire opens in the sky and rains flaming swords on nearby enemies for 2.4s, then a giant demon sword slams into the center as demon swords rise all around",
	["[권왕] "] = "[Fist King] ",
	[": 극 모습은 신화 이상 권법에서만"] = ": Apex forms only for Mythic-tier styles and above",
