	["빙산 낙하"] = "Iceberg Drop",
	["설원의 자객들"] = "Snowfield Assassins",
	["혈해 고리"] = "Blood Sea Ring",
	["혈우"] = "Blood Rain",
	["혈마 돌진"] = "Blood Demon Charge",
	["혈교도들아!"] = "Cultists, to me!",
	["혈마 강림"] = "Blood Demon Descends",
	["천마 낙성"] = "Heavenly Demon Meteor",
	["허공 고리"] = "Void Ring",
	["하늘 짓밟기"] = "Sky Stomp",
	["천마 돌격"] = "Heavenly Demon Assault",
