	["천마멸세"] = "Heavenly Demon World Ender",
	["화산탄"] = "Volcanic Bomb",
	["불꽃 고리"] = "Fire Ring",
	["용암 돌진"] = "Lava Charge",
	["불의 귀졸들"] = "Fire Imps",
	["화산 폭발"] = "Volcanic Eruption",
	["모래 질주"] = "Sand Dash",
	["모래 창"] = "Sand Spear",
	["모래 회오리"] = "Sand Whirlwind",
	["무덤의 망령들"] = "Tomb Wraiths",
	["왕의 낙하"] = "King's Fall",
	["천벌"] = "Heavenly Punishment",
	["하늘 문 내려닫기"] = "Sky Gate Slam",
	["천문 고리"] = "Heaven Gate Ring",
	["천병들아!"] = "Heavenly Soldiers, to me!",
	["천문 돌파"] = "Heaven Gate Breakthrough",
	["하늘이 무너진다"] = "The Sky Falls",
	["초월의 시련"] = "Trial of Transcendence",
	["매화를 넘어서겠다고? 그럼 꽃이 지는 모습을 끝까지 보아라. 세 번 피고 세 번 질 때까지 서 있다면 이 부채를 넘겨주지."] = "You want to surpass the plum blossom? Then watch the flowers fall to the end. Stand until they bloom and fall three times, and this fan is yours.",
	["벚꽃비"] = "Cherry Rain",
	["앵선돌진"] = "Cherry Fan Charge",
	["낙화난무"] = "Falling Blossom Flurry",
	["천앵낙하"] = "Heaven Cherry Drop",
	["만개"] = "Full Bloom",
	["극의 시련"] = "Trial of the Apex",
	["세 번을 죽고 세 번을 살았구나. 그래도 아직 부족하다. 내 황혼을 끝까지 버텨 보아라. 해가 지고 달이 뜨는 그 사이에 서 있을 수 있다면, 극을 넘겨주마."] = "You've died three times and lived three times. Still not enough. Endure my twilight to the end. If you can stand in the moment between sunset and moonrise, the Apex is yours.",
	["해의 비"] = "Sun Rain",
	["달의 고리"] = "Moon Ring",
	["월광우"] = "Moonlight Rain",
	["대일낙하"] = "Great Sun Drop",
	["술에 취한 듯 보여도 내 발은 한 번도 헛디딘 적이 없다. 이 비틀거림을 끝까지 버텨 내면, 이 병을 넘겨주마."] = "I may look drunk, but my feet have never missed a step. Endure this stagger to the end and this bottle is yours.",
	["술비"] = "Wine Rain",
	["취선 회오리"] = "Drunken Whirlwind",
	["굴렁쇠"] = "Rolling Hoop",
	["취화"] = "Drunken Fire",
	["만취"] = "Dead Drunk",
	["혈마의 손을 쥐었다고? 그 손톱은 아직 짧다. 내 낫 앞에서 끝까지 서 있어 보아라. 그러면 이 낫을 넘겨주마."] = "You hold the Blood Demon's hand? Those nails are still short. Stand before my scythe to the end, and I'll hand it over.",
	["핏빛 초승달"] = "Crimson Crescent",
	["혈륜"] = "Blood Wheel",
	["혈겸 돌진"] = "Blood Scythe Charge",
	["피의 비"] = "Rain of Blood",
	["혈월"] = "Blood Moon",
	["목선의 시련"] = "Trial of the Tree Sage",
	["숲은 쓰러뜨리는 것이 아니다. 버티는 것이다. 내 대숲의 창과 잎 속에서 끝까지 서 있거든, 나무의 주먹을 가르쳐 주마."] = "A forest isn't something you knock down. It's something that endures. Stand to the end among my bamboo spears and leaves, and I'll teach you the fist of the trees.",
	["죽창 비"] = "Bamboo Spear Rain",
	["대숲 고리"] = "Bamboo Ring",
	["고목 내리치기"] = "Old Tree Smash",
	["은행잎 폭풍"] = "Ginkgo Storm",
	["숲의 분노"] = "Wrath of the Forest",
	["파도를 일으킬 줄 안다고 바다가 되는 건 아니다. 내 바다 한가운데서 끝까지 숨을 쉬거든, 고래의 노래를 가르쳐 주마."] = "Knowing how to raise a wave doesn't make you the sea. Keep breathing in the middle of my sea to the end, and I'll teach you the whale's song.",
	["물방울 비"] = "Droplet Rain",
	["소용돌이 고리"] = "Whirlpool Ring",
	["해일 비"] = "Tsunami Rain",
	["빈칸 비"] = "Blank Rain",
	["격자 고리"] = "Grid Ring",
	["격자의 시련"] = "Trial of the Grid",
	["빈칸을 지우는 법은 알겠지. 그럼 빈칸에 좌표를 긋는 법은? 내 격자 안에서 끝까지 서 있어 봐라. 무너지는 돌을 건너온 다리라면, 버틸 수 있을 거다."] = "You know how to erase a blank. But how about drawing coordinates in one? Stand to the end inside my grid. Legs that crossed the crumbling stones should hold up.",
	["좌표 낙하"] = "Coordinate Drop",
	["좌표 도약"] = "Coordinate Leap",
	["공간 삭제"] = "Space Delete",
	["속도의 시련"] = "Trial of Speed",
	["저승길은 급할수록 멀다 했다. 나는 그 길을 누구보다 빨리 걸었다. 내 빠르기를 눈으로 따라잡거든, 그 걸음을 가르쳐 주마."] = "They say the road to the afterlife is longer the more you hurry. I walked it faster than anyone. Keep up with my speed with your eyes, and I'll teach you that stride.",
	["섬전"] = "Flash",
	["광침비"] = "Light Needle Rain",
	["음속 고리"] = "Sonic Ring",
	["잔상 돌격"] = "Afterimage Assault",
	["꿈의 시련"] = "Trial of Dreams",
	["꿈속에서도 정신을 붙들어야 한다. 내 꿈길 끝까지 정신을 놓지 않거든, 그 걸음을 가르쳐 주마. 꿈에서 입은 상처도 아프다."] = "Even in a dream you must keep hold of your mind. Stay awake to the end of my dream path and I'll teach you that walk. Wounds taken in dreams still hurt.",
	["잠의 별비"] = "Sleepy Star Rain",
	["꿈문 고리"] = "Dream Door Ring",
	["몽유 돌진"] = "Dreamwalk Charge",
	["달 조각"] = "Moon Shard",
	["별을 쥐었다고 별을 부리는 건 아니다. 내 별의 돔 아래서 끝까지 서 있거든, 이 지팡이 끝의 별을 네게 걸어 주마."] = "Holding a star doesn't mean you command stars. Stand to the end under my dome of stars, and I'll hang the star at this staff's tip on you.",
	["별똥비"] = "Shooting Star Rain",
	["성좌 고리"] = "Constellation Ring",
	["메테오"] = "Meteor",
	["번개를 쥐었다고 번개가 되는 건 아니다. 내 벼락을 세 번 맞고도 서 있거든, 이 토시를 네 팔에 채워 주마."] = "Holding lightning doesn't make you lightning. Take three of my bolts and still stand, and I'll fasten these bracers on your arms.",
	["벼락 비"] = "Lightning Rain",
	["뇌전 고리"] = "Lightning Ring",
	["뇌광 돌진"] = "Thunderlight Charge",
	["천뢰"] = "Heavenly Thunder",
	["만월 고리"] = "Full Moon Ring",
	["월광 돌진"] = "Moonlight Charge",
	["월하 낙성"] = "Moonlit Meteor",
	["일륜 낙하"] = "Sun Wheel Drop",
	["일식"] = "Eclipse",
	["월출장"] = "Moonrise Palm",
	["월륜각"] = "Moon Wheel Kick",
	["월영합벽"] = "Moon Shadow Union",
	["월광낙하"] = "Moonlight Drop",
	["둘레의 적 여섯 머리 위로 작은 달이 떨어져 차가운 달빛 기둥이 되어 터진다"] = "Small moons fall on six nearby enemies and burst into pillars of cold moonlight",
	["청운 마을"] = "Cheongun Village",
	["대나무 숲"] = "Bamboo Forest",
	["흑호채 (산적 소굴)"] = "Black Tiger Fort (bandit den)",
	["비류 폭포 계곡"] = "Flying Falls Valley",
	["상급 수련장"] = "Advanced Training Grounds",
	["청운 들판"] = "Cheongun Fields",
	["강호 들판"] = "Martial World Fields",
	["혈월곡"] = "Blood Moon Valley",
	["북방 설산"] = "Northern Snow Mountains",
	["독안개 늪"] = "Poison Mist Swamp",
	["붉은 황야"] = "Red Wasteland",
	["서해 절벽"] = "West Sea Cliffs",
	["혈교 본산"] = "Blood Cult Headquarters",
	["허공 균열"] = "Void Rift",
	["화염산"] = "Fire Mountain",
	["사왕릉 (모래 왕릉)"] = "Snake King's Tomb (sand tomb)",
	["천외봉 운해"] = "Beyond Peak Cloud Sea",
	["창해각 (바다 사당)"] = "Azure Sea Pavilion (sea shrine)",
	["서해 절벽 남쪽 바닷가 사당에 파도와 함께 숨 쉬는 노인이 있다더라"] = "They say an old man breathes with the waves at a seaside shrine south of the West Sea Cliffs",
	["바다는 막지 않는다. 덮을 뿐이다."] = "The sea doesn't block. It covers.",
	["창해옹"] = "Old Man of the Azure Sea",
	["염화단 (불 제단)"] = "Flame Altar",
	["동쪽 붉은 황야 너머, 꺼지지 않는 불 제단에 불을 다루는 노장이 산다더라"] = "They say a veteran who handles fire lives at an undying fire altar beyond the red wasteland to the east",
	["불은 묻지 않는다. 다 태울 뿐이다."] = "Fire doesn't ask. It just burns everything.",
	["염백"] = "Yeombaek",
	["일월대"] = "Sun-Moon Altar",
	["풍신대 (바람의 언덕)"] = "Wind God Hill (hill of winds)",
	["남서쪽 먼 언덕, 바람이 그치지 않는 곳에 바람을 차는 사람이 산다더라"] = "They say someone who kicks the wind lives on a far southwest hill where the wind never stops",
	["바람은 잡을 수 없다. 그래서 막을 수도 없다."] = "You can't catch the wind. So you can't block it either.",
	["풍백"] = "Pungbaek",
	["태허호 (호수 정자)"] = "Great Void Lake (lake pavilion)",
	["남서쪽 호수 한가운데 정자에 물처럼 앉은 노인이 있다더라"] = "They say an old man sits like water in a pavilion in the middle of the southwest lake",
	["물은 다투지 않는다. 그래서 이긴다."] = "Water doesn't fight. That's why it wins.",
	["수월진인"] = "Moon-on-Water Sage",
	["금강사"] = "Diamond Temple",
	["북동쪽 돌 기단 위 절에서 종소리가 끊이지 않는다더라"] = "They say the bell never stops ringing at the temple on the stone terrace to the northeast",
	["부서지지 않는 몸이 곧 부서지지 않는 마음이다."] = "An unbreakable body is an unbreakable mind.",
	["혜공대사"] = "Grand Master Hyegong",
	["매화원"] = "Plum Garden",
	["북서쪽 매화 숲 깊은 곳에 꽃잎과 함께 춤추는 여인이 있다더라"] = "They say a woman dances with the petals deep in the plum forest to the northwest",
	["꽃은 한 번에 핀다. 망설이는 순간 진다."] = "A flower blooms all at once. Hesitate and it falls.",
	["매향선자"] = "Plum Fragrance Fairy",
	["천룡봉"] = "Heavenly Dragon Peak",
	["동쪽 끝 바위 봉우리, 금빛 용 기둥 아래에 노인이 산다더라"] = "They say an old man lives beneath a golden dragon pillar on a rocky peak at the far east",
	["용은 엎드려 기다리다 하늘을 가른다."] = "A dragon lies low and waits, then splits the sky.",
	["용천노조"] = "Dragon Spring Patriarch",
	["무영곡"] = "Shadowless Valley",
	["서쪽 끝 검은 골짜기에 발소리 없는 그림자가 산다더라"] = "They say a shadow with no footsteps lives in the black valley at the far west",
	["보이는 발은 이미 늦은 발이다."] = "A foot you can see is already a late foot.",
	["무영객"] = "Shadowless Wanderer",
	["뇌운 고원"] = "Storm Plateau",
	["남동쪽 쇠기둥 고원에 번개가 떨어지지 않는 날이 없다더라"] = "They say lightning strikes the iron-pillar plateau to the southeast every single day",
	["생각하는 동안 이미 늦는다. 몸이 먼저 나가야 한다."] = "While you think, you're already late. The body has to move first.",
	["뇌정진군"] = "Thunder Lord",
	["취선 주막"] = "Drunken Immortal Inn",
	["남쪽 주막에 늘 취해 있는 노인이 있는데, 넘어지는 걸 본 사람이 없다더라"] = "They say an old man at the southern inn is always drunk, yet no one has ever seen him fall",
	["취한 자는 넘어지지 않는다. 넘어지는 척할 뿐이지."] = "A drunk doesn't fall. He only pretends to.",
	["취선옹"] = "Old Drunken Immortal",
	["단풍산"] = "Maple Mountain",
	["석림"] = "Stone Forest",
	["거균림 (버섯 숲)"] = "Giant Mushroom Forest",
	["운무 차밭"] = "Misty Tea Fields",
	["세상 끝 벼랑"] = "World's End Cliffs",
	["황사 협곡"] = "Yellow Dust Canyon",
	["북명 빙원"] = "Northern Ice Plains",
	["서역 사구"] = "Western Dunes",
	["동극 불길 평원"] = "Eastern Ember Plains",
	["무명 노인"] = "Nameless Old Man",
	["운해 끝자락"] = "Edge of the Cloud Sea",
	["길은 늘 열려 있었다. 걸어온 사람이 드물었을 뿐."] = "The road was always open. Few ever walked it.",
	["남서쪽 세상 끝, 구름이 땅에 닿는 곳에 이름 없는 노인이 앉아 있다더라"] = "They say a nameless old man sits at the southwest end of the world, where the clouds touch the ground",
	["시원자"] = "Origin Sage",
	["천외봉"] = "Beyond Peak",
	["처음에는 아무것도 없었다. 그래서 무엇이든 될 수 있었다."] = "At first there was nothing. So anything could be.",
	["북쪽 끝 구름바다 위, 하늘에 닿은 봉우리 아래에 세상의 처음을 아는 이가 서 있다더라"] = "They say one who knows the beginning of the world stands beneath a sky-high peak above the northern cloud sea",
	["권존"] = "Fist Sovereign",
	["해는 지고 달은 뜬다. 나는 늘 그 사이에 서 있었다."] = "The sun sets and the moon rises. I have always stood between them.",
	["동남쪽 세상 끝, 해와 달이 함께 뜨는 단 위에 주먹 하나로 정점에 선 이가 있다더라"] = "They say one who reached the summit with a single fist stands on an altar at the southeast end of the world, where sun and moon rise together",
	["영겁노인"] = "Eternal Elder",
	["천 개의 계단"] = "Thousand Stairs",
	["흘러간 시간은 돌아오지 않는다. 그래서 한 수 한 수를 아껴 쓴다."] = "Time that has flowed never returns. So I spend each move carefully.",
	["북서쪽 끝, 구름까지 닿은 천 개의 계단 위에 시간을 멈춘 노인이 서 있다더라"] = "They say an old man who stopped time stands atop a thousand stairs reaching the clouds at the far northwest",
	["거신상의 발치"] = "Foot of the Colossus",
	["수정 들판 한가운데"] = "Middle of the Crystal Fields",
	["비류 폭포 뒤"] = "Behind the Flying Falls",
	["북방 설산의 얼음 벼랑"] = "Ice cliffs of the northern snow mountains",
	["독안개 늪의 무너진 사당"] = "Ruined shrine in the Poison Mist Swamp",
	["강호의 전설"] = "Legend of the Martial World",
	["칼의 산 · 굶주린 길"] = "Mountain of Blades · Hungry Road",
	["강호의 문"] = "Gate of the Martial World",
	["첫 주먹"] = "First Fist",
	["강타"] = "Heavy Strike",
	["첫 기술"] = "First Skill",
	["들판의 무뢰배"] = "Field Thugs",
	["몸을 만드는 법"] = "Building the Body",
	["이류의 문턱"] = "Threshold of Second-Rate",
	["산적의 그림자"] = "Shadow of the Bandits",
	["사부를 찾아서"] = "Seeking a Master",
	["사부의 시험"] = "The Master's Test",
	["첫 진짜 권법"] = "First Real Style",
	["손에 익히기"] = "Getting It in Your Hands",
	["일류의 벽"] = "The First-Rate Wall",
	["두 번째 사부"] = "A Second Master",
	["특급에 오르다"] = "Reaching Elite",
	["흑호채"] = "Black Tiger Fort",
	["오의를 열어라"] = "Unlock the Secret Art",
	["심법 두루마리"] = "Manual Scrolls",
	["서해의 해적"] = "Pirates of the West Sea",
	["심법 셋"] = "Three Manuals",
	["더 많은 사부"] = "More Masters",
	["천층탑"] = "Thousand-Floor Tower",
	["혈월곡의 혈랑"] = "Blood Wolf of Blood Moon Valley",
	["절정에 오르다"] = "Reaching Peak",
	["네 번째 권법"] = "A Fourth Style",
	["숙련과 각성"] = "Mastery and Awakening",
	["초절정의 몸"] = "A Supreme Peak Body",
	["설산의 빙마"] = "Ice Demon of the Snow Mountain",
	["화경에 들다"] = "Entering Transformation",
	["첫 깨달음"] = "First Insight",
	["혈교의 그림자"] = "Shadow of the Blood Cult",
	["현경의 고요"] = "Mystic Stillness",
	["혈마"] = "Blood Demon",
	["두 번째 깨달음"] = "Second Insight",
	["사경의 문"] = "Gate of Brink",
	["생사의 경계"] = "Between Life and Death",
	["신화경에 들다"] = "Entering Mythic",
	["각성 권법"] = "Awakened Style",
	["천상의 문"] = "Gate of Heaven",
	["천상의 첫 사냥"] = "First Hunt in the Heavens",
	["무극에 오르다"] = "Reaching Limitless",
	["이름 없는 노인"] = "The Nameless Old Man",
	["구름 미궁"] = "Cloud Maze",
	["천층탑 서른 층"] = "Tower Floor Thirty",
	["다섯 번째 권법"] = "A Fifth Style",
	["천마"] = "Heavenly Demon",
	["깨어난 화염산"] = "Fire Mountain Awakens",
	["모래 왕릉"] = "Sand Tomb",
	["하늘 문지기"] = "Sky Gatekeeper",
	["뇌정봉의 뇌제"] = "Thunder Emperor of Thunder Peak",
	["천존"] = "Heavenly Lord",
	["하늘 밖의 하늘"] = "Heaven Beyond Heaven",
	["천공 투기장"] = "Sky Arena",
	["천층탑 쉰 층"] = "Tower Floor Fifty",
	["정점"] = "The Summit",
	["환생"] = "Rebirth",
	["윤회의 공덕"] = "Merit of Rebirth",
	["천층탑 백 층"] = "Tower Floor One Hundred",
	["두 번째 삶"] = "Second Life",
	["두 번째 그림자"] = "The Second Shadow",
	["세 번째 삶"] = "Third Life",
	["세 번째 그림자"] = "The Third Shadow",
	["네 번째 삶"] = "Fourth Life",
	["마지막 그림자"] = "The Last Shadow",
	["경지의 관문"] = "Realm Gate",
	["젊은이, 맨손으로 강호에 나서겠다고? 좋다. 우선 기본부터. 삼재권은 이미 네 몸에 있다. 마을 남쪽 들판의 무뢰배들이 요즘 행패가 심하니, 그놈들부터 손봐 주게."] = "Young one, you want to enter the martial world bare-handed? Good. Start with the basics. The Three Powers Fist is already in your body. The thugs in the fields south of the village have been causing trouble lately, so deal with them first.",
	["몸부터 풀자. 마을 입구의 수련 목인을 여덟 번 쳐라. 클릭 (휴대폰은 👊)을 이어 누르면 연타가 이어진다."] = "Let's loosen up. Hit the training dummy at the village entrance eight times. Keep clicking (👊 on mobile) to chain combos.",
	["힘을 실어 한 번에. 오른쪽 클릭 (휴대폰은 💥)으로 강타를 목인에게 두 번 맞혀라. 강타는 느리지만 상대의 균형을 크게 깎는다."] = "Put your weight into one blow. Land two heavy strikes (right-click, 💥 on mobile) on the dummy. Heavy strikes are slow but wear down balance a lot.",
	["권법마다 기술이 있다. E를 눌러 삼재권의 기술을 목인에게 써 보아라. 기술은 내공을 쓰고, 쓰면 잠시 기다려야 한다."] = "Every style has skills. Press E to use a Three Powers skill on the dummy. Skills use Ki and need a moment to recharge.",
	["들판의 무뢰배 다섯을 쓰러뜨려라. 마구 휘두르지 말고, 놈들이 칠 때 F로 흘린 뒤 파고들어라."] = "Defeat five field thugs. Don't flail. Deflect with F when they strike, then move in.",
	["주먹은 몸에서 나온다. 마을 수련터에서 여덟 번 수련하라. 박자를 맞추면 두 배다."] = "A fist comes from the body. Train eight times at the village training spots. Hit the beat for double.",
	["싸움과 수련으로 능력치를 채워 이류에 올라라. 이류부터는 박자가 빠른 대신 세 배로 오르는 강화 수련이 열린다."] = "Fill your stats through fighting and training to reach Second-Rate. From Second-Rate, enhanced training opens up: faster beats, but triple gains.",
	["서쪽 대나무 숲과 동쪽 계곡에 산적 떼가 진을 쳤다. 산적 도객 여섯을 꺾어라."] = "Bandit gangs have camped in the western bamboo forest and the eastern valley. Defeat six bandit swordsmen.",
	["삼재권만으로는 멀리 못 간다. 강호에는 열 사부가 숨어 산다. 안내판의 소문을 따라 한 분을 찾아가라. 남쪽 주막의 취한 노인 이야기가 가장 가깝지."] = "The Three Powers Fist alone won't get you far. Ten masters hide across the martial world. Follow the rumors on the notice board and seek one out. The story of the drunk old man at the southern inn is the closest.",
	["사부는 아무나 받지 않는다. 사부 곁에서 T를 눌러 시험을 청하고, 사부마다 다른 시험(흘리기·버티기·제자 연무)을 넘어라."] = "A master doesn't take just anyone. Press T beside a master to request a test, and pass their test (deflecting, enduring, or sparring with disciples).",
	["시험을 넘었다면 은자를 바치고 그 권법을 배워라. 권법 창(메뉴)에서 언제든 바꿔 쓸 수 있다."] = "Once you've passed, offer silver and learn the style. You can switch styles anytime in the Styles window (menu).",
	["새 권법은 써야 손에 붙는다. 그 권법으로 적을 때려 숙련을 3까지 올려라. 숙련 3에 두 번째 기술(R)이 열린다."] = "A new style only sticks if you use it. Hit enemies with it to raise its mastery to 3. At mastery 3 its second skill (R) opens.",
	["수련과 싸움으로 능력치를 쌓아 일류에 올라라. 경지가 오를 때마다 몸이 크게 달라진다. 일류부터 철사장 수련이 열린다."] = "Build stats through training and fighting to reach First-Rate. Your body changes greatly with each realm. Iron Palm Training opens at First-Rate.",
	["한 권법만 쓰면 상대가 읽는다. 안내판의 소문을 따라 다른 사부를 찾아가 시험을 넘고, 권법을 하나 더 익혀라."] = "Use only one style and foes will read you. Follow the rumors to another master, pass the test, and learn one more style.",
	["일류를 넘어 특급에 오르면 몸이 한 번 더 달라진다. 특급부터 운기조식이 열린다. 수련과 사냥으로 능력치를 채워 특급에 올라라."] = "Pass First-Rate to Elite and your body changes once more. Ki Circulation opens at Elite. Fill your stats through training and hunting to reach Elite.",
	["먼 북쪽 산적 소굴의 두목 흑호가 마을을 노린다. 놈을 꺾어라."] = "Black Tiger, chief of the bandit den in the far north, has his eye on the village. Defeat him.",
	["한 권법의 숙련을 5까지 올려라. 숙련 5에 그 권법의 오의(G)가 열린다. 내공이 가득 찼을 때 쓰는 한 수다."] = "Raise a style's mastery to 5. At mastery 5 its Secret Art (G) opens. It's the move you use when your Ki is full.",
	["적과 보스는 가끔 심법 두루마리를 떨어뜨린다. 만물상의 📜 심법 탭에서 두루마리를 펼쳐 심법 하나를 얻고, 세 칸 중 하나에 끼워라. 심법 하나가 권법 전체를 받쳐 준다."] = "Enemies and bosses sometimes drop manual scrolls. Open a scroll in the 📜 Manuals tab of the General Store to get a manual, and fit it into one of three slots. A single manual supports your whole style.",
	["서쪽 끝 서해 절벽에 해적 떼가 배를 댔다. 특급이면 해볼 만하다. 해적 도객 여덟을 쓰러뜨려라."] = "A pirate gang has landed at the West Sea Cliffs in the far west. At Elite you can take them. Defeat eight pirate swordsmen.",
	["심법은 셋까지 끼울 수 있다. 두루마리를 펼쳐 심법을 셋 모아라. 좋은 심법이 없어도 칸을 비워 두는 것보다 낫다."] = "You can equip up to three manuals. Open scrolls to collect three. Even a weak manual beats an empty slot.",
	["한 사부의 권법만으로는 부족하다. 안내판의 소문을 따라 강호의 사부를 셋까지 찾아가 보아라. 찾아낸 사부는 지도에 나온다."] = "One master's style isn't enough. Follow the rumors on the notice board and find up to three masters. Masters you find appear on the map.",
	["마을 안 천층탑에 올라 보아라. 층마다 세기가 정해져 있고, 열 층마다 보스가 지킨다. 처음 넘는 보스 층에는 두루마리와 큰 몫이 기다린다. 열 층을 넘어라."] = "Climb the Thousand-Floor Tower in the village. Each floor has a set strength, and a boss guards every ten floors. Scrolls and big rewards wait on each boss floor the first time. Clear ten floors.",
	["남동쪽 끝 핏빛 달 아래에 혈교의 앞잡이 혈랑이 있다. 놈을 쓰러뜨려라."] = "Blood Wolf, a lackey of the Blood Cult, lurks under the blood-red moon in the far southeast. Defeat him.",
	["혈교와 맞서려면 절정의 경지가 필요하다. 경지별 수련과 사부들의 권법으로 몸을 끌어올려라."] = "You need to be at Peak to face the Blood Cult. Raise your body with realm training and your masters' styles.",
	["찾아낸 사부들 가운데 아직 배우지 않은 분이 있다면 시험을 넘고 권법을 하나 더 익혀라. 적마다 잘 듣는 권법이 다르다."] = "If there's a master you've found but haven't learned from yet, pass their test and learn another style. Different styles work on different enemies.",
	["한 권법을 오래 쓰면 숙련이 오른다. 숙련 6에 이르면 권법이 깨어나 각성기(F)가 열리고, 기술이 세진다. 지금 쓰는 권법의 숙련을 6까지 올려라."] = "Use a style long enough and its mastery rises. At mastery 6 the style awakens, opening its awakening skill (F), and its skills get stronger. Raise your current style to mastery 6.",
	["절정을 넘어 초절정에 올라라. 초절정부터 상급 수련장의 금종조 수련이 열린다."] = "Pass Peak to reach Supreme Peak. Golden Bell Training at the Advanced Training Grounds opens at Supreme Peak.",
	["북방 설산의 주인 빙마가 혈교와 손을 잡았다. 얼음을 깨고 놈을 쓰러뜨려라."] = "Ice Demon, lord of the northern snow mountains, has joined the Blood Cult. Break through the ice and defeat him.",
	["기를 불처럼 다루는 화경에 올라라. 화경부터 천근추 수련이 열리고, 두 번째 깨달음을 얻을 수 있다."] = "Reach Transformation, where ki is handled like fire. Thousand-Pound Training opens and you can gain a second insight from Transformation.",
	["숙련 10에 이른 권법은 깨달음으로 한 등급 올라선다. 권법 창에서 숙련 10인 권법을 골라 깨달아라 (은자가 든다)."] = "A style at mastery 10 can rise a grade through insight. In the Styles window, pick a mastery-10 style and gain insight (costs silver).",
	["북동쪽 끝 혈교 본산. 혈교도 열을 꺾고 길을 열어라."] = "Blood Cult Headquarters at the far northeast. Defeat ten cultists to open the way.",
	["현경에 올라라. 현경부터 주천 운기가 열린다. 혈마의 손을 마주하려면 이만한 몸이 필요하다."] = "Reach Mystic. Grand Circulation opens at Mystic. You need this kind of body to face the Blood Demon's hand.",
	["혈교의 주인 혈마. 모든 것을 걸고 맞서라. 그를 꺾으면 그 손이 네 것이 된다."] = "The Blood Demon, master of the Blood Cult. Give it everything. Defeat him and his hand is yours.",
	["한 권법을 두 번 깨달으면 피해가 크게 오르고, 각성의 문이 열린다. 숙련 10인 권법을 골라 두 번째 깨달음을 얻어라."] = "Two insights in one style raise its damage a lot and open the gate to awakening. Pick a mastery-10 style and gain its second insight.",
	["죽음의 문턱, 사경에 올라라. 사경부터 마음속 마귀와 겨루는 심마 대련과 허공답보가 열린다. 심마를 꺾으면 능력치가 크게 오른다."] = "Reach Brink, the threshold of death. Inner Demon Duel and Sky Walk open at Brink. Beat your inner demon for a big stat boost.",
	["혈마를 꺾은 손이라면 생사경이 멀지 않다. 들판의 적은 내 수준의 땅에서 잡을 때 가장 알차다. 지도의 권장 전투력을 보고 땅을 골라 생사경에 올라라."] = "If your hand beat the Blood Demon, Life & Death isn't far. Field enemies are most rewarding in lands at your level. Check the recommended power on the map, pick a land, and reach Life & Death.",
	["생사경 다음은 신화경이다. 여기까지 온 사람은 손에 꼽는다. 신화경에 올라라."] = "After Life & Death comes Mythic. Only a handful ever get this far. Reach Mythic.",
	["생사경에 오른 고수는 익힌 권법의 숨은 끝을 본다. 원래 권법의 숙련을 끝까지 올리고 깨달음을 두 번 얻은 뒤, 그 사부를 다시 찾아 각성의 시련을 넘어라. 각성 권법(진) 하나를 익혀라."] = "A master at Life & Death sees the hidden end of their styles. Max out an original style's mastery and gain two insights, then return to its master and pass the Awakening Trial. Learn one awakened (True) style.",
	["하늘과 사람이 하나가 되는 경지, 천인합일에 올라라. 그때 마을의 천상 문이 열린다."] = "Reach Heaven-Human Unity, where heaven and man become one. Then the village's Heaven Gate opens.",
	["마을 안 천상 문으로 하늘에 올라라. 구름 위 천궁은 안전하고, 천상 객잔과 천정 상점이 있다. 지도는 하늘에 오르면 저절로 천상 지도로 바뀐다."] = "Ascend through the Heaven Gate in the village. The Sky Palace above the clouds is safe and has a heavenly inn and a sky gem shop. Your map switches to the heavenly map automatically when you go up.",
	["하늘의 적은 땅의 적보다 몫이 크고, 천정과 천상 재료를 떨어뜨린다. 천궁 남쪽 운해 평원의 운병 여덟을 쓰러뜨려라."] = "Heavenly enemies give more than earthly ones and drop sky gems and heavenly materials. Defeat eight cloud soldiers on the Cloud Plain south of the Sky Palace.",
	["혈마도 쓰러졌다. 그런데 북서쪽 끝 허공 균열에서 이상한 기운이 새어 나온다. 무극의 경지에 올라라. 권법을 깨달음으로 승급시키는 것도 잊지 마라."] = "The Blood Demon has fallen too. But a strange energy is leaking from the Void Rift in the far northwest. Reach Limitless. Don't forget to upgrade your styles through insight.",
	["무극에 오른 자는 들을 수 있다는 소문. 남서쪽 세상 끝, 구름이 땅에 닿는 곳에 이름 없는 노인이 있다. 그에게서 하늘을 여는 주먹을 얻어라."] = "A rumor only those at Limitless can hear: a nameless old man sits at the southwest end of the world, where the clouds touch the ground. Get the sky-opening fist from him.",
	["천궁 광장의 구름 미궁 문으로 들어가 방들을 넘고 미궁의 주인을 꺾어라. 들어간 사람의 세기에 맞춰 적이 선다."] = "Enter the Cloud Maze gate in the Sky Palace plaza, clear the rooms and defeat the maze's master. Enemies scale to the strength of whoever enters.",
	["마을의 천층탑 서른 층에 올라라. 보스 층마다 두루마리가 기다린다."] = "Climb to floor thirty of the village's Thousand-Floor Tower. Scrolls await on every boss floor.",
	["허공 균열의 천마 사도 여섯을 꺾고 길을 열어라."] = "Defeat six Heavenly Demon apostles in the Void Rift to open the way.",
	["적마다 잘 듣는 권법이 다르다. 사부를 하나 더 찾아 다섯 번째 권법을 익혀라."] = "Different styles work on different enemies. Find one more master and learn a fifth style.",
	["마교의 교주, 천마. 혈교의 뒤에서 강호를 움직이던 자다. 그를 꺾어야 땅의 싸움이 끝난다."] = "The Heavenly Demon, leader of the Demon Cult. He was moving the martial world from behind the Blood Cult. Defeat him to end the war on earth.",
	["천마가 쓰러지자 동쪽 끝 화염산이 깨어났다. 불의 산 아래 염제를 꺾어라."] = "With the Heavenly Demon fallen, the Fire Mountain in the far east has awakened. Defeat the Flame Emperor beneath it.",
	["남쪽 끝 모래 왕릉에서 사왕이 무덤을 박차고 일어났다. 왕릉으로 가 사왕을 다시 눕혀라."] = "The Snake King has burst from his grave in the sand tomb at the far south. Go to the tomb and put him back to rest.",
	["북쪽 끝 구름바다 위, 천외봉으로 가는 길을 천문장이 막고 있다."] = "The Heaven Gate General blocks the road to the Beyond Peak above the northern cloud sea.",
	["천궁 동쪽 다리 너머 뇌정봉에 벼락을 부리는 뇌제가 있다. 천상의 보스는 천상 재료를 떨어뜨린다. 뇌제를 꺾어라."] = "The Thunder Emperor wields lightning on Thunder Peak beyond the bridge east of the Sky Palace. Heavenly bosses drop heavenly materials. Defeat the Thunder Emperor.",
	["천궁 북쪽 옥좌대에 하늘의 옥좌를 지키는 천존이 있다. 천상의 주인을 꺾어라."] = "The Heavenly Lord guards the throne of heaven at the Throne Terrace north of the Sky Palace. Defeat the master of the heavens.",
	["사람과 신선의 사이, 반선에 올라라."] = "Reach Half-Immortal, between man and immortal.",
	["구름을 밟고 오르는 등선의 경지에 올라라. 천외천이 멀지 않다."] = "Reach Ascension, climbing on the clouds. Beyond Heaven isn't far.",
	["경지의 끝, 천외천에 올라라. 하늘 밖에 하늘이 있다."] = "Reach the end of the realms, Beyond Heaven. There is a sky beyond the sky.",
	["천궁 광장의 투기장 문 너머, 하늘의 재앙 천겁이 기다린다. 여럿이 함께 들어가 천겁을 쓰러뜨려라."] = "Beyond the arena gate in the Sky Palace plaza waits Cheongeop, the calamity of the heavens. Go in together and bring it down.",
	["천층탑 쉰 층에 올라라. 위로 갈수록 몫이 가파르게 붙는다."] = "Climb to floor fifty of the Thousand-Floor Tower. Rewards climb steeply the higher you go.",
	["천외봉 아래 시원자를 찾아 시험을 넘고 태초신권을 얻어라. 세상이 처음 열리던 그 한 주먹이다."] = "Find the Origin Sage beneath the Beyond Peak, pass the test, and gain the Genesis Divine Fist. The single fist from the moment the world first opened.",
	["태초의 주먹마저 쥐었다면 들어라. 동남쪽 세상 끝 일월대에 해와 달을 두 손에 쥔 권존이 있다. 그를 넘어 일월신권을 얻어라. 그것이 권법의 정점이다."] = "If you hold even the Genesis Fist, listen. At the Sun-Moon Altar at the southeast end of the world is the Fist Sovereign, sun and moon in hand. Surpass him and gain the Sun-Moon Divine Fist. That is the summit of all styles.",
	["천외천이 끝이 아니다. 환생하면 경지는 처음부터지만 몸은 더 세지고 (얻는 능력치 두 배), 천외천 너머의 경지가 하나씩 열린다. 메뉴에서 환생하라."] = "Beyond Heaven is not the end. If you're reborn, your realm starts over but your body grows stronger (double stat gains), and realms beyond Beyond Heaven open one by one. Rebirth from the menu.",
	["환생할 때마다 공덕 둘이 쌓인다. 능력치 창의 '♻ 환생 특전'에서 공덕으로 특전(체력·피해·흡성·심공·재물운·오성·질풍)을 하나 사라. 특전은 환생해도 남고, 언제든 되돌려 다시 고를 수 있다."] = "Each rebirth earns two merits. In the stats window, under '♻ Rebirth Perks', spend merits on a perk (HP, damage, Absorption, Inner Heart, Fortune, Insight, Gale). Perks stay through rebirths, and you can refund and pick again anytime.",
	["삼류에서 다시 오르다 생사경에 닿으면, 지난 삶의 네가 그림자로 나타난다. 능력치 창의 '☯ 윤회의 시련'으로 그림자를 불러 꺾어라. 넘을 때마다 공덕 하나와 천정·두루마리가 따르고, 그림자가 환생 권법 하나를 남긴다 (윤회권 · 업화권 · 무상권 · 권왕신권)."] = "Climbing again from Third-Rate, when you reach Life & Death your past self appears as a shadow. Summon and defeat it with '☯ Rebirth Trial' in the stats window. Each one you pass gives a merit, sky gems and scrolls, and the shadow leaves behind a rebirth style (Rebirth Fist · Karmic Fire Fist · Impermanence Fist · Fist King Fist).",
	["원래 권법과 그 각성 권법을 숙련 20까지 올리고 천상에서만 나는 재료를 모으면, 숨은 초월의 사부가 시련을 내준다. 초월 권법(초) 하나를 익혀라. 초 오의(X)는 하늘이 뒤집히는 한 수다."] = "Raise an original style and its awakened style to mastery 20 and gather materials found only in the heavens, and a hidden master of transcendence will grant a trial. Learn one Transcendent (Ultimate) style. The Ultimate Art (X) is a move that turns the sky upside down.",
	["천층탑 백 층에 올라라. 위로 갈수록 은자와 능력치가 가파르게 붙는다."] = "Climb to floor one hundred of the Thousand-Floor Tower. Silver and stats climb steeply the higher you go.",
	["환생한 몸으로 다시 올라 천외천을 넘어라. 혼원경이 열려 있다."] = "Climb again in your reborn body and pass Beyond Heaven. Primordial is open.",
	["다시 천외천 너머 혼원경에 올라 두 번째로 환생하라. 환생할수록 얻는 능력치가 커져, 다시 오르는 길은 처음보다 훨씬 빠르다."] = "Climb past Beyond Heaven to Primordial again and be reborn a second time. Each rebirth increases stat gains, so the climb gets much faster than the first time.",
	["두 번째 삶의 생사경에서 두 번째 그림자가 기다린다. 첫 그림자보다 질기다. 공덕으로 고른 특전을 믿어라."] = "The second shadow waits at Life & Death in your second life. It's tougher than the first. Trust the perks you chose with your merits.",
	["끝이 없는 경지, 무량경에 올라라."] = "Reach Boundless, the realm without end.",
	["무량경에 올라 세 번째로 환생하라. 특전을 다시 고를 때다. 싸움에 쓸 것인가, 오르는 빠르기에 쓸 것인가."] = "Reach Boundless and be reborn a third time. Time to choose perks again: for fighting, or for climbing faster?",
	["세 번째 그림자는 네 버릇을 안다. 늘 쓰던 기술만 쓰면 막힌다."] = "The third shadow knows your habits. Use only your usual skills and you'll be blocked.",
	["텅 빈 하늘의 경지, 태허경에 올라라. 네 번째 환생이 기다린다."] = "Reach Great Void, the realm of the empty sky. Your fourth rebirth awaits.",
	["태허경에 올라 네 번째로 환생하라. 권왕의 자리가 가깝다. 그러나 환생은 아직 둘이 더 남았다."] = "Reach Great Void and be reborn a fourth time. The Fist King's seat is near. But two rebirths still remain.",
	["윤회의 바퀴가 마지막 그림자를 내보낸다. 네 삶을 모두 넘어선 너만이 권왕의 자리에 앉는다."] = "The wheel of rebirth sends out the last shadow. Only you, having passed all four lives, can take the Fist King's seat.",
	["네 삶을 넘었다. 권왕에 올라라. 맨손의 강호에 왕은 하나다. 그러나 왕의 자리 위에도 길은 이어진다."] = "You've passed four lives. Become the Fist King. In the bare-handed martial world there is only one king. But the road continues even beyond the throne.",
	["이제 강호에 네 이름을 모르는 자가 없다. 남은 권법과 숨은 사부, 완전 각성과 승급. 그리고 너는 이제 권왕이다. 길은 끝이 없다."] = "Now there's no one in the martial world who doesn't know your name. Styles left to learn, hidden masters, full awakening and upgrades. And you are now the Fist King. The road never ends.",
	["거신상"] = "Colossus",
	["하늘 고리"] = "Sky Ring",
	["옛 투기장"] = "Old Arena",
	["수정 들판"] = "Crystal Fields",
	["천년 고목"] = "Thousand-Year Tree",
	["핏빛 달"] = "Blood Moon",
	["만검총"] = "Graveyard of Swords",
	["끊어진 하늘다리"] = "Broken Sky Bridge",
	["용의 무덤"] = "Dragon's Grave",
	["불의 산"] = "Mountain of Fire",
	["사왕의 무덤"] = "Snake King's Grave",
	["천년 종루"] = "Thousand-Year Bell Tower",
	["거울 호수"] = "Mirror Lake",
	["거신의 손"] = "Colossus's Hand",
	["별똥 분화구"] = "Meteor Crater",
	["만목원"] = "Myriad Tree Grove",
	["잠든 석장"] = "Sleeping Stone Staff",
	["별바위 고리"] = "Star Rock Ring",
	["옛 봉화대"] = "Old Beacon Tower",
	["버려진 마을"] = "Abandoned Village",
	["하늘 아치"] = "Sky Arch",
	["구층석탑"] = "Nine-Story Stone Pagoda",
	["연화정"] = "Lotus Pavilion",
	["일검 바위"] = "One Sword Rock",
	["천등 회랑"] = "Thousand Lantern Corridor",
	["무너진 장성"] = "Ruined Great Wall",
	["학 연못"] = "Crane Pond",
	["귀부 비석"] = "Turtle Stele",
	["버려진 광산"] = "Abandoned Mine",
	["선인송"] = "Immortal Pine",
	["해시계 광장"] = "Sundial Plaza",
	["흘리기 시험"] = "Deflect Test",
	["나를 쓰러뜨릴 필요는 없다. 흘려라. 내 주먹이 닿기 직전, 머리 위에 F가 번쩍일 때 F를 눌러라. %d번 흘려 내면 제자로 받아 주마."] = "You don't need to knock me down. Deflect. Press F when it flashes over your head, right before my fist lands. Deflect %d times and I'll take you as a disciple.",
	["F가 번쩍이면 F! 사부의 공격을 흘려라"] = "When F flashes, press F! Deflect the master's attacks",
	["버티기 시험"] = "Endurance Test",
	["%d초를 버텨라. 나와 내 제자들이 한꺼번에 덤빈다. 쓰러지지만 않으면 된다."] = "Hold out for %d seconds. My disciples and I will come at you all at once. Just don't fall.",
	["쓰러지지 말고 버텨라"] = "Don't fall. Hold out",
	["제자 연무"] = "Disciple Sparring",
	["내 제자들을 넘어 보아라. %d번 몰려온다. 마지막은 수제자다."] = "Get past my disciples. They'll come %d times. The last is my top disciple.",
	["몰려오는 제자들을 꺾어라"] = "Defeat the waves of disciples",
	["청운 마을 객잔"] = "Cheongun Village Inn",
	["단풍산 길목 주막"] = "Maple Mountain Pass Tavern",
	["차밭 언덕 주막"] = "Tea Hill Tavern",
	["버섯 숲 어귀 주막"] = "Mushroom Forest Entrance Tavern",
	["석림 길가 주막"] = "Stone Forest Roadside Tavern",
	["운해 길목 주막"] = "Cloud Sea Pass Tavern",
	["모래 왕릉 가는 길 주막"] = "Tavern on the Road to the Sand Tomb",
	["불 제단 아래 주막"] = "Tavern below the Fire Altar",
	["균열 고개 주막"] = "Rift Pass Tavern",
	["바람 언덕 주막"] = "Wind Hill Tavern",
	["산채 아랫마을 주막"] = "Village below the Bandit Fort Tavern",
	["금창약"] = "Wound Salve",
	["체력 40% 회복 (H키, 최대 5개)"] = "Restores 40% HP (H key, up to 5)",
	["소환단"] = "Summoning Pill",
	["5분 동안 수련 효과 2배"] = "Training effect x2 for 5 minutes",
	["대환단"] = "Great Restoration Pill",
	["모든 능력치가 오른다 (영구, 경지에 맞춰 커진다)"] = "Raises all stats (permanent, scales with realm)",
	["철골공"] = "Iron Bone Art",
	["파괴심법"] = "Destruction Manual",
	["금강호체공"] = "Diamond Guard Art",
	["받는 피해 감소"] = "Less damage taken",
	["질풍심법"] = "Gale Manual",
	["이동 속도"] = "Move speed",
	["운기심법"] = "Ki Flow Manual",
	["내공 회복"] = "Ki regen",
	["집중심법"] = "Focus Manual",
	["기술 대기 감소"] = "Shorter skill cooldowns",
	["오의심법"] = "Secret Art Manual",
	["오의 피해"] = "Secret Art damage",
	["일반"] = "Common",
	["희귀"] = "Rare",
	["영웅"] = "Heroic",
	["천상"] = "Heavenly",
	["배틀그라운드"] = "Battleground",
	["죽림 비무장"] = "Bamboo Dueling Ground",
	["대숲에 둘러싸인 돌 마당. 대나무 덤불 뒤에 숨어 파고든다"] = "A stone yard surrounded by bamboo. Hide behind the thickets and close in",
	["빙호 설원"] = "Frozen Lake Snowfield",
	["얼어붙은 호수와 얼음 기둥. 가운데는 탁 트였고 가장자리는 눈 언덕"] = "A frozen lake with ice pillars. Open in the middle, snowy hills at the edges",
	["화산 분지"] = "Volcanic Basin",
	["용암이 흐르는 분화구 안의 두 층 단. 높은 곳을 잡아라"] = "Two-tier terraces inside a lava-filled crater. Take the high ground",
	["운상 누각"] = "Cloud Pavilions",
	["구름 위에 뜬 누각 셋과 다리. 떨어지면 쓰러진다"] = "Three pavilions and bridges floating above the clouds. Fall and you're out",
	["갈색 말"] = "Brown Horse",
	["누구나 처음부터 가진 말"] = "The horse everyone starts with",
	["흑룡마"] = "Black Dragon Steed",
	["붉은 갈기의 검은 준마"] = "A black charger with a red mane",
	["백호"] = "White Tiger",
	["흰 범. 땅을 박차고 달린다"] = "A white tiger that bounds across the ground",
	["청룡"] = "Azure Dragon",
	["💎 로벅스 상품. 하늘을 헤엄치는 비늘 용. 가장 빠르다"] = "💎 Robux item. A scaled dragon that swims through the sky. The fastest",
	["날개구름"] = "Winged Cloud",
	["구름을 타고 미끄러진다. 청룡 다음으로 빠르다"] = "Glide on a cloud. Fastest after the Azure Dragon",
	["흑룡"] = "Black Dragon",
	["💎 로벅스 상품. 검은 비늘에 붉은 불길이 타오르는 용 (청룡 다음으로 빠르다)"] = "💎 Robux item. A black-scaled dragon wreathed in red flame (fastest after the Azure Dragon)",
	["혈염마"] = "Blood Flame Steed",
	["칠흑의 몸에 불타는 갈기. 발굽마다 핏빛 불꽃이 인다 (전투 신화 업적: 천하무적 · 보스의 악몽)"] = "Pitch-black with a burning mane. Blood-red flames rise from every hoof (combat mythic achievements: Invincible · Bane of Bosses)",
	["천상 백호"] = "Heavenly White Tiger",
	["푸른 빛 줄무늬의 흰 범. 별빛 서리가 흩날린다 (권법·강호 신화 업적: 천하의 모든 권 · 시그니처의 주인 · 천상 심법)"] = "A white tiger with glowing blue stripes, scattering starlit frost (style and world mythic achievements: Every Fist Under Heaven · Master of Signatures · Heavenly Manuals)",
	["무지개 구름"] = "Rainbow Cloud",
	["일곱 빛깔이 도는 구름. 지나간 자리에 무지개가 남는다 (도전·비무 신화 업적: 재앙의 끝 · 구름의 왕 · 탑의 주인 · 강호 제일권)"] = "A cloud swirling with seven colors that leaves a rainbow behind (challenge and dueling mythic achievements: End of Calamity · King of Clouds · Master of the Tower · First Fist of the World)",
	["세상의 끝자락"] = "Edge of the World",
	["천존이 무릎을 꿇자 땅의 끝자락이 술렁인다. 동쪽 황사 협곡의 주인 황사와, 꺼지지 않는 불길의 평원을 다스리는 동극군이 세를 넓히고 있다. 둘을 꺾어라."] = "With the Heavenly Lord on his knees, the edges of the land stir. Hwangsa, lord of the Yellow Dust Canyon in the east, and the Eastern Ember Lord, who rules the plains of undying flame, are expanding their reach. Defeat both.",
	["북명과 서역"] = "North and West",
	["세상의 북쪽 끝은 얼어붙었고, 서쪽 끝은 모래에 묻혔다. 북명 빙원의 북명제와 서역 사구의 서역사왕을 꺾어 땅의 네 끝을 모두 밟아라."] = "The northern end of the world is frozen and the western end is buried in sand. Defeat the North Emperor of the Northern Ice Plains and the Western Snake King of the Western Dunes, and set foot on all four ends of the land.",
	["하늘의 섬들"] = "Islands in the Sky",
	["천궁 너머 구름 사이에 섬마다 주인이 있다. 빙정궁의 빙제, 비천폭의 비천, 극광대의 극광. 하늘의 재료는 그들이 지키는 곳에서 난다."] = "Beyond the Sky Palace, every island among the clouds has a master. The Ice Emperor of the Frost Crystal Palace, Bicheon of the Flying Falls, Aurora of the Aurora Terrace. Heavenly materials come from the places they guard.",
	["구름 위의 숲"] = "Forest Above the Clouds",
	["더 높은 섬에는 오래된 것들이 산다. 청학봉의 선학, 운무 죽림의 죽왕, 봉황대의 염봉을 넘어라."] = "Old things live on the higher islands. Get past the Crane Sage of Blue Crane Peak, the Bamboo King of the Misty Bamboo Grove, and the Flame Phoenix of the Phoenix Terrace.",
	["선계의 문"] = "Gate of the Immortal Realm",
	["천외천에 오른 몸이면 선계가 문을 연다. 월광 호수의 월영, 선계 정원의 도선, 금운사의 금강천왕. 하늘의 마지막 수문장들이다."] = "At Beyond Heaven, the immortal realm opens its gate. Wolyeong of Moonlight Lake, Doseon of the Immortal Garden, and the Diamond Heaven King of Golden Cloud Temple. The last gatekeepers of the sky.",
	["용의 등성이"] = "Dragon's Ridge",
	["환생한 몸에는 하늘의 더 먼 곳이 보인다. 용척령의 비룡, 유리해의 유리 군주, 하늘 감옥의 천뢰를 꺾어라."] = "A reborn body can see farther into the sky. Defeat the Flying Dragon of Dragon Spine Ridge, the Glass Lord of the Glass Sea, and Cheonroe of the Sky Prison.",
	["구름 위의 용"] = "Dragon Above the Clouds",
	["운룡대 꼭대기, 구름을 몸으로 감은 운룡왕이 하늘의 길목을 막고 있다."] = "At the top of the Cloud Dragon Terrace, the Cloud Dragon King, wrapped in clouds, blocks the way through the sky.",
	["하늘 문 너머"] = "Beyond the Sky Gate",
	["하늘의 끝에는 문이 있다. 신선호의 신선왕과 비상문의 비상왕을 넘으면 하늘에서 더 오를 곳은 없다."] = "At the end of the sky there is a gate. Pass the Immortal King of Immortal Lake and the Soaring King of the Soaring Gate, and there's nowhere higher to climb in the sky.",
	["황천 나루"] = "Hwangcheon Ferry",
	["하늘의 끝을 본 자는 땅의 아래를 본다. 세상 동남쪽 맨 끝, 희미한 풀이 밟히는 곳에서 사신에게 삯을 치르고 원혼을 달래면 지옥이 열린다. 삼도천의 탈의파와 화탕지옥의 화탕대왕을 꺾어라."] = "Those who have seen the end of the sky see beneath the earth. At the far southeast end of the world, where faint grass gives underfoot, pay the reaper his fare and calm the restless spirits, and hell opens. Defeat Taluipa of the Three Crossings River and the Boiling Cauldron King of the Cauldron Hell.",
	["왕의 자리는 지옥에서도 시험받는다. 도산지옥의 도산군주와 아귀도의 아귀왕을 꺾어라."] = "A king's seat is tested even in hell. Defeat the Blade Mountain Lord of the Blade Mountain Hell and the Hungry Ghost King of the Hungry Ghost Realm.",
	["다섯 번째 삶"] = "Fifth Life",
	["권왕에 오른 몸으로 다시 환생하라. 다섯 번째 삶에는 권왕 위의 경지, 대라경이 열린다."] = "Be reborn again as Fist King. In your fifth life, the realm above Fist King, Grand Luo, opens.",
	["크게 그물을 펼친 하늘, 대라경에 올라라."] = "Reach Grand Luo, the sky that casts a great net.",
	["업경대 앞에서"] = "Before the Karma Mirror",
	["지옥의 한가운데 염라전. 업경대에 비친 네 지난 삶을 마주하고 염라대왕을 꺾어라."] = "Yama's Hall at the heart of hell. Face your past lives reflected in the Karma Mirror and defeat King Yama.",
	["극에 닿다"] = "Reaching the Apex",
	["권법에도 끝이 있다. 해와 달 사이의 극 일월신권, 비어 있는 좌표의 극 공백권, 빛보다 먼저 닿는 극 광속권. 숨은 사부를 찾아 극 권법 하나를 익혀라."] = "Even styles have an end. Apex Sun-Moon Fist between sun and moon, Apex Null Fist of the empty coordinates, Apex Lightspeed Fist that lands before light. Find a hidden master and learn one Apex style.",
	["여섯 번째 삶"] = "Sixth Life",
	["마지막 환생이다. 여섯 번째 삶에 허무경이 열린다."] = "The last rebirth. In your sixth life, Nothingness opens.",
	["모든 것이 비어 다시 차는 경지, 허무경에 올라라. 경지의 끝이다."] = "Reach Nothingness, where everything empties and fills again. It's the last realm.",
	["지옥의 깊은 곳"] = "Depths of Hell",
	["지옥은 아래로 갈수록 깊다. 독사지옥의 독사대왕, 발설지옥의 발설대왕, 끝없이 떨어지는 무간의 군주를 꺾어라."] = "Hell goes deeper the lower you go. Defeat the Viper King of the Viper Hell, the Tongue King of the Tongue-Pulling Hell, and the lord of endlessly falling Avici.",
	["세 개의 극"] = "Three Apexes",
	["극 권법 셋을 모두 익혀라. 셋이 하나로 모일 때 그 너머가 열린다."] = "Learn all three Apex styles. When the three come together, what lies beyond opens.",
	["신의 동굴"] = "Cave of the Divine",
	["세상 북서쪽 맨 끝, 지옥 입구의 정반대 자리에 사람 모양의 돌이 서 있다. 다섯 번 환생한 몸으로 은자 999만을 바치면 땅 밑 동굴이 열린다. 세 대좌에 극 권법의 기운을 차례로 보내 신 삼재권을 얻어라."] = "At the far northwest of the world, directly opposite the entrance to hell, stands a man-shaped stone. With five rebirths, offer 999 ten-thousand silver and a cave opens below. Send the energy of the Apex styles to the three pedestals in turn to gain the Divine Three Powers Fist.",
	["지옥의 끝"] = "Bottom of Hell",
	["지옥의 가장 아래, 피의 못, 얼음 감옥, 쇠사슬 골짜기. 혈지대왕 · 한빙대왕 · 철환대왕을 꺾으면 지옥의 큰 싸움은 끝난다."] = "The bottom of hell: the pool of blood, the ice prison, the valley of chains. Defeat the Blood Pool King, the Frost King and the Iron Ball King, and the great war of hell is over.",
	["하늘의 끝과 지옥의 바닥을 모두 밟았다. 이제 강호에 네 이름을 모르는 자가 없다. 남은 권법과 숨은 사부, 천층탑의 꼭대기. 맨손의 길은 끝나지 않는다."] = "You've walked both the end of the sky and the floor of hell. Now there's no one in the martial world who doesn't know your name. Styles left to learn, hidden masters, the top of the Thousand-Floor Tower. The bare-handed road never ends.",
	["청운 장로"] = "Elder Cheongun",
	["강호에 온 것을 환영하네. 맨손 하나로 이름을 떨치겠다는 젊은이가 또 왔구먼."] = "Welcome to the martial world. So another young one has come to make a name with nothing but bare hands.",
	["먼저 내게 와서 말을 걸게. 노란 길잡이를 따라오면 되네."] = "Come talk to me first. Just follow the yellow guide.",
	["몸이 경지에 닿았다고 경지에 오르는 것은 아니다."] = "Your body reaching a realm doesn't mean you've risen to it.",
	["나를 넘어라. 그래야 다음 경지다."] = "Get past me. Then comes the next realm.",
	["천층탑. 한 층 오를 때마다 적이 강해진다."] = "The Thousand-Floor Tower. Enemies get stronger with every floor.",
	["쓰러지거나 떨어지면 처음부터다. 열 층마다 주인이 기다린다."] = "Fall down or fall off and you start over. A master waits every ten floors.",
	["강호"] = "Martial World",
	["배틀그라운드에서 백 명을 쓰러뜨렸다. 강호에 네 이름이 돌기 시작했다."] = "You've defeated a hundred in the Battleground. Your name has started to spread across the martial world.",
	["무쌍신권. 사람을 꺾기 위해 다듬어진 주먹이 네 것이다."] = "Peerless Divine Fist. A fist honed to beat people is yours.",
	["흑호"] = "Black Tiger",
	["내 산채에 발을 들인 놈은 살아서 나간 적이 없다."] = "No one who's set foot in my fort has ever left alive.",
	["혈랑"] = "Blood Wolf",
	["피 냄새를 맡고 왔나. 잘못 찾아왔다."] = "Followed the smell of blood here? You came to the wrong place.",
	["빙마"] = "Ice Demon",
	["이 설산은 내 집이다. 길을 잃었다면 지금 돌아가라."] = "This snow mountain is my home. If you're lost, turn back now.",
	["혈교 본산까지 걸어 들어온 놈은 오랜만이군."] = "It's been a while since anyone walked all the way into the Blood Cult's headquarters.",
	["혈교를 부린 것도 나다. 맨손으로 여기까지 온 건 칭찬해 주지."] = "I'm the one who ran the Blood Cult. Coming this far bare-handed deserves some praise.",
	["염제"] = "Flame Emperor",
	["불의 산은 들어온 자를 돌려보내지 않는다."] = "The mountain of fire never lets those who enter leave.",
	["사왕"] = "Snake King",
	["천 년을 잤다. 깨운 값은 받아야겠다."] = "I slept a thousand years. Someone has to pay for waking me.",
	["천문장"] = "Heaven Gate General",
	["하늘의 문은 아무에게나 열리지 않는다."] = "The gate of heaven doesn't open for just anyone.",
	["천궁 수문장"] = "Sky Palace Gatekeeper",
	["여기는 천상계. 땅에서 쌓은 이름은 이곳에 닿지 않는다."] = "This is the Heavenly Realm. Names earned on the ground don't reach here.",
	["천존은 옥좌에서 내려온 적이 없다. 가 보면 알 것이다."] = "The Heavenly Lord has never left his throne. Go and see for yourself.",
	["뇌제"] = "Thunder Emperor",
	["하늘의 벼락은 두 번 묻지 않는다."] = "Heaven's lightning doesn't ask twice.",
	["성군"] = "Star Lord",
	["별을 헤아리는 데 방해가 되는군. 빨리 끝내자."] = "You're interrupting my star counting. Let's end this quickly.",
	["땅에서 올라온 주먹이 어디까지 닿는지 보자."] = "Let's see how far a fist from the ground can reach.",
	["빙제"] = "Ice Emperor",
	["이 궁에 들어온 자는 다들 발부터 얼었다. 너도 곧 그렇게 된다."] = "Everyone who entered this palace froze from the feet up. You'll be the same soon.",
	["염봉"] = "Flame Phoenix",
	["봉황은 죽지 않는다. 타고 남은 재에서 다시 날 뿐."] = "A phoenix doesn't die. It just rises again from its ashes.",
	["풍엽"] = "Pungyeop",
	["잎이 다 지기 전에 돌아가라. 그게 마지막 충고다."] = "Turn back before all the leaves fall. That's my last warning.",
	["석왕"] = "Stone King",
	["천 년을 서 있었다. 너 하나에 무너질 돌이 아니다."] = "I've stood for a thousand years. I'm not a stone that crumbles to the likes of you.",
	["균왕"] = "Spore King",
	["이 숲에서는 숨을 아껴 쉬어라. 포자가 폐에 박힌다."] = "Breathe sparingly in this forest. The spores lodge in your lungs.",
	["다선"] = "Tea Immortal",
	["찻잎이 가라앉기 전에 끝내 주마."] = "I'll finish this before the tea leaves settle.",
	["비천"] = "Bicheon",
	["하늘에서 떨어지는 물은 바위도 뚫는다."] = "Water falling from the sky pierces even rock.",
	["선학"] = "Crane Sage",
	["학은 한 번 날개를 펴면 구름 위로만 난다."] = "Once a crane spreads its wings, it flies only above the clouds.",
	["죽왕"] = "Bamboo King",
	["대나무는 꺾이지 않는다. 휘었다가 너를 친다."] = "Bamboo doesn't break. It bends, then strikes you.",
	["월영"] = "Wolyeong",
	["호수에 비친 달을 베어 본 적이 있느냐."] = "Have you ever cut the moon reflected in a lake?",
	["금강천왕"] = "Diamond Heaven King",
	["이 절의 문을 지킨 지 오래다. 주먹이 버틸지 보자."] = "I've guarded this temple's gate a long time. Let's see if your fists hold up.",
	["탈의파"] = "Taluipa",
	["삼도천을 건너려면 이승의 것을 모두 내려놓아라. 네 죄의 무게는 이 나무가 잰다."] = "To cross the Three Crossings River, lay down everything of this world. This tree weighs your sins.",
	["화탕대왕"] = "Boiling Cauldron King",
	["이 솥은 한 번도 식은 적이 없다. 이번엔 네 차례다."] = "This cauldron has never once cooled. Your turn now.",
	["도산군주"] = "Blade Mountain Lord",
	["이 산의 칼날은 모두 죄인의 것이었다. 네 것도 하나 더하마."] = "Every blade on this mountain belonged to a sinner. I'll add yours.",
	["아귀왕"] = "Hungry Ghost King",
	["배가 고프다. 얼마나 먹어도 늘 고프다. 너는 좀 오래 씹어야겠군."] = "I'm hungry. No matter how much I eat, I'm always hungry. You'll take some chewing.",
	["염라대왕"] = "King Yama",
	["산 사람이 여기까지 온 건 오랜만이다. 업경대가 너를 어떻게 비추는지 보자."] = "It's been a while since a living person came this far. Let's see how the Karma Mirror shows you.",
	["천겁"] = "Cheongeop",
	["천겁이다. 혼자서는 버티기 어렵다. 동료를 모아서 와라."] = "I am Cheongeop. Hard to survive alone. Bring your companions.",
	["두 배 수련"] = "Double Training",
	["영구"] = "Permanent",
	["모든 수련의 능력치가 영원히 두 배"] = "All training stat gains doubled forever",
	["소환단·강화 수련·자동 수련과 겹친다"] = "Stacks with Summoning Pills, enhanced training and auto training",
	["심마 대련 보상도 두 배"] = "Inner Demon Duel rewards doubled too",
	["자동 수련"] = "Auto Training",
	["수련 화면에서 박자마다 대신 눌러 준다 ('좋음')"] = "Presses for you on every beat in the training screen ('Good')",
	["수련 자리를 떠나면 멈춘다 (어디서나 오르지 않는다)"] = "Stops when you leave the training spot (doesn't level you anywhere)",
	["손은 편해지지만 사람보다 빠르지 않다"] = "Easier on your hands, but no faster than a person",
	["고급 자동 수련"] = "Advanced Auto Training",
	["수련 화면에서 박자마다 '완벽'으로 대신 눌러 준다"] = "Presses 'Perfect' for you on every beat in the training screen",
	["강화 수련에서도 쓸 수 있다"] = "Works in enhanced training too",
	["수련 자리를 떠나면 멈춘다"] = "Stops when you leave the training spot",
	["은자 두 배"] = "Double Silver",
	["적·보스·천층탑에서 얻는 은자가 영원히 두 배"] = "Silver from enemies, bosses and the Tower doubled forever",
	["업적·도감 보상처럼 한 번 받는 것은 그대로"] = "One-time rewards like achievements and the codex stay the same",
	["은자가 필요한 곳 (권법·심법·탈것)을 훨씬 빨리 채운다"] = "Fill what needs silver (styles, manuals, mounts) much faster",
	["가방 확장"] = "Bag Expansion",
	["금창약을 5개 → 10개까지 들 수 있다"] = "Carry Wound Salves: 5 → 10",
	["마을 상점에서 한 번에 채우기가 편해진다"] = "Easier to restock all at once at the village shop",
	["큰 싸움 (보스·레이드) 에서 버틸 수 있는 횟수가 두 배"] = "Twice as many heals in big fights (bosses, raids)",
	["청룡 탈것"] = "Azure Dragon Mount",
	["탈것"] = "Mount",
	["비늘이 빛나는 청룡을 타고 하늘을 헤엄치듯 달린다"] = "Ride a shining-scaled Azure Dragon, swimming through the sky as you run",
	["모든 탈것 중 가장 빠르다 (×3.1)"] = "The fastest of all mounts (×3.1)",
	["금빛 뿔과 수염, 몸을 따라 흐르는 금빛 가루"] = "Golden horns and whiskers, golden dust flowing along its body",
	["두 배 처치"] = "Double Kills",
	["적을 쓰러뜨려 오르는 능력치가 영원히 두 배"] = "Stats gained from defeating enemies doubled forever",
	["졸병·정예·보스·천층탑 모두"] = "Grunts, elites, bosses and the Tower alike",
	["두 배 수련과 겹친다 (수련은 수련, 처치는 처치)"] = "Stacks with Double Training (training for training, kills for kills)",
	["행운의 부적"] = "Lucky Charm",
	["보스의 심법 두루마리 확률 두 배 (15% → 30%)"] = "Double boss manual scroll chance (15% → 30%)",
	["천상 재료가 떨어질 확률 두 배 (한 번에 둘까지는 그대로)"] = "Double heavenly material drop chance (max two at once still applies)",
	["천상계 적의 천정 1.5배"] = "Sky gems from heavenly enemies x1.5",
	["머리 위 이름 앞에 금빛 👑"] = "A golden 👑 before your name overhead",
	["권법 숙련이 두 배로 빨리 오른다"] = "Style mastery rises twice as fast",
	["적·보스의 은자 +25% (은자 두 배와 겹친다)"] = "Silver from enemies and bosses +25% (stacks with Double Silver)",
	["심법 넷째 칸"] = "Fourth Manual Slot",
	["심법을 셋이 아니라 넷까지 끼운다"] = "Equip four manuals instead of three",
	["체력·공격·흡혈·대기 시간 효과가 한 칸 더"] = "One more slot of HP, attack, lifesteal and cooldown effects",
	["심법 화면에 넷째 칸이 열린다"] = "A fourth slot opens in the manual screen",
	["흑룡 탈것"] = "Black Dragon Mount",
	["검은 비늘에 붉은 불길이 타오르는 흑룡"] = "A black-scaled dragon wreathed in red flame",
	["청룡 다음으로 빠르다 (×3.0, 가장 빠른 건 그대로 청룡)"] = "Fastest after the Azure Dragon (×3.0; the Azure Dragon is still the fastest)",
	["흑룡만의 불꽃 기운이 몸을 따라 흐른다"] = "The Black Dragon's own flame aura flows along its body",
	["권법"] = "Style",
	["전설 권법 · 푸른 여우불과 여우 꼬리 (빠르고 가볍다)"] = "Legendary style · blue foxfire and fox tails (fast and light)",
	["강화 +15까지: 꼬리가 하나에서 아홉으로 늘어나며 세진다"] = "Enhance up to +15: grows from one tail to nine as it gets stronger",
	["강화 재료는 보스의 비급 조각 · 은자 (게임 안에서 모은다)"] = "Enhancement materials are boss manual fragments and silver (collected in-game)",
	["권왕 권법 · 검은 불꽃으로 손에 검을 빚어 벤다 (초 오의 X까지)"] = "Fist King-tier style · forges swords from black flame to cut (up to Ultimate Art X)",
	["강화 +15까지: 검이 둘로 늘고 불꽃이 보랏빛 · 핏빛으로 타오르며 세진다"] = "Enhance up to +15: grows to two swords, flames burn purple and blood red as it gets stronger",
	["끝까지 강화해도 극 · 신 권법 아래 (배틀그라운드는 전설과 같은 세기)"] = "Even fully enhanced, below Apex and Divine styles (Battleground strength equals Legendary)",
	["천정 두 배"] = "Double Sky Gems",
	["천상계 적·보스에게서 얻는 천정 두 배"] = "Sky gems from heavenly enemies and bosses doubled",
	["천층탑 최고 층 천정도 두 배"] = "Top-floor sky gems in the Tower doubled too",
	["행운의 부적 (1.5배)과 겹친다"] = "Stacks with the Lucky Charm (1.5x)",
	["은자 주머니"] = "Silver Pouch",
	["은자 상자"] = "Silver Box",
	["은자 궤짝"] = "Silver Chest",
	["소환단 한 시간"] = "Summoning Pill (one hour)",
	["심법 두루마리 10장"] = "10 Manual Scrolls",
	["💰 은자 "] = "💰 Silver ",
	[" (지금 경지 기준)"] = " (based on your current realm)",
	["🧪 한 시간 동안 수련 두 배 (소환단과 같다, 남은 시간에 더해진다)"] = "🧪 Double training for one hour (same as a Summoning Pill, added to remaining time)",
	["📜 심법 두루마리 "] = "📜 Manual scrolls ",
	["장 (심법 뽑기)"] = "x (manual draw)",
	["✨ 신의 모습"] = "✨ Divine Form",
	["신을 채우면 쓰러질 때까지 몸이 떠올라 신의 모습이 되고 기술이 모두 바뀐다"] = "Fill Divine and you float into Divine Form until you fall, with all skills changed",
	["🌠 초가속"] = "🌠 Hyper Speed",
	["극을 채우면 잠시 초가속 (걸음 ×1.6 · 잔상 타격) 이 되고 기술이 모두 바뀐다"] = "Fill Apex for a short burst of hyper speed (stride ×1.6 · afterimage hits) with all skills changed",
	["⬜ 격자 전개"] = "⬜ Grid Deployment",
	["극을 채우면 3D 격자 공간이 펼쳐지고 기술이 모두 바뀐다"] = "Fill Apex to unfold a 3D grid space with all skills changed",
	["🌇 황혼 (일월극변)"] = "🌇 Twilight (Sun-Moon Apex Shift)",
	["극을 채우면 40초 동안 세상이 황혼에 멈추고 기술이 바뀐다"] = "Fill Apex and the world halts at twilight for 40 seconds with skills changed",
	["천궁"] = "Sky Palace",
	["운해 평원"] = "Cloud Plain",
	["뇌정봉"] = "Thunder Peak",
	["성운원"] = "Nebula Garden",
	["옥좌대"] = "Throne Terrace",
	["금 간 허공"] = "Cracked Void",
	["빙정궁"] = "Frost Crystal Palace",
	["봉황대"] = "Phoenix Terrace",
	["비천폭"] = "Flying Falls",
	["청학봉"] = "Blue Crane Peak",
	["운무 죽림"] = "Misty Bamboo Grove",
	["월광 호수"] = "Moonlight Lake",
	["금운사"] = "Golden Cloud Temple",
	["윤회대"] = "Rebirth Terrace",
	["극광대"] = "Aurora Terrace",
	["선계 정원"] = "Immortal Garden",
	["아공선인"] = "Subspace Sage",
	["금 간 허공 (천상계)"] = "Cracked Void (Heavenly Realm)",
	["공간은 비어 있지 않다. 접혀 있을 뿐."] = "Space isn't empty. It's folded.",
	["천상계 운해 평원의 서쪽 끝에서, 보이지 않는 다리가 허공으로 이어진다더라"] = "They say an invisible bridge stretches into the void from the west end of the Cloud Plain in the Heavenly Realm",
	["격자지기"] = "Grid Keeper",
	["세상 끝 너머 (망각의 정원)"] = "Beyond the End of the World (Garden of Oblivion)",
	["펼쳐 보면 알게 된다. 빈칸에도 좌표가 있다는 것을."] = "Unfold it and you'll see. Even a blank has coordinates.",
	["세상 끝 벼랑 너머, 무너지는 돌길 끝에 떠 있는 정원에서 허공에 격자를 긋는 자가 있다더라"] = "They say beyond the World's End Cliffs, in a garden floating at the end of a crumbling stone path, someone draws grids in the air",
	["황혼권존"] = "Twilight Fist Sovereign",
	["윤회대 (천상계)"] = "Rebirth Terrace (Heavenly Realm)",
	["해도 달도 한쪽만 고집하지 않는다. 극은 그 균형에 있다."] = "Neither sun nor moon clings to one side. The Apex lies in that balance.",
	["천상 윤회대, 해와 달 사이의 노을 속에 권존보다 먼저 권존이었던 이가 서 있다더라"] = "They say on the Heavenly Rebirth Terrace, in the sunset between sun and moon, stands one who was Fist Sovereign before the Fist Sovereign",
	["질주귀"] = "Racing Ghost",
	["지옥 (황천 나루)"] = "Underworld (Hwangcheon Ferry)",
	["빠르다는 건 서두르는 게 아니다. 군더더기가 없는 것이다."] = "Being fast isn't hurrying. It's having nothing extra.",
	["저승 너머 황천 나루에, 사신보다 빠르다는 귀신이 서 있다더라"] = "They say a ghost faster than the reaper stands at the Hwangcheon Ferry beyond the afterlife",
	["운류자"] = "Drifting Cloud Master",
	["천궁 (천상계)"] = "Sky Palace (Heavenly Realm)",
	["구름은 밀어도 흩어지지 않는다."] = "Push a cloud and it doesn't scatter.",
	["천상계 천궁 북서쪽 정자에 구름처럼 앉은 노인이 있다더라"] = "They say an old man sits like a cloud in the pavilion northwest of the Sky Palace in the Heavenly Realm",
	["철쇄노인"] = "Old Iron Chain",
	["청운 들판 동쪽"] = "East of Cheongun Fields",
	["주먹은 빗나가도, 붙잡은 손은 빗나가지 않는다."] = "A fist can miss. A hand that has grabbed doesn't.",
	["청운 마을 남쪽 들판 동쪽에 쇠사슬을 허리에 감은 노인이 있다더라"] = "They say an old man with iron chains wrapped around his waist is in the east of the fields south of Cheongun Village",
	["역류객"] = "Countercurrent Wanderer",
	["청운 들판 서쪽"] = "West of Cheongun Fields",
	["먼저 치는 자가 먼저 진다."] = "Whoever strikes first loses first.",
	["청운 마을 남쪽 들판 서쪽에 늘 눈을 감고 서 있는 사람이 있다더라"] = "They say someone always stands with eyes closed in the west of the fields south of Cheongun Village",
	["질풍랑"] = "Gale Youth",
	["청운 마을 동남쪽 들판"] = "Fields southeast of Cheongun Village",
	["바람은 멈추면 바람이 아니다."] = "Wind that stops is no longer wind.",
	["청운 마을 동남쪽 들판에 잠시도 가만히 있지 않는 젊은이가 있다더라"] = "They say a young man who never stays still is in the fields southeast of Cheongun Village",
	["붕산노조"] = "Mountain Crusher Patriarch",
	["산은 한 번에 무너진다. 그 한 번을 위해 천 년을 쌓는다."] = "A mountain falls all at once. It takes a thousand years to build up for that once.",
	["붉은 황야 남쪽, 갈라진 바위 언덕 위에 산처럼 앉은 노인이 있다더라"] = "They say an old man sits like a mountain on a cracked rocky hill south of the red wasteland",
	["빙혼노니"] = "Ice Soul Nun",
	["북방 설산 얼음 벼랑"] = "Ice cliffs of the northern snow mountains",
	["얼음은 차갑지 않다. 다만 움직이지 않을 뿐."] = "Ice isn't cold. It just doesn't move.",
	["북방 설산 동쪽 얼음 벼랑 아래, 얼어붙은 폭포 앞에 숨결이 하얀 노니가 있다더라"] = "They say a nun with white breath is before the frozen waterfall under the ice cliffs east of the northern snow mountains",
	["옥진인"] = "Jade Sage",
	["석림 옥 기둥"] = "Jade pillars of the Stone Forest",
	["옥은 깎을수록 빛난다. 사람도 그렇다."] = "Jade shines the more it's carved. So do people.",
	["서쪽 끝 석림, 옥처럼 푸른 기둥 사이에 앉아 돌을 다듬는 이가 있다더라"] = "They say someone sits carving stone among the jade-blue pillars of the Stone Forest at the far west",
	["종지기"] = "Bell Keeper",
	["단풍산 꼭대기"] = "Top of Maple Mountain",
	["종은 스스로 울지 않는다. 치는 자가 있어야 운다."] = "A bell doesn't ring on its own. It rings when someone strikes it.",
	["동북쪽 끝 단풍산 꼭대기, 낡은 종 아래 하루에 한 번 종을 치는 이가 있다더라"] = "They say someone rings the old bell once a day atop Maple Mountain at the far northeast",
	["명경선"] = "Clear Mirror Immortal",
	["운무 차밭 거울 연못"] = "Mirror Pond of the Misty Tea Fields",
	["거울은 무엇이든 비춘다. 그래서 무엇도 붙잡지 않는다."] = "A mirror reflects anything. That's why it holds on to nothing.",
	["서북쪽 끝 운무 차밭 한가운데, 거울처럼 맑은 연못가에 앉은 신선이 있다더라"] = "They say an immortal sits by a mirror-clear pond in the middle of the misty tea fields at the far northwest",
	["천룡진인"] = "Heavenly Dragon Sage",
	["천룡봉 동쪽 용의 등뼈"] = "Dragon's spine east of Dragon Peak",
	["힘을 빼야 멀리 친다. 용도 바람을 거스르지 않는다."] = "Relax to hit far. Even a dragon doesn't fight the wind.",
	["천룡봉 동쪽, 용의 등뼈처럼 솟은 바위 위에 금빛 수염의 진인이 서 있다더라"] = "They say a golden-bearded sage stands on rocks rising like a dragon's spine east of Heavenly Dragon Peak",
	["패왕"] = "Overlord",
	["황사 협곡 무너진 왕좌"] = "Fallen Throne of Yellow Dust Canyon",
	["왕좌는 금방 무너진다. 남는 건 몸에 익힌 것뿐이다."] = "Thrones fall quickly. What remains is what your body has learned.",
	["동쪽 끝 황사 협곡, 무너진 돌 왕좌에 홀로 앉은 사내가 있다더라"] = "They say a man sits alone on a fallen stone throne in the Yellow Dust Canyon at the far east",
	["성하노군"] = "Starry River Elder",
	["성운원 깊은 곳 (천상계)"] = "Deep in the Nebula Garden (Heavenly Realm)",
	["별은 떨어지지 않는다. 내려올 뿐이다."] = "Stars don't fall. They come down.",
	["천상계 성운원의 가장 깊은 곳, 성군의 등 뒤에 별을 헤아리는 노인이 있다더라"] = "They say an old man counts stars behind the Star Lord in the deepest part of the Nebula Garden in the Heavenly Realm",
	["천앵선"] = "Cherry Fan Immortal",
	["매화원 깊은 곳 (벚꽃 언덕)"] = "Deep in the Plum Garden (cherry hill)",
	["꽃잎은 바람을 따라 움직인다. 부채도 그렇게 써라."] = "Petals move with the wind. Use a fan the same way.",
	["매화원 가장 깊은 곳, 철 모르고 벚꽃이 흩날리는 언덕에 부채 든 이가 있다더라"] = "They say someone with a fan is on a hill where cherry blossoms fall out of season, deepest in the Plum Garden",
	["만취선"] = "Dead-Drunk Immortal",
	["취선 주막 남쪽 (술독 마루)"] = "South of the Drunken Immortal Inn (wine-jar porch)",
	["비틀거림도 초식이다. 쓰러질 듯 서는 자가 가장 오래 선다."] = "Staggering is a technique too. Those who stand as if about to fall stand the longest.",
	["취선 주막에서 남쪽 길로 조금 내려가면, 술독이 산처럼 쌓인 마루에서 수건을 머리에 동여맨 노인이 코를 곤다더라"] = "They say a little way down the south road from the Drunken Immortal Inn, an old man with a towel tied around his head snores on a porch piled high with wine jars",
	["혈월선"] = "Blood Moon Immortal",
	["혈교 본산 밖 (혈월 제단)"] = "Outside the Blood Cult HQ (blood-moon altar)",
	["피를 보고 흔들리면 그 순간 진다. 낫은 늘 같은 궤를 그린다."] = "Waver at the sight of blood and you lose right then. A scythe always draws the same arc.",
	["혈교 본산의 북동쪽 성벽 너머, 핏빛 달이 걸린 돌단에 거꾸로 꽂힌 붉은 낫이 있다더라"] = "They say beyond the northeast wall of the Blood Cult HQ, a red scythe is stuck upside-down in a stone altar under a blood-red moon",
	["뇌천선"] = "Thunder Heaven Immortal",
	["뇌운 고원 동쪽 벼랑 끝 (쇠기둥 봉우리)"] = "East cliff edge of the Storm Plateau (iron-pillar peak)",
	["벼락은 망설이지 않는다. 한 번 정했으면 끝까지 쳐라."] = "Lightning doesn't hesitate. Once you decide, strike to the end.",
	["뇌운 고원에서 동쪽 벼랑으로 가면, 벼락이 그치지 않는 쇠기둥 봉우리 위에 앉은 노인이 있다더라"] = "They say if you go from the Storm Plateau to the east cliff, an old man sits atop an iron-pillar peak where lightning never stops",
	["고경선"] = "Ancient Whale Immortal",
	["서해 바닷가 고래 뼈 바위"] = "Whale-bone rock on the west sea shore",
	["바다의 끝을 보았다 해도, 그 깊이는 아직 모른다."] = "Even if you've seen the end of the sea, you don't yet know its depth.",
	["창해각에서 북쪽 바닷가로 가면, 모래에 반쯤 묻힌 거대한 고래 뼈 위에 앉아 파도 소리를 듣는 노인이 있다더라"] = "They say if you go from the Azure Sea Pavilion to the north shore, an old man sits on a giant whale bone half-buried in sand, listening to the waves",
	["...세상 남동쪽 끝, 큰 바위 옆에 누가 서 있다는데, 말을 들은 사람은 없다더라"] = "...They say someone stands beside a big rock at the southeast end of the world, but no one has ever heard them speak",
	["몽선"] = "Dream Sage",
	["남서쪽 연못 연화정"] = "Lotus Pavilion on the southwest pond",
	["꿈속에서도 발은 땅을 딛고 있어야 한다."] = "Even in a dream, your feet must stand on the ground.",
	["남서쪽 먼 연못 한가운데 정자에서, 해가 떠도 졸고 있는 노인이 있다더라. 두 번 다시 태어난 자의 꿈만 들어준다고"] = "They say an old man dozes even after sunrise in a pavilion in the middle of a far southwest pond. He only listens to the dreams of those born twice",
	["천성선"] = "Star Counting Immortal",
	["성운원 남쪽 끝 관성대 (천상계)"] = "Observatory at the south end of the Nebula Garden (Heavenly Realm)",
	["별은 매일 같은 길을 돈다. 꾸준함만 한 무공은 없다."] = "Stars travel the same path every day. No martial art beats consistency.",
	["성운원 남쪽 끝, 구리 고리가 저절로 도는 둥근 관측대 위에서 지팡이로 별을 헤아리는 노인이 있다더라"] = "They say at the south end of the Nebula Garden, an old man counts stars with a staff atop a round observatory where copper rings turn on their own",
	["목선"] = "Tree Sage",
	["남서쪽 들판 깊은 숲 (만목원)"] = "Deep forest of the southwest fields (Myriad Tree Grove)",
	["나무는 서두르지 않는다. 그런데도 늘 이긴다."] = "A tree doesn't hurry. Yet it always wins.",
	["남서쪽 들판의 비틀린 고목들이 둥글게 선 숲 한가운데, 이끼 덮인 돌에 앉은 노인이 있다더라"] = "They say an old man sits on a mossy stone in the middle of a ring of twisted old trees in the southwest fields",
	["각성선인"] = "Awakening Sage",
	["권법이 바뀌려면 먼저 몸에 완전히 익어야 한다."] = "For a style to change, it must first be fully ingrained in your body.",
	["천상 빛깔"] = "Heavenly Hue",
	["지금 쓰는 권법의 시그니처 장신구를 별빛 도는 천상 빛깔로 (권법마다 한 번, 메뉴로 켜고 끈다)"] = "Turn your current style's signature accessory a starlit heavenly hue (once per style, toggle in the menu)",
	["천상 오라"] = "Heavenly Aura",
	["몸 둘레에 천정 조각 셋이 맴돌고 발밑에 별빛이 인다 (한 번 사면 늘)"] = "Three sky gem shards orbit you and starlight rises underfoot (buy once, keep forever)",
	["날개구름 (탈것)"] = "Winged Cloud (mount)",
	["가장 빠른 탈것. 천정으로만 얻는다"] = "The fastest mount. Only obtainable with sky gems",
	["천상 영약"] = "Heavenly Elixir",
	["10분 동안 주는 피해 +15%"] = "Damage dealt +15% for 10 minutes",
	["선로주"] = "Immortal Dew Wine",
	["천상의 이슬로 빚은 술 (초·취팔선권의 재료)"] = "Wine brewed from heavenly dew (material for Ultimate Drunken Fist)",
	["천상 두루마리 묶음"] = "Heavenly Scroll Bundle",
	["심법 두루마리 열"] = "Ten manual scrolls",
	["천앵 꽃잎"] = "Heaven Cherry Petal",
	["청학봉 섬의 적 (선학은 꼭 둘)"] = "Enemies on Blue Crane Peak (the Crane Sage always drops two)",
	["천궁 상점에서 천정으로 빚는다"] = "Crafted with sky gems at the Sky Palace shop",
	["혈월정"] = "Blood Moon Crystal",
	["밤에 천상계의 적 (보스는 꼭 둘)"] = "Heavenly enemies at night (bosses always drop two)",
	["뇌정석"] = "Thunder Stone",
	["천상계의 보스만 (한 번에 둘)"] = "Heavenly bosses only (two at a time)",
	["비천 진주"] = "Bicheon Pearl",
	["비천폭 섬의 적 (비천은 꼭 둘)"] = "Enemies at Flying Falls (Bicheon always drops two)",
	["별가루"] = "Stardust",
	["성운원 섬의 적 (성군은 꼭 둘)"] = "Enemies in the Nebula Garden (the Star Lord always drops two)",
	[". 그리고 원래 권법과 각성 권법(진)을 숙련 %d까지, 천상계에서만 나는 재료를 모아야 한다"] = ". Also raise the original style and its awakened (True) style to mastery %d and gather materials found only in the Heavenly Realm",
	[". 그리고 원래 권법을 숙련 %d까지, 천상계에서만 나는 재료를 모아야 한다"] = ". Also raise the original style to mastery %d and gather materials found only in the Heavenly Realm",
