	["핏빛 불길이 온몸에서 타오르고 불티가 튄다"] = "Blood-red flames burn all over your body, throwing sparks",
	["파천 기운"] = "Sky-Breaking Aura",
	["검보랏빛 연기가 몸을 휘감고 흰 번갯불이 잘게 튄다"] = "Dark purple smoke wraps your body with small flickers of white lightning",
	["운석 기운"] = "Meteor Aura",
	["두 손과 두 발에서 주황 불꽃이 일고 재가 날린다"] = "Orange flames rise from your hands and feet, scattering ash",
	["발밑에 흰 구름이 피어오르고 무지갯빛 가루가 올라간다"] = "White clouds bloom underfoot and rainbow dust rises",
	["윤회 기운"] = "Rebirth Aura",
	["보랏빛 영기가 느릿하게 타오르고 금빛 별가루가 가라앉는다"] = "Purple spirit energy burns slowly while golden stardust settles",
	["만권 기운"] = "Ten Thousand Fists Aura",
	["청백의 맑은 기운이 몸을 감싸고 정수리에서 흰·금빛 반짝임이 흩어진다"] = "A clear blue-white energy wraps your body, with white and gold sparkles scattering from your crown",
	["천상 꽃잎"] = "Heavenly Petals",
	["연분홍·하늘빛 꽃잎이 몸 둘레에서 나풀나풀 떨어진다"] = "Pale pink and sky-blue petals flutter down around you",
	["천서 기운"] = "Heavenly Script Aura",
	["푸른 안개가 깔리고 빛의 글자가 천천히 떠오른다"] = "Blue mist settles as glowing letters slowly rise",
	["금룡 기운"] = "Golden Dragon Aura",
	["발끝부터 머리 위까지 금빛 화염이 치솟고 흰 불씨가 흩날린다"] = "Golden flames surge from toe to crown, scattering white embers",
