	["처음의 돌"] = "Stones of the Beginning",
	["세상의 처음은 하늘에서 떨어졌다. 별똥 분화구 한가운데에 서 보아라"] = "The beginning of the world fell from the sky. Stand in the middle of the Meteor Crater",
	["발밑이 따뜻하다. 아주 오래전, 여기에 별이 떨어졌다."] = "It's warm underfoot. Long ago, a star fell here.",
	["분화구 둘레에 흩어진 '처음의 돌' 셋을 주워라 (빛나는 돌, T)"] = "Pick up the three 'Stones of the Beginning' scattered around the crater (glowing stones, T)",
	["처음의 돌을 시원자에게 가져가라"] = "Bring the Stones of the Beginning to the Origin Sage",
	["해와 달의 차례"] = "The Order of Sun and Moon",
	["해의 기둥"] = "Sun Pillar",
	["해시계 광장의 해의 기둥 넷을, 해가 떠오르듯 가장 낮은 것부터 가장 높은 것까지 차례로 짚어라 (T)"] = "Touch the four sun pillars in Sundial Plaza in order, from lowest to highest, like the rising sun (T)",
	["달이 뜬 밤, 거울 호수 가운데 섬에 서서 물에 비친 달을 보아라"] = "On a moonlit night, stand on the island in the middle of Mirror Lake and look at the moon in the water",
	["물속의 달이 하늘의 달보다 밝다."] = "The moon in the water is brighter than the moon in the sky.",
	["해와 달을 모두 본 몸으로 권존에게 돌아가라"] = "Having seen both sun and moon, return to the Fist Sovereign",
	["멈춘 시계"] = "The Stopped Clock",
	["시계 톱니"] = "Clock Gear",
	["버려진 마을과 해시계 광장에 흩어진 멈춘 시계의 톱니 넷을 모아라 (T)"] = "Collect the four gears of the stopped clock scattered in the Abandoned Village and Sundial Plaza (T)",
	["천년 종루 아래에서 종소리가 몇 번 울리는지 들어라"] = "Listen beneath the Thousand-Year Bell Tower for how many times the bell rings",
	["종이 한 번 울렸다. 소리가 한참 동안 산을 돈다."] = "The bell rang once. The sound circles the mountain for a long time.",
	["톱니를 영겁노인에게 가져가라"] = "Bring the gears to the Eternal Elder",
	["허공의 틈"] = "Crack in the Void",
	["허공 균열의 허공 마인 다섯을 쓰러뜨려 틈을 닫아라"] = "Defeat five void demons in the Void Rift to close the crack",
	["끊어진 하늘다리 끝에 서서, 다리 너머의 허공을 들여다보아라"] = "Stand at the end of the Broken Sky Bridge and look into the void beyond it",
	["발밑이 아득하다. 한 걸음만 더 나가면 떨어진다."] = "It's a long way down. One more step and you fall.",
	["아공선인에게 돌아가라"] = "Return to the Subspace Sage",
	["별을 헤아리는 밤"] = "A Night of Counting Stars",
	["밤에 별바위 고리 한가운데에서 별을 헤아려라"] = "At night, count the stars in the middle of the Star Rock Ring",
	["별을 다 헤아렸을 즈음, 손끝이 차갑게 맑아졌다."] = "By the time you finished counting, your fingertips felt cold and clear.",
	["떨어진 별 조각"] = "Fallen Star Shards",
	["천상계 성운원에 떨어진 별 조각 다섯을 주워라 (T)"] = "Pick up five star shards fallen in the Nebula Garden of the Heavenly Realm (T)",
	["별 조각을 성하노군에게 가져가라"] = "Bring the star shards to the Starry River Elder",
	["시든 묘목"] = "Withered Saplings",
	["만목원 둘레의 시든 묘목 넷에 물을 주어라 (T)"] = "Water the four withered saplings around the Myriad Tree Grove (T)",
	["숲을 썩게 하는 독안개 늪의 늪 거한 셋을 쓰러뜨려라"] = "Defeat three swamp brutes in the Poison Mist Swamp that rot the forest",
	["목선에게 돌아가라"] = "Return to the Tree Sage",
	["떨어진 부채 장식"] = "Fallen Fan Ornaments",
	["부채 장식"] = "Fan Ornament",
	["벚꽃 언덕 아래 떨어진 부채 장식 셋을 찾아라 (T)"] = "Find the three fan ornaments dropped below the cherry hill (T)",
	["천앵선에게 돌아가라"] = "Return to the Cherry Fan Immortal",
	["술잔 찾기"] = "Find the Cups",
	["만취선의 술잔"] = "Dead-Drunk Immortal's Cup",
	["술독 마루 둘레에 굴러간 만취선의 술잔 넷을 찾아라 (T)"] = "Find the four cups of the Dead-Drunk Immortal that rolled off around the wine-jar porch (T)",
	["술잔을 만취선에게 가져가라"] = "Bring the cups to the Dead-Drunk Immortal",
	["핏빛 달 아래"] = "Under the Blood Moon",
	["밤에 혈월곡의 핏빛 달 아래에 서라"] = "At night, stand under the blood-red moon of Blood Moon Valley",
	["달빛이 손톱 끝까지 붉게 스민다."] = "The moonlight seeps red to the tips of your nails.",
	["혈월선에게 돌아가라"] = "Return to the Blood Moon Immortal",
	["번개를 기다리다"] = "Waiting for Lightning",
	["만검총 한가운데, 가장 높은 검 아래에서 번개를 기다려라"] = "Wait for lightning beneath the tallest sword in the middle of the Graveyard of Swords",
	["검 끝에서 파란 불꽃이 튄다. 팔의 털이 곤두선다."] = "Blue sparks jump from the sword tip. The hair on your arms stands up.",
