	["연화정 둘레에 떨어져 잠든 별 다섯을 깨워라 (T)"] = "Wake the five sleeping stars fallen around the Lotus Pavilion (T)",
	["달이 뜬 밤, 거울 호수에 비친 달 위에 서 보아라"] = "On a moonlit night, stand on the moon reflected in Mirror Lake",
	["물에 비친 달이 흔들린다. 졸음이 한꺼번에 밀려온다."] = "The reflected moon wavers. Drowsiness washes over you all at once.",
	["연꽃 등"] = "Lotus Lamp",
	["연화정 남쪽 물가의 연꽃 등 다섯을 무지개의 차례로 밝혀라 (빨강 → 주황 → 노랑 → 초록 → 파랑, T)"] = "Light the five lotus lamps on the south shore of the Lotus Pavilion in rainbow order (red → orange → yellow → green → blue, T)",
	["몽선을 깨워라 (말을 걸어라)"] = "Wake the Dream Sage (talk to him)",
	["지워진 글자"] = "Erased Letters",
	["강호의 랜드마크 넷 (버려진 광산 입구 · 일검 바위 틈 · 귀부 비석 뒤 · 선인송 아래)에 떨어진 지워진 글자를 주워라 (T)"] = "Pick up the erased letters dropped at four landmarks (Abandoned Mine entrance · crack in One Sword Rock · behind the Turtle Stele · under the Immortal Pine) (T)",
	["밤에, 세상의 반대편 끝 (북서쪽 맨 끝)의 아무것도 없는 곳에 서라"] = "At night, stand in the empty place at the opposite end of the world (the far northwest)",
