	["🪨 일곱 돌탑"] = "🪨 Seven Cairns",
	["길이 답했다"] = "The Road Answered",
	["강호 곳곳의 돌탑 일곱에 모두 돌을 올렸다. 마지막 돌탑 밑에 누군가 묻어 둔 꾸러미가 있다. 💰 %s 은자와 심법 두루마리 %d개를 얻었다.\n\n...그런데 바람 소리 사이로 무언가 지직거린다. 세상의 남동쪽 맨 끝, 지도에 그려지지 않은 곳에서."] = "You've added stones to all seven cairns across the martial world. Under the last cairn, someone buried a bundle. You got 💰 %s silver and %d manual scrolls.\n\n...But something crackles between the sounds of the wind. At the southeast end of the world, somewhere not on the map.",
	["🐈 고양이가 깔고 자던 금창약 %d병을 내주었다"] = "🐈 The cat gave you %d Wound Salves it was sleeping on",
	["🗡 뽑았던 검을 도로 꽂아 두었다. 다음 사람을 위해"] = "🗡 You put the sword back in. For the next person",
	["🗡 바위에 박힌 검"] = "🗡 Sword in the Stone",
	["검이 빠졌다"] = "The Sword Came Out",
	["백 번째 당기자 검이 스르륵 빠졌다. 칼자루에 작은 글씨가 있다. '힘이 아니라 끈기였다.' 검은 녹슬었지만, 칼자루 속에서 💰 %s 은자가 쏟아졌다."] = "On the hundredth pull, the sword slid out. Small letters on the hilt read: 'It wasn't strength. It was persistence.' The blade is rusted, but 💰 %s silver poured out of the hilt.",
	["🗡 검이 아주 조금 움직인 것 같다 (%d/%d)"] = "🗡 The sword seemed to move just a little (%d/%d)",
	["💰 던질 은자가 모자라요"] = "💰 Not enough silver to toss",
	["🪙 우물이 반짝였다! 💰 %s 은자가 솟아올랐다"] = "🪙 The well sparkled! 💰 %s silver came up",
	["🪙 소원이 닿았다. 5분 동안 주는 피해 +15%"] = "🪙 Your wish was heard. Damage dealt +15% for 5 minutes",
	["🌫 상자는 비어 있다. 바람만 머문다"] = "🌫 The chest is empty. Only the wind remains",
	["🌫 망각의 정원"] = "🌫 Garden of Oblivion",
	["세상의 끝, 그 너머"] = "Beyond the End of the World",
	["무너지는 돌길을 건너 아무도 오지 않는 정원에 닿았다. 낡은 상자 속에 누군가 남긴 글이 있다. '끝이라 부르는 곳은, 대개 아직 아무도 건너지 않은 곳이다.' 💰 %s 은자 · 💠 천정 %d · 📜 두루마리 %d개를 얻었다."] = "You crossed the crumbling stone path and reached a garden no one visits. In an old chest is a note someone left: 'What we call the end is usually just a place no one has crossed yet.' You got 💰 %s silver · 💠 %d sky gems · 📜 %d scrolls.",
	["🦆 꽥! 어미 오리가 심법 두루마리 하나를 물어다 주었다"] = "🦆 Quack! The mother duck brought you a manual scroll",
	["🕳 희미한 풀이 꺼지며 발밑이 사라졌다"] = "🕳 The faint grass gave way and the ground vanished beneath you",
	["🕳 땅 밑"] = "🕳 Underground",
	["떨어졌다"] = "You Fell",
	["세상의 끝자락, 아무도 밟지 않던 풀이었다. 어둠 속으로 한참을 떨어져 차가운 돌바닥에 닿았다. 붉은 빛이 번지는 큰 문과, 검은 갓을 쓴 그림자가 보인다."] = "It was grass at the edge of the world that no one had stepped on. You fell through the darkness for a long time and landed on cold stone. You see a great door glowing red and a shadow in a black hat.",
	["🌿 이 풀만 유난히 서늘하다... (세 번 환생한 몸이라면 무언가 느낄지도)"] = "🌿 Only this grass feels oddly cool... (someone reborn three times might sense something)",
	["💀 사신"] = "💀 Reaper",
	["열린 문"] = "The Open Gate",
	["...사슬은 이미 끊어졌다. 복도 끝, 문이 숨을 쉬는 소리가 들리느냐. 가거라. 저 너머는 이승과 다르다. 몸조심해라."] = "...The chains are already broken. Hear the door breathing at the end of the hall? Go. It's different from the living world over there. Take care.",
	["산 자의 냄새가 난다"] = "I Smell the Living",
	["...산 사람이 여기까지 왔군. 복도 끝 문을 열고 싶으냐. 삯은 💰 %s 은자다. 지금 가진 것으로는 모자라다. 채워서 오너라. 나는 여기서 기다리고 있으마."] = "...So a living person came this far. Want to open the door at the end of the hall? The fare is 💰 %s silver. What you have isn't enough. Come back with it. I'll be waiting here.",
	["삯을 받았다"] = "Fare Received",
	["💰 %s 은자. ...좋다. 삯은 받았다. 복도 끝 문은 사슬 셋으로 잠겨 있다. 이 방을 떠도는 원혼 셋이 그 사슬을 쥐고 놓지 않는다. 가서 달래라. 달래지 못하면 문도 열리지 않는다. (원혼 %d)"] = "💰 %s silver. ...Good. Fare received. The door at the end of the hall is locked with three chains. Three restless spirits wandering this room hold them and won't let go. Go calm them. If you can't, the door won't open. (spirits %d)",
	["아직이다"] = "Not Yet",
	["...아직이냐. 원혼은 방 가장자리를 떠돈다. 푸른 불을 따라가라. 울음소리가 들릴 것이다. 달랜 혼 %d / %d."] = "...Not yet? The spirits wander the edges of the room. Follow the blue fire. You'll hear crying. Spirits calmed %d / %d.",
	["사슬이 끊어졌다"] = "The Chains Broke",
	["......혼들이 가벼워졌구나. 들리느냐. 복도 끝에서 사슬이 끊어지는 소리가. 문 너머에서 뜨거운 바람이 올라온다.\n\n복도를 걸어가 문 앞에 서라."] = "......The spirits feel lighter. Hear that? The chains breaking at the end of the hall. A hot wind rises from beyond the door.\n\nWalk down the hall and stand before the door.",
	["💙 원혼이 너를 힐끗 보고 멀어진다. 먼저 사신과 이야기하자"] = "💙 The spirit glances at you and drifts away. Talk to the reaper first",
	["💙 이미 달랜 혼이다. 편안히 흔들린다"] = "💙 Already calmed. It sways peacefully",
	["💙 원혼을 달랬다 (%d/%d)"] = "💙 Calmed a spirit (%d/%d)",
	["⛓ 사슬이 문을 휘감고 있다. 꿈쩍도 않는다"] = "⛓ Chains wrap the door. It won't budge",
	["싸우는 중에는 지옥문을 건널 수 없어요"] = "You can't cross the Hell Gate mid-fight",
	["🔥 지옥문"] = "🔥 Hell Gate",
	["붉은 숨"] = "Red Breath",
	["문이 열린다. 뜨거운 붉은 기운이 얼굴을 때린다. 사슬이 풀린 문턱 너머로, 끝이 보이지 않는 어둠과 불빛이 펼쳐져 있다.\n\n사신이 뒤에서 중얼거린다. \"...돌아올 수 있을 때 돌아와라.\""] = "The door opens. Hot red air hits your face. Beyond the unchained threshold stretch endless darkness and firelight.\n\nThe reaper mutters behind you. \"...Come back while you still can.\"",
	["싸우는 중에는 문을 건널 수 없어요"] = "You can't cross the gate mid-fight",
	["⬆ 저승 방으로 돌아왔어요"] = "⬆ Returned to the underworld room",
	["🌿 이승으로 올라왔다"] = "🌿 Climbed back to the living world",
	["🛏 푹 쉬었다. 체력과 내공이 가득 찼다 · 이제 쓰러지면 청운 마을에서 깨어난다"] = "🛏 Rested well. HP and Ki fully restored · if you fall now, you'll wake in Cheongun Village",
	["🛏 푹 쉬었다. 체력과 내공이 가득 찼다"] = "🛏 Rested well. HP and Ki fully restored",
	["에서 푹 쉬었다. 체력과 내공이 가득 찼다"] = ": rested well. HP and Ki fully restored",
	["에서 쉬었다 · 이제 쓰러지면 여기서 깨어난다"] = ": rested · if you fall now, you'll wake here",
	["%s %s을(를) 익혔어요! 권법 창에서 강화할 수 있어요"] = "%s %s learned! You can enhance it in the Styles window",
	["🐉 청룡을 얻었어요! V로 타기"] = "🐉 Got the Azure Dragon! V to ride",
	["🐲 흑룡을 얻었어요! V로 타기"] = "🐲 Got the Black Dragon! V to ride",
	["이미 가지고 있어요"] = "You already own this",
	["아직 판매 준비 중이에요 (이 서버의 판에는 게임패스 번호가 없어요)"] = "Not on sale yet (this server's version has no game pass ID)",
	["아직 판매 준비 중이에요"] = "Not on sale yet",
	["💰 은자 %s을(를) 받았어요"] = "💰 Received %s silver",
	["🧪 소환단 한 시간! 수련이 두 배"] = "🧪 One hour of Summoning Pill! Training doubled",
	["📜 심법 두루마리 %d장을 받았어요"] = "📜 Received %d manual scrolls",
	["을(를) 얻었어요! 고마워요"] = " obtained! Thank you",
	["⚔ 배틀그라운드 몫 💰 %s 은자를 받았어요"] = "⚔ Received 💰 %s silver as your Battleground share",
	["⚔ 배틀그라운드에서 "] = "⚔ In the Battleground, defeated ",
	["명을 쓰러뜨렸다! "] = " players! ",
	["...아직 이르다. %s에 이르거든 다시 오너라."] = "...Too early. Come back when you reach %s.",
	["...해와 달을 쥐려면 먼저 세상의 처음을 알아야 한다. %s을(를) 익히고 다시 오너라."] = "...To hold the sun and moon, you must first know the beginning of the world. Learn %s and come back.",
	["...극은 한 번의 삶으로는 닿지 않는다. "] = "...The Apex isn't reached in a single life. ",
	["...초월은 아무에게나 열리지 않는다. "] = "...Transcendence doesn't open to just anyone. ",
	[". 시련을 청하려면 "] = ". To request the trial, bring ",
	[", 배우려면 "] = "; to learn it, ",
	["을(를) 가져오너라."] = ".",
	["...깊은 잠에 든 노인은 깨지 않는다. 환생을 %d번 거친 혼이라야 이 꿈에 들어설 수 있을 듯하다."] = "...The old man in deep sleep won't wake. It seems only a soul reborn %d times can enter this dream.",
	["먼저 내 분신을 꺾어라."] = "First defeat my clone.",
	["제자가 되고 싶다면 시험을 넘어라. "] = "If you want to be my disciple, pass the test. ",
	[" 준비가 되면 다시 말을 걸어라. (다시 T를 누르면 시험이 시작된다)"] = "  Talk to me again when you're ready. (Press T again to start the test)",
	["[권왕] 장로 만들기 오류:"] = "[Fist King] Elder creation error:",
	["🗿 사람 모양 돌"] = "🗿 Man-Shaped Stone",
	["이미 이룬 자"] = "Already Achieved",
	["...돌은 말이 없다. 이미 궁극을 이룬 사람에게 이 돌이 더 줄 것은 없다."] = "...The stone is silent. It has nothing more to give one who has achieved the ultimate.",
	["아직 이르다"] = "Too Early",
	["...돌은 말이 없다. 다만 손바닥을 대면 차가운 울림이 전해진다. 이 길은 환생을 %d번 거친 혼에게만 열린다 (지금 %d번)."] = "...The stone is silent. But when you lay your palm on it, a cold resonance comes through. This path opens only to a soul reborn %d times (now %d).",
	["기운이 모자라다"] = "Not Enough Energy",
	["...돌 속에서 셋의 빈자리가 느껴진다. 극 권법 셋 (극 일월 · 극 공백 · 극 광속)을 모두 익히고 오너라. 아직 "] = "...You feel three empty places in the stone. Learn all three Apex styles (Apex Sun-Moon · Apex Null · Apex Lightspeed) and come back. Still missing: ",
	["바칠 것이 모자라다"] = "Not Enough to Offer",
	["...돌 앞에 은자를 바쳐야 길이 열린다. 💰 %s 은자. 지금 가진 것으로는 닿지 않는다."] = "...Silver must be offered before the stone to open the way. 💰 %s silver. What you have isn't enough.",
	["길이 열린다"] = "The Way Opens",
	["💰 %s 은자를 바쳤다. 돌이 낮게 울리며 발밑이 꺼진다. 어두운 동굴 속 제단에서, 극 권법을 하나씩 장착해 세 대좌에 기운을 보내라."] = "You offered 💰 %s silver. The stone hums low and the ground gives way. At the altar in the dark cave, equip the Apex styles one at a time and send their energy to the three pedestals.",
	["🗿 돌이 다시 길을 연다"] = "🗿 The stone opens the way again",
	["이미 궁극을 얻었어요"] = "You've already gained the ultimate",
	["🌑 극 권법 (극 일월 · 극 공백 · 극 광속) 하나를 장착하고 오세요"] = "🌑 Equip an Apex style (Apex Sun-Moon · Apex Null · Apex Lightspeed) and come back",
	[" · 지금: "] = "  · now: ",
	["의 기운은 이미 보냈어요. 다른 극 권법을 장착하세요"] = "'s energy has already been sent. Equip another Apex style",
	["🌑 이 대좌에는 이미 기운이 들어 있어요"] = "🌑 This pedestal already holds energy",
	["🌠 %s의 기운을 보냈다 (%d / 3)"] = "🌠 Sent the energy of %s (%d / 3)",
	["[권왕] 목인 세우기 오류:"] = "[Fist King] Dummy placement error:",
