	["가짐 (늘 켜져 있다)"] = "Owned (always on)",
	["자동 뽑기: 두루마리나 은자가 모자라요"] = "Auto draw: not enough scrolls or silver",
	["🔁 자동: 켜짐"] = "🔁 Auto: on",
	["🔁 자동: 꺼짐"] = "🔁 Auto: off",
	["🔁 자동 뽑기 끝: "] = "🔁 Auto draw finished: ",
	["🔁 자동 뽑기: [%s] 등장! (새로 얻거나 오른 심법 %d)"] = "🔁 Auto draw: [%s] appeared! (%d manuals new or upgraded)",
	["📜 1번 뽑기"] = "📜 Draw 1",
	["📜 10번 뽑기"] = "📜 Draw 10",
	["빼기"] = "Remove",
	["끼우기"] = "Equip",
	["💠 올리기"] = "💠 Upgrade",
	["확률: "] = "Odds: ",
	["  ·  %d번 안에 전설 이상이 한 번은 나온다"] = "   ·  Legendary or better guaranteed within %d draws",
	["📜 두루마리 <b>%d</b>개 · <font color=\"#96E6FF\">💠 천정 %s (💠 올리기: 고른 심법을 확정으로 한 등급 위로)</font>\n<font color=\"#FFD25A\">전설 보장까지 %d번</font>  <font color=\"#C8B9A5\">(두루마리가 없으면 한 번에 💰 %s)</font>"] = "📜 Scrolls <b>%d</b> · <font color=\"#96E6FF\">💠 Sky gems %s (💠 Upgrade: raise the selected manual one grade, guaranteed)</font>\n<font color=\"#FFD25A\">%d draws until guaranteed Legendary</font>  <font color=\"#C8B9A5\">(without scrolls, 💰 %s per draw)</font>",
	["<b>%d칸</b>\n<font color=\"#FFD25A\">🔒 📜 심법 넷째 칸 게임패스</font>"] = "<b>Slot %d</b>\n<font color=\"#FFD25A\">🔒 📜 Fourth Manual Slot game pass</font>",
	["<b>%d칸</b>\n"] = "<b>Slot %d</b>\n",
	["<b>%d칸</b>\n<font color=\"#9A8C7A\">비어 있음 (아래에서 끼우기)</font>"] = "<b>Slot %d</b>\n<font color=\"#9A8C7A\">Empty (equip from below)</font>",
	["✅ 빼기"] = "✅ Remove",
	["천상 (끝)"] = "Heavenly (max)",
	["<font color=\"#8A7C6A\">%s %s · %s (아직 없음)</font>"] = "<font color=\"#8A7C6A\">%s %s · %s (not owned)</font>",
	["🌌 빛깔: 켜짐"] = "🌌 Hue: on",
	["💠 천정 %s  ·  천상계의 적·보스·운석 수호수가 떨어뜨린다%s  ·  초월 재료 %s"] = "💠 Sky gems %s  ·  dropped by heavenly enemies, bosses and meteor guardians%s  ·  transcendence materials %s",
	["  ·  ✨ 영약 %d초"] = "   ·  ✨ Elixir %d s",
	["✔ 이 권법은 완료"] = "✔ Done for this style",
	["✔ 가짐"] = "✔ Owned",
	["장신구 권법만"] = "Accessory styles only",
	["🌌 빛깔: 꺼짐"] = "🌌 Hue: off",
	["🚪 나가기"] = "🚪 Leave",
	["🗼 천층탑 %d층%s  ·  최고 %d층"] = "🗼 Tower floor %d%s  ·  best floor %d",
	["🌀 구름 미궁 %d / %d  ·  %s %s%s"] = "🌀 Cloud Maze %d / %d  ·  %s %s%s",
	["  ✓ 다음 방으로"] = "   ✓ To the next room",
	["체력 %d%%  ·  남은 %d:%02d  ·  내 기여 %.1f%%%s"] = "HP %d%%  ·  %d:%02d left  ·  my contribution %.1f%%%s",
	[" (%d위)"] = "  (#%d)",
	["아직 아무도 치지 않았다"] = "No one has hit it yet",
	["%d / %d초"] = "%d / %d s",
	["%s  ·  %s  ·  %s  ·  ⏱ %d초"] = "%s  ·  %s  ·  %s  ·  ⏱ %d s",
	["🎮 조작"] = "🎮 Controls",
	["⚔ 싸움"] = "⚔ Combat",
	["📈 강해지기"] = "📈 Getting Stronger",
	["🧘 수련"] = "🧘 Training",
	["🥋 권법·사부"] = "🥋 Styles & Masters",
	["🏔 지상"] = "🏔 The Land",
	["☁ 천상계"] = "☁ Heavenly Realm",
	["♻ 환생·후반"] = "♻ Rebirth & Endgame",
	["💰 상점·기타"] = "💰 Shop & Misc",
	["권장 "] = "Recommended ",
	["보스 "] = "Boss ",
	["<b>🎮 조작</b>"] = "<b>🎮 Controls</b>",
	["• 클릭: 연타 (네 번까지 이어진다) · Z: 강타 (강한 한 방, 천룡장은 누르고 있다 놓기)"] = "• Click: combo (chains up to four) · Z: heavy strike (one strong blow; for the Dragon Palm, hold and release)",
	["• E: 기술 · R: 기술 (숙련 %d) · G: 오의 (숙련 %d, 내공 가득) · X: 초 오의 (초월·환생 권법)"] = "• E: skill · R: skill (mastery %d) · G: Secret Art (mastery %d, full Ki) · X: Ultimate Art (Transcendent and rebirth styles)",
	["• F: 막기. <b>맞기 직전에 누르면 흘리기</b> — 피해 없이 흘려 내고 상대가 휘청인다"] = "• F: block. <b>Press right before a hit to deflect</b> — take no damage and stagger the attacker",
	["• Q: 대시 (잠깐 무적) · 공중에서 Space: 두 번 뛰기 · C (또는 Ctrl): 달리기"] = "• Q: dash (briefly invincible) · Space in the air: double jump · C (or Ctrl): run",
	["• T (가까이): 사부·수련·상점·문 · H: 금창약 · Tab: 능력치 · M: 지도"] = "• T (nearby): masters, training, shops, gates · H: Wound Salve · Tab: stats · M: map",
	["• 휴대폰·태블릿: 오른쪽 아래 둥근 단추. 가운데 👊 공격, 안쪽 고리 💥 강타 · 💨 대시 · 🛡 막기, 바깥 고리 E · R · G · X"] = "• Phone/tablet: round buttons at the bottom right. Center 👊 attack, inner ring 💥 heavy · 💨 dash · 🛡 block, outer ring E · R · G · X",
	["  단추가 흐리면 아직 쓸 수 없다 (대기 중이거나 🔒 잠김). 수련할 때는 가운데에 지금! 단추가 뜬다"] = "   A dimmed button can't be used yet (cooling down or 🔒 locked). While training, a Now! button appears in the center",
	["• 왼쪽 위 ☰ 단추로 메뉴를 펴고 접는다: 권법·지도·능력치·업적·만물상 (물건·심법·탈것·꾸미기·로벅스)·도움말 (수련 안내도 여기)"] = "• Open and close the menu with the ☰ button at the top left: Styles, Map, Stats, Achievements, General Store (items, manuals, mounts, cosmetics, Robux), Help (training guide is here too)",
	["• 오른쪽 아래 구석의 작은 글자는 게임 판 번호다 (업데이트가 들어왔는지 볼 때)"] = "• The small text in the bottom right corner is the game version (to check whether an update has arrived)",
	["• 메뉴의 🌿 그래픽 단추: 가볍게로 바꾸면 작은 풀·꽃·덤불을 내 화면에서 걷어 덜 끊긴다 (휴대폰은 처음부터 가볍게)"] = "• 🌿 Graphics button in the menu: switch to Light to remove small grass, flowers and bushes from your screen for less lag (phones start on Light)",
	["<b>⚔ 연타는 박자</b>"] = "<b>⚔ Combos are about rhythm</b>",
	["• 앞 동작이 끝나 갈 즈음 눌러야 이어진다. 딱 맞으면 <b>정타</b> (피해 +15%, 세 번 이으면 연속 정타 +30%)"] = "• Press as the previous move is finishing to chain. Hit it exactly for a <b>clean hit</b> (damage +15%, three in a row for chain clean hits +30%)",
	["• 너무 일찍 마구 누르면 <b>흐트러진다</b>: 연타가 끊기고 적이 읽어서 막고 흘린다"] = "• Mash too early and you'll <b>falter</b>: the combo breaks and enemies read and deflect it",
	["• 숙련 6 각성: 연타 마무리가 상대를 하늘로 띄운다 → 두 번 뛰고 공중에서 클릭 = 공중 연격"] = "• Mastery 6 awakening: the combo finisher launches the target → double jump and click in the air = air combo",
	["<b>몸놀림</b>"] = "<b>Movement</b>",
	["• 대시 바로 뒤 클릭: <b>돌진 일격</b> · 공중에서 클릭: <b>낙하격</b>"] = "• Click right after a dash: <b>Rushing Strike</b> · click in the air: <b>Falling Strike</b>",
	["• 흘리기 바로 뒤 클릭: <b>반격</b> (크게 아프고 균형을 많이 깎는다)"] = "• Click right after a deflect: <b>Counter</b> (heavy damage and big balance damage)",
	["• 맞기 직전에 대시로 피하면 <b>간파</b>: 상대가 굳고, 곧바로 클릭하면 반격"] = "• Dodge with a dash right before a hit for a <b>Read</b>: the attacker freezes; click right away to counter",
	["<b>합을 겨루는 법</b>"] = "<b>How to Trade Blows</b>",
	["• 🟧 균형 막대: 막을 때마다 차오른다. 꽉 차면 <b>파훼</b> — 무릎이 꺾여 큰 피해를 받는다"] = "• 🟧 Balance bar: fills each time you block. When full, <b>Guard Break</b> — your knees buckle and you take heavy damage",
	["• 적의 무기가 반짝이면 곧 휘두른다 — 흘릴 때다"] = "• When an enemy's weapon glints, it's about to swing — time to deflect",
	["• <b>붉게 빛나는 공격</b>은 막을 수 없다. 대시로 피해라"] = "• <b>Attacks glowing red</b> can't be blocked. Dodge with a dash",
	["• 서로 같은 순간에 치면 <b>격돌</b>: 주먹이 부딪혀 둘 다 튕겨 난다"] = "• Strike at the same moment and you <b>clash</b>: fists collide and both of you bounce back",
	["<b>전투력</b>"] = "<b>Power</b>",
	["• 머리 위 숫자. 체력·피해·기술 세기를 함께 센다. 내 전투력은 능력치 창에 있다"] = "• The number overhead. It counts HP, damage and skill strength together. Your power is in the stats window",
	["• 내가 상대보다 %.1f배 넘게 세면 덜 아프고, %.1f배 넘으면 휘청이지 않고, %d배 넘으면 호신강기에 튕겨 나간다 (졸병만, 보스는 튕겨 내지 못한다)"] = "• If you're over %.1fx stronger than a foe you take less damage, over %.1fx you don't stagger, and over %dx they bounce off your Protective Aura (grunts only; bosses can't be repelled)",
	["• 지도의 권장 전투력: 빨강 위험 · 주황 버거움 · 초록 알맞음 · 회색 여유"] = "• Recommended power on the map: red dangerous · orange tough · green right · gray easy",
	["<b>📈 능력치는 싸움과 수련으로</b>"] = "<b>📈 Stats come from fighting and training</b>",
	["• 적을 쓰러뜨리면 그 적의 전투력만큼 네 능력치가 고루 오른다. <b>내 수준의 땅</b>에서 잡을 때 가장 알차다"] = "• Defeating an enemy raises all your stats according to its power. Hunting in <b>lands at your level</b> is most rewarding",
	["• 보스는 %d배, 정예는 %.1f배. 나보다 훨씬 센 적도 내 경지 몫의 %.1f배까지만"] = "• Bosses give %dx, elites %.1fx. Even much stronger enemies give at most %.1fx your realm's share",
	["• 수련: 박자를 맞추면 두 배. 이류부터 바위의 🔥 강화 수련 (%d배). 경지마다 새 수련이 열린다 (도움말 → 🧘 수련)"] = "• Training: hit the beat for double. From Second-Rate, 🔥 enhanced training at the boulder (%dx). Each realm opens new training (Help → 🧘 Training)",
	["<b>경지</b> (능력치 합으로 오른다. 오를 때마다 피해·체력이 크게 오른다)"] = "<b>Realms</b> (rise with your stat total. Damage and HP jump each time you rise)",
	["• 천외천 너머 (환생해야 하나씩 열린다): 혼원경 → 무량경 → 태허경 → 권왕"] = "• Beyond Beyond Heaven (one opens per rebirth): Primordial → Boundless → Great Void → Fist King",
	["<b>숙련 · 각성 · 깨달음</b>"] = "<b>Mastery · Awakening · Insight</b>",
	["• 그 권법으로 맞힐수록 숙련이 오른다. 숙련 %d에 R, %d에 오의(G), 6에 각성 (기술이 세지고 연타 마무리가 띄운다)"] = "• Mastery rises the more you hit with a style. R at mastery %d, Secret Art (G) at %d, awakening at 6 (stronger skills, combo finisher launches)",
	["%s (%s부터 · 💰 %s)"] = "%s (from %s · 💰 %s)",
	["• 숙련 %d인 권법은 깨달음으로 피해가 오른다 (상급·전설은 두 번 모두, 신화는 한 번만, 태초 이상은 오르지 않는다): %s"] = "• Styles at mastery %d gain damage through insight (Advanced and Legendary twice, Mythic once, Genesis and above not at all): %s",
	["<b>권법 등급</b>"] = "<b>Style Grades</b>",
	["• 다섯 등급: 상급 → 전설 → 신화 → 태초 → 윤회 (지존은 새 권법을 위해 비워 둔 자리)"] = "• Five grades: Advanced → Legendary → Mythic → Genesis → Rebirth (Supreme is reserved for new styles)",
	["• 권법이 변한 모습은 등급과 따로다: 진 (각성) · 초 · 극"] = "• A style's evolved forms are separate from grade: True (awakened) · Ultimate · Apex",
	["• 상급·전설 권법은 초 신권까지, 신화 이상 권법은 초와 극까지 변할 수 있다"] = "• Advanced and Legendary styles can evolve up to Ultimate; Mythic and above up to Ultimate and Apex",
	["<b>🎯 권법 시험장</b>"] = "<b>🎯 Style Testing Ground</b>",
	["• 메뉴 → 🎯 권법 시험장. 하늘에 떠 있는 큰 돌 마당에 작은 목인 다섯과 큰 목인 셋이 서 있다. 목인 머리 위에 초당 피해와 가장 센 한 대가 보인다. 사람끼리는 싸우지 않는다. 남쪽 붉은 문이나 같은 메뉴로 돌아온다"] = "• Menu → 🎯 Style Testing Ground. Five small dummies and three big dummies stand on a big stone yard floating in the sky. DPS and biggest hit show above each dummy. Players don't fight here. Return through the red gate to the south or the same menu",
	["• 서쪽 🛡 반격 코너: 흘리기 사범 셋이 천천히 박자 맞춰 친다. 맞아도 피해·경직·균형이 없다. 칠 때 막기를 막 잡으면 흘리기, 흘려 균형을 다 깎으면 무너져 반격할 틈. 붉은 공격은 피하기"] = "• West 🛡 Counter Corner: three deflect instructors strike slowly on a beat. No damage, stagger or balance loss. Block right as they strike to deflect; wear their balance down by deflecting and they collapse, opening a counter. Dodge red attacks",
	["• 동쪽 🎯 데미지 챌린지: 기둥에서 시작하면 3초 세고 20초 동안 챌린지 목인에게 준 피해를 모두 센다. 내 최고 기록은 저장되고, 이 서버 기록판에 다섯 명까지"] = "• East 🎯 Damage Challenge: start at the pillar, a 3-second count, then all damage to the challenge dummy for 20 seconds is counted. Your best is saved, and up to five names appear on this server's board",
	["<b>심법 · 천층탑</b>"] = "<b>Manuals · Thousand-Floor Tower</b>",
	["• 적과 보스가 떨어뜨리는 심법 두루마리를 펼치면 심법이 나온다. 세 칸에 끼우면 권법 전체를 받쳐 준다 (메뉴 → 만물상 → 📜 심법)"] = "• Open manual scrolls dropped by enemies and bosses to get manuals. Equip them in three slots to support your whole style (Menu → General Store → 📜 Manuals)",
	["• 마을 안 천층탑: 층마다 세기가 정해져 있고 열 층마다 보스. 처음 넘는 보스 층엔 두루마리와 큰 몫"] = "• The Tower in the village: each floor has a set strength with a boss every ten floors. Scrolls and big rewards the first time you clear a boss floor",
	["<b>이야기</b>"] = "<b>Story</b>",
	["• 화면 왼쪽의 이야기 목표를 따라가면 게임 전체를 차례로 배운다. 청운 장로에게 말을 걸면 다음 장을 받는다"] = "• Follow the story goals on the left of the screen to learn the whole game in order. Talk to Elder Cheongun for the next chapter",
	["<b>🥋 권법 얻기</b>"] = "<b>🥋 Getting Styles</b>",
	["• 처음엔 삼재권. 다른 권법은 <b>그 사부를 찾아가</b> T로 시험을 청하고, 넘으면 은자를 내고 배운다"] = "• You start with the Three Powers Fist. For other styles, <b>find their master</b>, request a test with T, pass it, then pay silver to learn",
	["• 배우는 값 (둘째부터): 💰 "] = "• Learning cost (from the second): 💰 ",
	["• 시험은 사부마다 다르다: 흘리기 · 버티기 · 제자 연무"] = "• Tests differ by master: deflecting · enduring · sparring with disciples",
	["• 권법 창의 📍 길 안내를 누르면 화면과 지도에 길잡이가 뜬다. 하늘로 솟은 빛기둥이 사부의 자리"] = "• Press 📍 Guide in the Styles window for a guide on screen and map. The pillar of light rising into the sky marks the master's spot",
	["<b>지상의 사부</b>"] = "<b>Masters of the Land</b>",
	["• %s %s — %s의 %s"] = "• %s %s — %s at %s",
	["<b>숨은 권법</b>"] = "<b>Hidden Styles</b>",
	["• 지도에 없는 사부와 특별한 조건으로 얻는 권법이 많다. 권법 창에서 잠긴 권법을 누르면 실마리가 나온다"] = "• Many styles come from masters not on the map or from special conditions. Click a locked style in the Styles window for a hint",
	["• 각성 권법(진): 원래 권법을 숙련 끝까지 올리고 두 번 깨달은 뒤 각성의 시련을 넘는다"] = "• Awakened (True) styles: max an original style's mastery, gain two insights, then pass the Awakening Trial",
	["• 초월 권법(초): 원래 권법과 그 진 권법을 숙련 20까지 + 천상 재료 → 숨은 초월의 사부"] = "• Transcendent (Ultimate) styles: an original style and its True style at mastery 20 + heavenly materials → hidden master of transcendence",
	["<b>🏔 지상 강호</b> (마을에서 멀수록 세다. 권장 전투력이 낮은 땅부터)"] = "<b>🏔 The Martial World</b> (stronger the farther from the village. Start with lands of lower recommended power)",
	["• 청운 마을 (안전): 청운 장로 · 사부 안내판 · 만물상 · 배틀그라운드 문 · 수련터 · 천층탑 · 천상 문"] = "• Cheongun Village (safe): Elder Cheongun · master notice board · General Store · Battleground gate · training spots · Thousand-Floor Tower · Heaven Gate",
	["• 상급 수련장 (안전, 마을 북동): 금종조·천근추·주천 운기·허공답보 수련"] = "• Advanced Training Grounds (safe, northeast of the village): Golden Bell, Thousand-Pound, Grand Circulation and Sky Walk training",
	["• 🏮 주막 (강호 곳곳 열 곳, 지도에 등): 탁자에서 T를 누르면 쉬고, 그 주막이 깨어날 곳이 된다 (쓰러지면 거기서 일어난다). 마을 객잔에서 쉬면 다시 마을로"] = "• 🏮 Taverns (ten across the world, lanterns on the map): press T at the table to rest; that tavern becomes your respawn point. Rest at the village inn to respawn in the village again",
	[" — 보스 "] = "  — boss ",
	["• 사부 가는 길목 (강호 들판): 창병 · 곤봉 산적 · 쌍도 자객. 아주 먼 곳엔 흑영 자객 · 철갑 무사"] = "• On the way to masters (Martial World Fields): spearmen · club bandits · twin-saber assassins. Far away: black shadow assassins · armored warriors",
	["• 비급 조각 다섯이 강호 곳곳에 숨어 있다 (지도에 없다)"] = "• Five manual fragments are hidden across the world (not on the map)",
	["• 낮과 밤이 돈다 (낮 10분 · 밤 2분). 일월신권은 낮과 밤에 따라 세기가 바뀐다"] = "• Day and night cycle (day 10 min · night 2 min). The Sun-Moon Fist's strength changes with day and night",
	["<b>☁ 천상계</b>"] = "<b>☁ Heavenly Realm</b>",
	["• %s에 오르면 마을 안 <b>천상 문</b>이 열린다. 지도는 하늘에 오르면 천상 지도로 바뀐다"] = "• Reach %s and the <b>Heaven Gate</b> in the village opens. The map switches to the heavenly map when you go up",
	["• 천궁 (안전): 천상 객잔 · 천정 상점 · 운류자 (운류장) · 구름 미궁 문 🌀 · 천공 투기장 문 ⚔"] = "• Sky Palace (safe): Heavenly Inn · sky gem shop · Drifting Cloud Master (Drifting Cloud Palm) · Cloud Maze gate 🌀 · Sky Arena gate ⚔",
	["• 천정 💠: 천상의 적과 보스가 떨어뜨린다. 천정 상점에서 두루마리·영약·천정단·탈것을 산다"] = "• Sky gems 💠: dropped by heavenly enemies and bosses. Buy scrolls, elixirs, gem pills and mounts at the sky gem shop",
	["<b>섬</b> (권장 전투력이 낮은 섬부터)"] = "<b>Islands</b> (start with islands of lower recommended power)",
	["<b>천상 재료</b> (초월 권법에 든다. 한 번에 많아야 둘)"] = "<b>Heavenly Materials</b> (for Transcendent styles. At most two at once)",
	["• 구름 미궁: 방을 넘어 미궁의 주인을 꺾는다. 들어간 사람의 세기에 맞춰 적이 선다"] = "• Cloud Maze: clear rooms and defeat the maze's master. Enemies scale to whoever enters",
	["• 천공 투기장: 여럿이 함께 하늘의 재앙 천겁을 쓰러뜨린다"] = "• Sky Arena: team up to defeat Cheongeop, the calamity of the heavens",
	["<b>♻ 환생</b>"] = "<b>♻ Rebirth</b>",
	["• 천외천에 오르면 천상 윤회대의 제단에서 환생한다 (모두 %d번). 경지는 삼류부터지만 얻는 능력치가 커진다"] = "• Once at Beyond Heaven, be reborn at the altar on the Heavenly Rebirth Terrace (%d times in all). Your realm restarts at Third-Rate but stat gains grow",
	["• 권법·숙련·깨달음·심법·탈것·은자는 그대로 남는다. 환생할 때마다 천외천 너머 경지가 하나씩 열린다"] = "• Styles, mastery, insights, manuals, mounts and silver stay. Each rebirth opens one more realm beyond Beyond Heaven",
	["• 환생 한 번에 공덕 둘. 능력치 창 → ♻ 환생 특전에서 특전을 산다 (언제든 되돌려 다시 고를 수 있다)"] = "• Two merits per rebirth. Buy perks in the stats window → ♻ Rebirth Perks (refund and re-pick anytime)",
	["<b>☯ 윤회의 시련</b>"] = "<b>☯ Rebirth Trials</b>",
	["• n번째 환생 뒤 %s에 다시 오르면 n번째 시련이 열린다. 전생의 그림자를 꺾으면 공덕 하나와 환생 권법 하나"] = "• After your nth rebirth, reach %s again and the nth trial opens. Defeat your past-life shadow for one merit and one rebirth style",
	["• 환생 권법: 윤회권 → 업화권 → 무상권 → 권왕신권 (모두 초 오의 X가 있다)"] = "• Rebirth styles: Rebirth Fist → Karmic Fire Fist → Impermanence Fist → Fist King Fist (all have an Ultimate Art X)",
	["<b>끝까지</b>"] = "<b>To the End</b>",
	["• 초월 권법(초) · 극 일월신권 (일월신권 숙련 20, 세 번 환생) · 마지막 경지 권왕"] = "• Transcendent (Ultimate) styles · Apex Sun-Moon Fist (Sun-Moon Fist mastery 20, three rebirths) · the final realm, Fist King",
	["• 업적과 칭호 (메뉴 → 업적): 이룬 만큼 은자와 칭호가 붙는다"] = "• Achievements and titles (Menu → Achievements): earn silver and titles as you complete them",
	["<b>💰 은자로 사는 것</b>"] = "<b>💰 Bought with Silver</b>",
	["• 만물상 (마을): 금창약 (H) · 소환단 (수련 2배) · 대환단 (능력치)"] = "• General Store (village): Wound Salve (H) · Summoning Pill (training x2) · Great Restoration Pill (stats)",
	[" (🏆 신화 업적 전용)"] = "  (🏆 mythic achievement only)",
	[" (💠 천정 전용 · 천궁 상점)"] = "  (💠 sky gems only · Sky Palace shop)",
	[" (처음부터)"] = "  (from the start)",
	["• 탈것: "] = "• Mounts: ",
	["<b>💎 게임패스</b> (로벅스. 한 번 사면 영구)"] = "<b>💎 Game Passes</b> (Robux. Buy once, keep forever)",
	["<b>⚔ 들판 PvP</b>"] = "<b>⚔ Field PvP</b>",
	["• 마을·사당·사부의 자리 같은 안전한 곳 밖에서는 사람끼리도 싸운다"] = "• Outside safe places like villages, shrines and master seats, players fight each other too",
	["• 처음엔 끌 수 없다 (🔒). 사람에게 한 번 쓰러지면 메뉴의 ⚔ PvP 단추로 끄고 켤 수 있다 (싸우는 중에는 못 바꾸고, 한 번 바꾸면 잠시 기다린다)"] = "• You can't turn it off at first (🔒). Once defeated by a player, you can toggle it with the ⚔ PvP button in the menu (not mid-fight, with a short wait after each change)",
	["<b>⚔ 배틀그라운드</b> (모두 같은 힘으로 겨루는 곳)"] = "<b>⚔ Battleground</b> (everyone fights with equal strength)",
	["• 마을의 배틀그라운드 문 (예전 비무대 자리)이나 메뉴 → ⚔ 배틀그라운드로 간다. 돌아올 때는 메뉴 → 🏠 메인 월드로"] = "• Go through the village's Battleground gate (the old dueling stage) or Menu → ⚔ Battleground. To return, Menu → 🏠 Main World",
	["• 모두 체력 %d, 공격력도 같다. 메인 월드에서 익힌 권법만 쓴다 (기술은 모두 열려 있다). 좋은 권법이 아주 조금 세다"] = "• Everyone has %d HP and the same attack. Only styles learned in the main world can be used (all skills unlocked). Better styles are very slightly stronger",
	["• 처음엔 대기실 (싸움이 없다): 권법을 고르고, 수련 목인으로 시험하고, 다음 맵에 투표하고, '⚔ 싸움터로 들어가기'. 메뉴 → 🏯 대기실로 나올 수 있다 (싸운 직후는 안 된다)"] = "• You start in the lobby (no fighting): pick a style, test on training dummies, vote for the next map, then '⚔ Enter the arena'. Menu → 🏯 Lobby to come back out (not right after fighting)",
	["• 한 대는 %d까지, 1초에 받는 피해는 %d까지: 쓰러지기까지 적어도 %d초. 들어가거나 일어나면 %d초 보호. 오래 묶이면 잠깐 버틴다"] = "• Max %d per hit; per 1s at most %d damage: at least %d seconds to go down. %d seconds of protection when entering or getting up. Brief resistance if held too long",
	["• 맵은 %d분마다 바뀐다: %s. 한 판에 가장 많이 쓰러뜨린 사람이 이긴다"] = "• The map changes every %d minutes: %s. Most takedowns in a round wins",
	["• 쓰러뜨릴 때마다 은자 (경지가 높을수록 더), 판을 이기면 더. 메인 월드로 돌아오면 받는다. 모두 %d명을 쓰러뜨리면 무쌍신권"] = "• Silver for each takedown (more at higher realms), more for winning a round. Collected on returning to the main world. Defeat %d players in total for the Peerless Fist",
	["<b>그 밖에</b>"] = "<b>Other</b>",
	["• 하늘에서 별똥별이 떨어지면 가 보라 (천상)"] = "• When a shooting star falls from the sky, go check it out (Heavenly)",
	["🎮 조작법 다시 보기"] = "🎮 View Controls Again",
	["① 금빛 고리가 줄어든다  ② 고리가 가운데 흰 원에 겹칠 때 Space  ③ 딱 맞으면 완벽 (두 배)"] = "① The golden ring shrinks  ② Press Space when it overlaps the white circle in the middle  ③ A perfect hit is Perfect (double)",
	["① 파란 원이 커졌다 작아졌다 한다  ② 가장 커졌을 때 Space  ③ 숨 쉬듯 천천히"] = "① The blue circle grows and shrinks  ② Press Space when it's biggest  ③ Slowly, like breathing",
	["① 화살표를 따라 빛나는 고리로 달린다  ② 고리를 지나면 저절로 오른다  ③ C (또는 Ctrl)로 달리면 빠르다"] = "① Follow the arrow and run to the glowing ring  ② Passing the ring raises stats automatically  ③ Run with C (or Ctrl) to go faster",
	["① 나무팔이 들어오며 원이 밝아진다  ② 가장 밝게 번쩍일 때 Space  ③ 실전의 흘리기 박자와 같다"] = "① The circle brightens as the wooden arm comes in  ② Press Space when it flashes brightest  ③ Same timing as deflecting in real fights",
	["① 흰 바늘을 초록 칸 안에 붙잡는다  ② 누르면 오른쪽, 놓으면 왼쪽  ③ 짧게 톡톡 누르는 게 요령"] = "① Keep the white needle inside the green zone  ② Press to tip right, release to tip left  ③ The trick is short taps",
	["① 쇠모래가 번쩍일 때 Space  ② 바위 들기보다 조금 빠르다  ③ 근골이 크게 오른다"] = "① Press Space when the iron sand flashes  ② A bit faster than Boulder Lift  ③ Raises Might a lot",
	["① 기가 몸을 돌며 커진다  ② 가장 커졌을 때 Space  ③ 내공과 체력이 함께 오른다"] = "① Ki circles your body and grows  ② Press Space when it's biggest  ③ Raises Ki and HP together",
	["마음속 마귀와 싸운다. 마구 치지 말고 F로 흘린 뒤 받아치자"] = "Fight the demon in your heart. Don't flail; deflect with F and counter",
	["<b>🧘 수련 안내</b>"] = "<b>🧘 Training Guide</b>",
	["• 수련터에 가서 T를 누르면 시작한다. 움직이면 끝난다"] = "• Go to a training spot and press T to start. Moving ends it",
	["• 박자가 맞으면 <b>좋음</b>, 딱 맞으면 <b>완벽</b> (두 배). 놓쳐도 잃는 것은 없다"] = "• Hit the beat for <b>Good</b>, exactly for <b>Perfect</b> (double). Missing costs nothing",
	["• 기력 같은 것은 없다. 얼마든지 수련할 수 있다"] = "• There's no stamina. Train as much as you like",
	["• 이류부터 <b>🔥 강화 수련</b> (바위에서): 박자가 빠르지만 오르는 능력치가 %d배"] = "• From Second-Rate, <b>🔥 enhanced training</b> (at the boulder): faster beat, but %dx stats",
	["• 경지가 오를수록 한 번에 오르는 능력치가 커진다"] = "• The higher your realm, the more stats each rep gives",
