	["호혼도약"] = "Fox Spirit Leap",
	["몸이 푸른 여우 혼령이 되어 둘레의 적 사이를 활을 그리며 네 번 뛰어 할퀸다 (무적). 마지막에 하늘에서 큰 여우 혼령이 한가운데로 내리 덮친다"] = "Become a blue fox spirit and leap in arcs between nearby enemies four times, clawing them (invincible). At the end a giant fox spirit pounces from the sky onto the center",
	["흑염발도"] = "Black Flame Iaido",
	["칼을 허리에 거두고 숨을 죽였다가, 눈에 보이지 않게 앞으로 18칸을 지나며 벤다 (무적). 한 박자 늦게 지나온 길에 베인 자국이 줄줄이 그어지며 검은 불꽃이 터진다"] = "Sheathe the blade at your hip and hold your breath, then cut through 18 studs ahead unseen (invincible). A beat later, slash marks appear one after another along your path and black flames burst",
